(window.GIM_TP=window.GIM_TP||{})["Ketubot.1"]={"from":199,"a":[[["בלאותיה קיימין","תני תנא קמיה דרב נחמן זינתה הפסידה בלאותיה קיימין א\"ל אם היא זינתה כליה מי זנאי תני לא הפסידה בלאותיה קיימין","אמר רבה בר בר חנה א\"ר יוחנן זו דברי רבי מנחם סתימתאה אבל חכמים אומרים זינתה לא הפסידה בלאותיה קיימין:","אם מתחלה נשאה כו': אמר רב הונא אילונית אשה ואינה אשה אלמנה אשה גמורה","אילונית אשה ואינה אשה הכיר בה יש לה כתובה לא הכיר בה אין לה כתובה אלמנה אשה גמורה בין הכיר בה בין לא הכיר בה יש לה כתובה","ורב יהודה אומר אחת זו ואחת זו אשה ואינה אשה הכיר בה יש לה כתובה לא הכיר בה אין לה כתובה","מיתיבי כנסה בחזקת שהיא כן ונמצאת שהיא כן יש לה כתובה הא סתמא אין לה כתובה","לא תימא הא סתמא אין לה כתובה אלא אימא כנסה בחזקת שאינה כן ונמצאת שהיא כן אין לה כתובה","אבל סתמא מאי אית לה אדתני בחזקת שהיא כן ונמצאת שהיא כן יש לה כתובה לשמעינן סתמא וכ\"ש הא","ועוד תני כנסה בידוע ונמצאת בידוע יש לה כתובה כנסה סתם אין לה כתובה תיובתא דרב הונא","רב הונא מתני' אטעיתיה הוא סבר מדקא מפליג באילונית ולא קמפליג באלמנה מכלל דאלמנה אפי' בסתמא נמי אית לה ולא היא כי קתני לה לאלמנה אפלוגתא דאילונית קאי:","\u0001הדרן עלך אלמנה ניזונת\u0002","מתני׳ \u0001הנושא\u0002 את האשה ופסקה עמו כדי שיזון את בתה חמש שנים חייב לזונה חמש שנים","ניסת לאחר ופסקה עמו כדי שיזון את בתה חמש שנים חייב לזונה חמש שנים לא יאמר הראשון לכשתבא אצלי אזונה אלא מוליך לה מזונותיה למקום שאמה","וכן לא יאמרו שניהם הרי אנו זנין אותה כאחד אלא אחד זנה ואחד נותן לה דמי מזונות","ניסת הבעל נותן לה מזונות והן נותנין לה דמי מזונות מתו בנותיהן ניזונות מנכסים בני חורין והיא ניזונת מנכסים משועבדים מפני שהיא כבעלת חוב","הפקחים היו כותבים ע\"מ שאזון את בתך חמש שנים כל זמן שאת עמי:","\u0001גמ׳\u0002 אתמר האומר לחבירו חייב אני לך מנה רבי יוחנן אמר חייב ור\"ל אמר פטור","ה\"ד אי דאמר להו אתם עדיי מ\"ט דר\"ל דקפטר אי דלא אמר להו אתם עדיי מ\"ט דרבי יוחנן דקמחייב","לעולם דלא קאמר להו אתם עדיי והכא במאי עסקינן דא\"ל חייב אני לך מנה בשטר רבי יוחנן אמר חייב אלימא מילתא דשטרא כמאן דאמר להו אתם עדים דמי ר\"ל אמר פטור לא אלימא מילתא דשטרא","תנן הנושא את האשה ופסקה עמו לזון את בתה חמש שנים חייב לזונה חמש שנים מאי לאו כי האי גוונא"],[[0,"בלאותיה קיימין","בלאות שהן קיימין לא הפסידה:"],[2,"זו דברי רבי מנחם","הא סתמא דתני תנא קמיה דר\"נ הפסידה ר' מנחם אמרה דסתימתאה הוא הרבה משמועותיו נשנו סתם במשנה ובברייתא:"],[3,"אשה ואינה אשה","פעמים היא כאשתו פעמים אינה כאשתו:"],[3,"אלמנה","לכ\"ג:"],[6,"בחזקת שהיא כן","שהודיעתו שהיא אלמנה:"],[6,"הא סתמא","הוה ליה לא הכיר בה:"],[7,"בחזקת שאינה כן","שהטעתו ואמרה לו לא נתקדשתי לאדם מעולם:"],[8,"אבל סתמא","שלא התנה עמה ומיהו לא הכיר בה יש לה:"],[9,"כנסה בידוע","שהיא אלמנה:"],[10,"מדקא מפליג באיילונית","דאם מתחלה נשאה לשם איילונית יש לה:"],[10,"כי קתני לה לאלמנה","וקאמר יש לה כתובה:"],[10,"אפלוגתא דאיילונית קאי","לאחר שחילק באיילונית ופירש הכיר בה יש לה כתובה שנאה לאלמנה אצלה וקאמר אף אלמנה נמי שהכיר בה ונשאה לשם אלמנה יש לה כתובה:"],[11,"","הדרן עלך אלמנה ניזונת"],[12,"מתני' הנושא את האשה: לזון את בתה","שהיה לה מאיש אחר:"],[13,"נשאת","האם לאחר שגירשה הראשון:"],[13,"לכשתבא אצלי","כלומר אם הייתי מקיים את אמה הייתי זנה:"],[15,"בנותיהן נזונות מנכסים בני חורין","ולא ממשועבדים דתנן (גיטין דף מח:) אין מוציאין לאכילת פירות ולשבח קרקעות ולמזון האשה והבנות מנכסים משועבדים:"],[15,"והיא נזונת","אותה הבת:"],[15,"שהיא כבעלת חוב","שיש לה עליהן שטר מזונות:"],[16,"נשאת","האם לאחר שגירשה הראשון. לכשתבא אצלי. כלומר אם הייתי מקיים את אמה הייתי זנה:"],[16,"כל זמן שאת עמי","ולא אם אמות או תמותי או אגרשיך:"],[18,"גמ' אי דאמר להו","לשומעין:"],[18,"אתם עדיי","שאני מודה לו:"],[18,"מאי טעמא דר\"ל דפטר","הא אנן תנן בסנהדרין (דף כט:) עד שיאמרו בפנינו הודה לו אלמא הודה בפני עדים חייב:"],[18,"אי לא אמר להו","לשומעין אתם עדיי:"],[19,"מאי טעמא דרבי יוחנן","הא קיימא לן התם בסנהדרין וצריך שיאמר אתם עדיי:"],[19,"ה\"ג לעולם דלא אמר להו אתם עדיי והכא במאי עסקינן בשטרא","שמסר לו שטר בפנינו וכתוב בו אני חייב לך מנה ואע\"פ שכתב ידו הוא הואיל ולא חתם פטור והא דתנן (לעיל כתובות דף כא.) הוציא עליו כתב ידו שהוא חייב לו גובה מנכסים בני חורין כגון שחתם בו אני פלוני לויתי מנה מפלוני כדמוכח בפרק האשה שנתארמלה (שם) דאמר אביי לכתוב חתימת ידיה אחספא אבל אמגילתא לא מאי טעמא דלמא משכח ליה כו' ותנן הוציא עליו כתב ידו כו' אלמא בחתימת ידיה קמיירי אבל הכא הכי כתב ליה חייב אני לך מנה ולא חתם בו:"],[19,"אלימא מלתא דשטרא","הואיל ובפני עדים מסר לו:"],[20,"מאי לאו כי האי גוונא","[מה עדות יש לה לאחר זמן בדבר זה לאו כי האי גוונא] שמוסר לה שטר בפני עדים וכתוב בו פלוני קבל עליו כך ואין שם לא קנין ולא חתימה דאי הוה שטר חתום בידה מאי למימרא:"]],[[15,"מתני' הנושא את האשה: נשאת הבעל חייב במזונותיה","סלקא דעתין דלא מיחייב דכיון דיש לה מזונות מאחר כאילו התנה עמה על מנת שאין לה עליו מזונות קמ\"ל:"],[15,"והן נותנין לה דמי מזונות","איצטריך ס\"ד דלא פסקו אלא כל זמן שלא נשאת:"],[15,"והיא ניזונת מנכסים משועבדים","אע\"ג דלעיל (כתובות דף נא: ושם) תניא חמשה גובין מן המשוחררים המקבל עליו לזון את בת אשתו למ\"ד בהניזקין (גיטין נא.) קצובין לחוד טרפה לא קשיא מידי דהכא משום קצבה ולמ\"ד כתובין בעינן מוקי לה בשקנו מידו וא\"ת למ\"ד קצובין אע\"פ שאין כתובין אמאי לא חשיב להו קצבה למזון הבנות דהוי עד דתבגרן ומיהו מן האב אין קשה כל כך דלא ידעינן כמה בנות יהיו לו לפיכך אין קצובין אלא האחין ששעבדו בההיא שעתא קצובין נינהו עד דתבגרן:"],[18,"אי דלא אמר להו אתם עדיי מאי טעמא דרבי יוחנן","הוה ליה למפטריה או משום משטה אני בך או משום אדם עשוי שלא להשביע את עצמו:"],[19,"דאמר ליה חייב אני לך מנה בשטר","דאלימא מילתא דשטרא לרבי יוחנן וחשיבא הודאה אע\"ג דלא אמר אתם עדיי ולא מיירי כשכתב לו חייב אני לך מנה וחתם תחתיו דהיינו הוציא עליו כתב ידו וגובה לכולי עלמא מנכסים בני חורין ולא מיירי נמי כשכתב לו אני פלוני חייב לך מנה דהא נמי כחתם תחתיו דמי ואע\"ג דבריש מגילתא מוכיח בגט פשוט (ב\"ב דף קסז.) דיכול לחתום ולא חיישינן דלמא משכח לה איניש דלא מעלי וכתיב מאי דבעי התם ודאי לא גבי כלל הואיל ואינו מכתיבה אחת דחייב אני לך מנה כתב האי איניש דלא מעלי. מ\"ר:"],[19,"","אי דלא אמר להו אתם עדיי מאי טעמא דרבי יוחנן. הוה ליה למפטריה או משום משטה אני בך או משום אדם עשוי שלא להשביע את עצמו:"],[20,"חייב לזונה חמש שנים מאי לאו כי האי גוונא","דאי בשטר גמור מה חדוש דחייב ואע\"ג דלא הוי שטר גמור גבי ממשעבדי דאית ליה קלא:"]]],[["לא בשטרי פסיקתא וכדרב גידל","דאמר רב גידל אמר רב כמה אתה נותן לבנך כך וכך וכמה אתה נותן לבתך כך וכך עמדו וקידשו קנו הן הן הדברים הנקנין באמירה","תא שמע כתב לכהן שאני חייב לך חמש סלעים חייב ליתן לו חמש סלעים ובנו אינו פדוי","שאני התם דמשועבד ליה מדאורייתא אי הכי אמאי כתב כדי לברר לו כהן","אי הכי בנו אמאי אינו פדוי כדעולא דאמר עולא דבר תורה פדוי לכשיתן ומ\"ט אמרו בנו אינו פדוי גזירה שמא יאמרו פודין בשטרות","אמר רבא כתנאי ערב היוצא אחר חיתום שטרות גובה מנכסים בני חורין","מעשה בא לפני רבי ישמעאל ואמר גובה מנכסים בני חורין אמר לו בן ננס אינו גובה לא מנכסים בני חורין ולא מנכסים משועבדים","אמר לו למה אמר לו הרי שהיה חונק את חבירו בשוק ומצא חבירו ואמר לו הנח לו ואני אתן לך פטור שלא על אמונתו הלוהו","לימא רבי יוחנן דאמר כרבי ישמעאל וריש לקיש דאמר כבן ננס","אליבא דבן ננס כ\"ע לא פליגי"],[[0,"לא בשטרי פסיקתא","החתן והכלה פוסקין תנאים שביניהם בשני עדים והעדים חותמים עדות גמורה וא\"ת א\"כ מאי למימרא איצטריך כגון דליכא קנין אלא דברים ואשמעינן כדרב גידל דלא בעי קנין:"],[3,"לברר לו כהן","שלא יתננו לכהן אחר:"],[4,"אי הכי","דטעמא משום שיעבודא דאורייתא הוא והוה ליה כמעיד עדים וחותמים אמאי אין בנו פדוי:"],[4,"שמא יאמרו פודין","את הבכור בשטרי חוב שיש לו על אחר ומסרו לכהן בפדיונו דאתי למימר מה לי האי שטרא ומה לי האי שטרא ואנן תנן במסכת בכורות אין פודין לא בעבדים ולא בשטרות ולא בקרקעות וילפינן לה התם מקראי בפרק יש בכור לנחלה:"],[5,"לאחר חיתום שטרות","תחת חתימת העדים כתוב פלוני ערב והוא מודה בדבר:"],[5,"גובה מנכסים בני חורין","המלוה מן הערב ולא מנכסים משועבדים כיון דלאחר חיתום השטר הוא הויא לה כמלוה על פה:"],[9,"אליבא דבן ננס כולי עלמא לא פליגי","כלומר בהא שפיר קאמרת דר' יוחנן כרבי ישמעאל ולא כבן ננס דמודה רבי יוחנן דלבן ננס פטור דהשתא ומה ערב דשיעבודא דאורייתא הוא דכתיב אנכי אערבנו (בראשית מ״ג:ט׳) כי ליכא עדים פטור כ\"ש כה\"ג:"]],[[2,"תא שמע כתב לכהן שאני חייב כו' חייב ליתן לו חמש סלעים","השתא סלקא דעתין דהאי חייב משום שנתחייב לו ונשתעבד ע\"י השטר ולהכי בנו אינו פדוי ומשני שאני התם דמשועבד ליה מדאורייתא פירוש להכי יכול הכא להתחייב ע\"י השטר שיש עליו קצת שעבוד אבל במקום דליכא שעבוד לא מצי למשתעבד בשטרא:"],[2,"חייב ליתן לו חמש סלעים","ובכי האי גוונא מיירי דאי לאו הכי מאי קמ\"ל דמיחייב:"],[3,"לברור לו כהן","אפי' במכירי כהונה מיירי דמסתמא קנה בלא כתיבה כדמוכח בשלהי כל הגט (גיטין ל.) ומיהו צריך כתיבה דלא ליהדר ביה והוה מצי לשנויי שכתב לו משום דלא לימא ליה פרעתי הואיל ובשטר גמור מיירי:"],[4,"אי הכי בנו אמאי אינו פדוי","כלומר הוה ליה למימר דליהוי פדוי לכשיבא ליד כהן דנהי דקודם שבא לידו דינא הוא דאינו פדוי דהא ליכא עליה אלא שעבוד בעלמא מ\"מ כשיגיעו לידו אמאי אין בנו פדוי ובברייתא משמע דאינו פדוי לגמרי:"],[4,"אמאי אינו פדוי כדעולא כו'","וא\"ת עולא לית ליה דרבי יוחנן דאמר חייב דאיצטריך ליה לפרושי טעמא משום שלא יאמרו פודין בשטרות וי\"ל דאיצטריך לפרושו הכי משום דמיירי בכל ענין אפילו כתב לו שאני חייב לו ה' סלעים לפדיון ואפי' לא כתב לו הכי סתמא דמילתא לפדיון בנו הוא דקאמר ולעולם אית ליה דר' יוחנן. מ\"ר:"],[5,"כתנאי ערב היוצא אחר חיתום שטרות","ולא חתם עצמו היטב אלא ואני ערב בעלמא כעין שלמעלה והשתא משמע הכא דערב היוצא אחר חיתום שטרות מיחייב משום דחשיב כמודה שנעשה ערב בשעת מתן מעות וקשה לרבי דלא משמע הכי בסוף פ\"ב דגיטין (דף כא. ושם) דאמרינן התם בעי רמי בר חמא היו מוחזקין בטבלא שהיא שלה וגט כתוב עליה והרי היא יוצאה מתחת ידו כו' מהו מי אמרינן אקנויי אקניתא ניהליה או דלמא כו' ובעי למיפשט רבא מערב היוצא אחר חיתום שטרות גובה מנכסים בני חורין אלמא דחייב משום דשיעבד נפשיה כשחתם עצמו בשטר ומשום הכי פשיט שפיר דהא האי שטרא כשחתם בו הערב לאחר זמן כבר היה מסור למלוה והיאך נכסי הערב משועבדין בו והא בעינן ספר מקנה אי לאו דאקנייה ניהליה מלוה לערב וחתם והדר מסר ניהליה ואי מטעם הודאה מיחייב א\"כ לא צריך שיהא קנוי לערב ואומר רבי דלעולם מחמת הודאה מיחייב והכי פשט רבא דאי אמרת בשלמא בעלמא קני כה\"ג משום הכי מיחשב הודאה דאלימא מילתא דשטר וחשיבא הודאה אלא אי אמרת בעלמא לא מיחייב כה\"ג אם כן הכא נמי לא אלימא מילתא דהאי שטרא ולא חשיב הודאה. מ\"ר:"],[9,"אליבא דבן ננס כ\"ע לא פליגי","פירוש רבי יוחנן לא מצי סבר כבן ננס ותימה לר\"י דהואיל ובן ננס פליג אדרבי יוחנן דלא חשיב ליה הודאה מנא ליה לרבי יוחנן דרבי ישמעאל סבירא ליה כותיה דהא בשלהי ב\"ב (דף קעו.) אמר רבי יוחנן גופיה חלוק היה רבי ישמעאל אף בחנוק ודלמא דוקא בחנוק הוא דפליגי דרבי ישמעאל סבר משעבד נפשיה ובן ננס סבר דחנוק לא משעבד נפשיה אבל בהודאה ל\"פ כלל דמודה רבי ישמעאל דאינה הודאה ונראה לי דיש לדקדק מדקתני רישא ערב היוצא אחר חיתום שטרות ואי לא פליג רבי ישמעאל בהודאה לא הוה ליה למיתני הכי אלא הוה ליה למימר דערב שלא בשעת מתן מעות משתעבד נפשיה אלא הא קמשמע לן דאפילו תמצי לומר דלא מיחייב משום דלא משעבד נפשיה הואיל ולא הוי בשעת מתן מעות מכל מקום מחמת הודאה מיחייב וכי תימא ומנלן דבחנוק פליגי דלמא בהא דוקא פליגי יש לדקדק מדקאמר רבי ישמעאל למה והשיב לו הרי שהיה חונק ואם תמצי לומר דמודה רבי ישמעאל בחנוק דלא מיחייב א\"כ היכי קאמר ליה למה לא יתחייב מטעם הודאה ומה השיבו הרי שהיה חונק אין הנדון דומה לראייה אלא ודאי בחנוק נמי פליגי והכי קאמר לו למה לא יתחייב משום דמעכשיו הוא דמשעבד נפשיה ושוב שמעתי מר' כדברי ור\"ת מפרש כולה סוגיא בלא הודאה שלא היה חייב לו כלום מתחלה והא דקאמר חייב אני לך מנה בשטר היינו בשטר גמור שחתמו היטב שרוצה להשתעבד ולהתחייב לו מנה בשטר זה ובהא פליגי רבי יוחנן סבר אלימא מילתא דשטרא לאקנויי ביה בשטר זה כמו שהודה בפני עדים ואין הדמיון טוב אלא איידי דנקט לעיל דאמר להו אתם עדי נקט נמי הכא כמ\"ד להו אתם עדי דמי ואין לתמוה היכי משתעבד בשטר זה הא אין מטלטלין נקנין בשטר דיש לומר דהואיל וטרח למכתב שטרא גמר ומשעבד נפשיה שהרי אפילו באמירה בעלמא יש דברים שנקנים כדקאמר בסמוך ועוד דשמעינן ליה לרבי יוחנן בהזהב (ב\"מ דף מט.) הנותן מתנה מועטת לחבירו קנה אע\"פ שלא הגיע לידו דגמר ומקני הכא נמי מתוך שטרח ליתנם בשטר בכה\"ג גמר ומקנה ומסיק כתנאי ערב היוצא אחר חיתום שטרות וחתם עצמו היטב אני פלוני בן פלוני ערב ומעכשיו הוא משתעבד ועכשיו אתיא שפיר ההיא דגיטין (דף כא. ושם) אבל לפי' הקונטרס דמטעם הודאה לא כתב בו אלא ואני ערב ומסר לו השטר בפני עדים ופליגי בן ננס ורבי ישמעאל אי הויא הודאה אי לאו ואם תאמר אמאי לא הוי שיעבוד בזה השטר כעדי מסירה י\"ל דלא חשיב האי שטר לאשתעבודי ביה כיון שאין כתוב בו שם הערב אלא כתיבתו דכיון שאין מוכיח מכתיבתו שהוא מסרו לא מצי לאישתעבודי ביה וא\"ת אמאי נקט אחר חיתום שטרות ה\"ה קודם חיתום דהוו מיפלגי וי\"ל דלהכי נקט אחר חיתום דקודם חיתום אין רגילות לכתוב לשון גרוע אבל לאחר חיתום רגילות הוא לכתוב לשון גרוע בשטר משום שההלוואה כבר נעשית ולפי' ר\"ת דמיירי בשטר גמור ליכא למימר דהא דנקט לאחר חיתום משום דקודם חיתום גבי לכ\"ע אפי' שלא בשעת מתן מעות דהא בן ננס כריש לקיש ולדידיה לא מצי לאישתעבודי בשטרא אלא להכי נקט לאחר חיתום דאז מוכחא מילתא דלאחר מתן מעות היה אבל קודם חיתום מוכח מילתא דקודם מתן מעות הוא ובהא מודה בן ננס דמשתעבד אבל לאחר חיתום פליג דמוכחא מילתא דלאחר מתן מעות הוא דאי קודם מתן מעות הוה להו לאקדומי לחיתום אלא לא יכלו להקדימו וכ\"ת משום הא ליכא הוכחה דלהכי לא הקדימו לחיתום דלא ליגבי ממשעבדי שהרי אי הוה קודם מתן מעות הוה ליה לפרושי אי נמי למיכתב הערבות בלא וא\"ו דהיכא דלא כתב וא\"ו לא קיימי העדים עליה אלא מלתא באפי נפשה הוא כדמסיק בב\"ב בסופו (דף קעו.) וקשה לפי' ר\"ת הואיל ומוקי להאי כתיבת ערבות שהוא שטר גמור להתחייב בו כשמוסר לו בפני עדים מההיא טעמא שמחוייב שום דבר יתחייב לו שיעבוד נכסים נמי ע\"י עדי מסירה כמו אם לוה ממנו דעדי מסירה מפקי ליה לקלא כדמוכח בכמה דוכתי ור\"ת הביא ראיה לדבריו מירושלמי דרבי יוחנן וריש לקיש אמרי בכה\"ג שלא נתחייב לו קודם לכך דפריך במה נתחייב זה לזון את בת אשתו לא כן אמר רבי יוחנן ורשב\"ל הכותב שטר חוב לחבירו בחזקת שהוא חייב ונמצא שאינו חייב אינו חייב לו כלום ואף על פי שלפי הירושלמי קשה דרבי יוחנן אדרבי יוחנן אין לחוש דבכמה דוכתי פליג אגמרא שלנו:"]]],[["כי פליגי אליבא דרבי ישמעאל רבי יוחנן כרבי ישמעאל וריש לקיש עד כאן לא קאמר רבי ישמעאל התם אלא דשייך ליה לשיעבודא דאורייתא אבל הכא לא שייך שיעבודא דאורייתא","גופא אמר רב גידל אמר רב כמה אתה נותן לבנך כך וכך וכמה אתה נותן לבתך כך וכך עמדו וקידשו קנו הן הן הדברים הנקנים באמירה","אמר רבא מסתברא מילתא דרב בבתו נערה דקא מטי הנאה לידיה אבל בוגרת דלא מטי הנאה לידיה לא","והאלהים אמר רב אפילו בוגרת דאי לא תימא הכי אבי הבן מאי הנאה אתא לידיה אלא בההיא הנאה דקמיחתני אהדדי גמרי ומקני להדדי","א\"ל רבינא לרב אשי דברים הללו ניתנו ליכתב או לא ניתנו ליכתב א\"ל לא ניתנו ליכתב","איתיביה הפקחין היו כותבין על מנת שאזון את בתך חמש שנים כל זמן שאת עמי מאי כותבין אומרים","וקרי ליה לאמירה כתיבה אין והתנן הכותב לאשתו דין ודברים אין לי בנכסייך ותני ר' חייא האומר לאשתו","ת\"ש אין כותבין שטרי אירוסין ונשואין אלא מדעת שניהם הא מדעת שניהם כותבין מאי לאו שטרי פסיקתא","לא שטרי אירוסין ממש כדרב פפא ורב שרביא דאיתמר כתבו לשמה ושלא מדעתה רבה ורבינא אמרי מקודשת רב פפא ורב שרביא אמרי אינה מקודשת","תא שמע מתו בנותיהן ניזונות מנכסים בני חורין והיא ניזונת מנכסים משועבדים מפני שהיא כבעלת חוב","הכא במאי עסקינן בשקנו מידו","אי הכי בנות נמי בשקנו לזו ולא קנו לזו","ומאי פסקא איהי דהואי בשעת קנין מהני לה קנין בנות דלא הוו בשעת קנין לא מהני להו קנין","מי לא עסקינן דהואי בשעת קנין והיכי דמי כגון דגרשה ואהדרה","אלא איהי דליתא בתנאי ב\"ד מהני לה קנין בנות דאיתנהו בתנאי ב\"ד לא מהני להו קנין","מגרע גרעי אלא בנותיו היינו טעמא כיון דאיתנהו בתנאי ב\"ד אימר צררי אתפסינהו:","לא יאמר הראשון: אמר רב חסדא זאת אומרת בת אצל אמה","ממאי דבגדולה עסקינן דלמא בקטנה עסקינן ומשום מעשה שהיה","דתניא מי שמת והניח בן קטן לאמו יורשי האב אומרים יהא גדל אצלנו ואמו אומרת יהא בני גדל אצלי מניחין אותו אצל אמו ואין מניחין אותו אצל ראוי ליורשו מעשה היה ושחטוהו ער\"ה","אם כן ליתני למקום שהיא"],[[0,"כי פליגי כו'","כלומר הא דמוקמת ריש לקיש כבן ננס ולא כר' ישמעאל ליתא דאמר לך ר\"ל אנא אפילו לרבי ישמעאל קא פליגנא אדרבי יוחנן:"],[0,"ערב","שיעבודא דאורייתא:"],[0,"אבל הכא","פלוני חייב ליכא שיעבודא דאורייתא:"],[2,"דקא מטי הנאה לידיה","כסף קדושיה לאביה:"],[3,"אבי הבן","אביו של חתן:"],[4,"ניתנו ליכתב","נתנו חכמים כתיבה לדבר אם באו להחתים עדים בדברים הללו שהן בלא קנין:"],[4,"לא ניתנו ליכתב","דלא ליטרוף ממשעבדי וכיון דליכא קנין לא משתעבדי נכסי:"],[8,"שטרי אירוסין ממש","שטר שמקדש בו את האשה הרי את מקודשת לי כותב בשטר ומוסר לה ואשמעינן דצריך לכתוב על פיה כדרב פפא ורב שרביא דאמרי כתבו שלא מדעתה אינה מקודשת:"],[9,"שהיא כבעלת חוב","ואי לא דנקיטא שטר מי טרפא ממשעבדי:"],[12,"מאי פסקא","בתמיה וכי דבר פסוק הוא לחכמים שקונין לבת האשה ולא לבנות ששנו סתם במשנה בנותיהן ניזונות מבני חורין והיא ניזונת ממשועבדים:"],[13,"מי לא עסקינן כו'","וכי אי אפשר שיהו אף הבנות בשעת קנין כגון דגרשה ואהדרה וכתב לה התנאים הללו ואפילו הכי תנן סתמא בנותיהן ניזונות מבני חורין ולא ממשועבדים:"],[14,"בתנאי ב\"ד","בנן נוקבן דיהויין ליכי מינאי כו':"],[15,"מיגרע גרעי","בתמיה:"],[15,"צררי אתפסינהו","לפני מותו מסר להם צרורות כספים למזונותיהן:"],[16,"זאת אומרת הבת אצל האם","דקתני למקום שאמה ולא קתני לבית אחיה למדנו שכן הוא הדין שתגדל הבת אצל אמה ובת הניזונת מן הבנים זנין אותה בבית אמה ואין כופין אותה לדור אצלם:"],[17,"דלמא בקטנה עסקינן","ומשום הכי לא קתני בת אצל אחין:"],[17,"משום מעשה שהיה","[ואיכא למיחש נמי שמא] יהרגוה בשביל לירש עישור נכסים שלה אבל גדולה דלא חיישינן לרציחה אימא לך דתשב אצל האחין:"],[19,"אם כן","דיש חילוק בין גדולה לקטנה:"],[19,"ניתני מוליך לה מזונות למקום שהיא","דמשמע לגדולה במקום שהיא ולקטנה במקום שהיא:"]],[[4,"ניתנו ליכתב או לא ניתנו ליכתב","פי' משום דסתם קנין לכתיבה עומד שמא משום הכי ניתנו ליכתב דכי קנו מידו דמי וקשה דמאי קפריך מההיא דאין כותבין שטרי אירוסין ונשואין אלא מדעת שניהם הא מדעת שניהם כותבין דלמא הכי קאמר הא מדעת שניהם כשאומר לו לכתוב וקמ\"ל דאין כותבין בסתמא והיה מפרש רבי דמשמע ליה להש\"ס אין כותבין אלא מדעת שניהם היינו בידיעת שניהם ששניהם נתרצו בדבר דידעו גמר הפסיקה אבל לא ידעו בכתיבה דומיא דהך דלעיל מיניה כותבין שטר ללוה אע\"פ שאין מלוה עמו דהיינו אע\"ג דאין יודע עכשיו מן ההלואה כלום וכותבין שטר למוכר אע\"פ שאין לוקח עמו דהיינו אע\"פ שאין הלוקח יודע במקח כלום ואין כותבין שטרי אירוסין אלא מדעת שניהם מדעת גמר הפסיקה הא מדעת שניהם כותבין אף בלא ידיעת השטר נמי:"],[8,"רבה ורבינא אמרי מקודשת","תימה דלרבינא דאמר מקודשת מיבעי ליה לאוקמה לההיא דאין כותבין שטרי אירוסין בשטרי פסיקתא ואם כן מאי קמיבעיא ליה לעיל דברים הללו ניתנו ליכתב תפשוט ליה מהך:"],[9,"תא שמע מתו בנותיהם נזונות","תימה אמאי לא מייתי הך מעיקרא מקמי דמייתי ההיא דהפקחין דההיא נשנית תחלה במשנתנו וי\"ל שכן דרך הש\"ס משום דאי הוה מייתי הך מעיקרא והוה משני בשקנו מידו תו לא הוה מצי למפרך מההיא דהפקחין דאיכא לאוקמה נמי כשקנו מידו:"],[10,"הכא במאי עסקינן בשקנו מידו","הוה מצי לשנויי בדכתב ליה ור\"ח ור\"ת מפרשים ניתנו ליכתב ניתנו לגבות ע\"י כתיבה דווקא או לא ניתנו ליכתב שאף בלא כתיבה תקנו לה קנין איתיביה הפיקחין היו כותבין מדקתני כתיבה ש\"מ בעי כתיבה דלא קני באמירה בלא כתיבה ואין כותבין שטרי אירוסין ונשואין נמי מדקתני כתיבה ש\"מ בעי כתיבה דלא קני באמירה בלא כתיבה והשתא לא גרסינן הא מדעת שניהן כותבין וברוב ספרים אינו ת\"ש והיא ניזונת מנכסים משועבדים אלמא דכותבין דאי אין כותבין אמאי הוה גביא ממשעבדי דס\"ד דכך הוא רגילות כל שעה לכתוב לה ומשני בשקנו מידו כלומר דבלא כתיבה יכולין לגבות מן המחוררין והכא כך אירע הדבר שהקנה לה:"],[10,"הב\"ע בשקנו מידו","בפ' הנזקין (גיטין דף נא. ושם) מוקי להך נמי בשקנו מידו וההיא דהמקבל עליו לזון בן אשתו ובת אשתו בשלא קנו מידו איירי ולפי מאי דמשמע בגיטין דלמאן דלא בעיא אלא קצובין אתי שפיר הך דהיא ניזונת מנכסים משועבדים אפילו דלא קנו מידו מצינו לאוקמה ההיא דחמשה גובה מן המחוררין [לעיל (כתובות נא:)] כשאין שם קצבה:"],[15,"אימר צררי אתפסינהו","תימה לרבי דבגיטין פ' הנזקין (גיטין דף מח:) תנן אין מוציאין לאכילת פירות ולשבח קרקעות ולמזון האשה והבנות מנכסים משועבדים מפני תיקון העולם ומפרש ר\"ל בגמ' (שם נ:) טעמא לפי שאין כתובין והיינו טעמא נמי דמזון הבנות והכא מפרש טעמא משום אימר צררי אתפסה וי\"ל דאיצטריך טעמא לפי שאין כתובין היכא שהודה האב שלא התפיס צררי ועוד תימה לרבי דהכא משמע דמתפיס צררי לקטנה ולקמן בפ' בתרא (כתובות דף קז.) אמר שמואל אין פוסקין מזונות לאשת איש מ\"ט רב זביד אמר אימר צררי אתפסה רב פפא אמר חיישינן שמא אמר לה צאי מעשה ידיך במזונותיך מאי בינייהו איכא בינייהו קטנה וספקה פי' דלרב זביד לא חיישינן דצררי לקטנה לא מתפיס ותירץ רבי דודאי לענין דלא גבי ממשעבדי לא חיישינן כי התם אבל הכא למיגבי ממשעבדי אמרינן עוד תירץ דהתם כשהלך למדינת הים מיירי ואינו חושש להתפיסה צררי דמעלה בדעתו שתהא לוה ואוכלת וכשיחזור יפרע אבל הכא דמיית אתפסה צררי עוד תימה לרבי כיון דהיינו טעמא דלא גבו בנות ממשעבדי משום דכיון דאיתנהו בתנאי ב\"ד אימר אתפסינהו צררי כתובה נמי מהאי טעמא לא תגבי ממשעבדי ותירץ רבי דטפי מתפיס צררי לבתו כדאמרינן לעיל בפרק נערה (כתובות דף מג. ושם) לענין הרווחה דבתו עדיפא ליה ואמרתי לפני רבי דמשמע הכא דבת אשתו אי הוה גובה בתנאי ב\"ד לא היתה גובה ממשעבדי דהוה חיישינן להתפיס צררי אע\"ג דלא ניחא ליה בהרווחה ואמר לי רבי דודאי הוה מצי למימר בתה לא ניחא ליה בהרווחה בתו ניחא ליה אלא איצטריך טעמא דתנאי ב\"ד שאם פסקה עמו לזון את בתה מחיים דאז לא אכלה בתנאי ב\"ד א\"נ לאחר מיתה ולאחר שתבגר היתה גובה ממשעבדי דלא חיישינן לצררי אלא היכא דאיכא תרי טעמי דאכלה בתנאי ב\"ד וניחא ליה בהרווחה ובהאי שינויא מיתרצא נמי ההיא פירכא דלקמן משמע דצררי לקטנה לא מתפיס עוד תירץ דה\"ק כיון דאיתנהו בתנאי ב\"ד פי' שכל כך יפה כסה שהקנה לה אע\"ג דאיתנהו בתנאי ב\"ד ודאי איכא למיחש לצררי ובהאי שינויא מתורצין לגמרי כל הנך פירכי ההיא דגיטין וההיא דקטנה וההיא דכתובה. מ\"ר:"]]],[["מאי למקום שאמה שמעת מינה בת אצל האם לא שנא גדולה ולא שנא קטנה:","לא יאמרו שניהם וכו':","ההוא גברא דאוגר ליה ריחיא לחבריה לטחינה לסוף איעתר זבין ריחיא וחמרא","אמר ליה עד האידנא הוה טחיננא גבך השתא הב לי אגרא א\"ל מיטחן טחיננא לך","סבר רבינא למימר היינו מתניתין לא יאמרו שניהם הרי אנו זנין אותה כאחד אלא אחד זנה ואחד נותן לה דמי מזונות","א\"ל רב עוירא מי דמי התם חד כריסא אית לה תרתי כריסתא לית לה הכא מצי א\"ל טחון וזבין טחון ואותיב","ולא אמרן אלא דלית ליה טחינא לריחיא אבל אית ליה טחינא לריחיא כגון זו כופין אותו על מדת סדום:","\u0001מתני׳\u0002 אלמנה שאמרה אי אפשי לזוז מבית בעלי אין היורשין יכולין לומר לה לכי לבית אביך ואנו זנין אותך אלא זנין אותה ונותנין לה מדור לפי כבודה","אמרה אי אפשי לזוז מבית אבא יכולין היורשין לומר לה אם את אצלנו יש ליך מזונות ואם אין את אצלנו אין ליך מזונות","אם היתה טוענת מפני שהיא ילדה והן ילדים זנין אותה והיא בבית אביה:","\u0001גמ׳\u0002 תנו רבנן משתמשת במדור כדרך שמשתמשת בחיי בעלה בעבדים ושפחות כדרך שמשתמשת בחיי בעלה בכרים וכסתות כדרך שמשתמשת בחיי בעלה בכלי כסף ובכלי זהב כדרך שמשתמשת בחיי בעלה שכך כתב לה ואת תהא יתבת בביתי ומיתזנא מנכסי כל ימי מגר ארמלותיך בביתי","תני רב יוסף בביתי ולא בבקתי","אמר רב נחמן יתומים שמכרו מדור אלמנה לא עשו ולא כלום","ומ\"ש מדרבי אסי א\"ר יוחנן דא\"ר אסי אמר ר' יוחנן יתומים שקדמו ומכרו בנכסים מועטין מה שמכרו מכרו","התם לא משתעבדי לה מחיים הכא משתעבדי לה מחיים","אמר אביי נקיטינן מדור אלמנה שנפל אין היורשין חייבין לבנותו","תניא נמי הכי מדור אלמנה שנפל אין היורשין חייבין לבנותו ולא עוד אלא אפילו היא אומרת הניחוני ואבננו משלי אין שומעין לה","בעי אביי שיפצה מאי תיקו:","אמרה אי אפשי:","וליתבו לה כי יתבה התם מסייע ליה לרב הונא דאמר רב הונא ברכת הבית ברובה","וליתבו לה לפי ברכת הבית ה\"נ","אמר רב הונא לשון חכמים ברכה לשון חכמים עושר לשון חכמים מרפא ברכה הא דאמרן","עושר דתנן המוכר פירות לחבירו משך ולא מדד קנה מדד ולא משך לא קנה ואם היה פקח שוכר את מקומו","מרפא דתנן לא ילעוס אדם חטין ויניח על גבי מכתו בפסח מפני שמחמיצות","ת\"ר בשעת פטירתו של רבי אמר לבני אני צריך נכנסו בניו אצלו אמר להם הזהרו בכבוד אמכם נר יהא דלוק במקומו שולחן יהא ערוך במקומו מטה תהא מוצעת במקומה יוסף חפני שמעון אפרתי הם שמשוני בחיי והם ישמשוני במותי:","הזהרו בכבוד אמכם: דאורייתא היא דכתיב (שמות כ, יא) כבד את אביך ואת אמך אשת אב הואי","אשת אב נמי דאורייתא היא דתניא כבד את אביך ואת אמך את אביך זו אשת אביך ואת אמך זו בעל אמך וי\"ו יתירה לרבות את אחיך הגדול","הני מילי מחיים אבל לאחר מיתה לא:","נר יהא דלוק במקומו שולחן יהא ערוך במקומו מטה תהא מוצעת במקומה: מאי טעמא כל בי שמשי הוה אתי לביתיה","ההוא בי שמשא אתאי שבבתא קא קריה אבבא אמרה אמתיה שתיקו דרבי יתיב כיון דשמע שוב לא אתא שלא להוציא לעז על צדיקים הראשונים:","יוסף חפני שמעון אפרתי הם שמשוני בחיי והם ישמשוני במותי: סבור מינה בהדין עלמא הוא דקאמר כיון דחזו דקדים ערסייהו לערסיה אמרי שמע מינה לההוא עלמא הוא דקאמר","והאי דאמר הכי דלא לימרו מילתא הואי להו ועד האידנא נמי זכותו דרבי הוא דאהניא להו","אמר להן לחכמי ישראל אני צריך נכנסו אצלו חכמי ישראל אמר להן אל תספדוני בעיירות"],[[0,"מאי למקום שאמה","דקתני מילתא פסיקתא ש\"מ כל בת אצל האם:"],[2,"דאוגר ליה ריחיא לחבריה לטחינה","לא התנה שוכר לתת מעות למשכיר אלא שיטחון לו למזונות ביתו בשכרו:"],[2,"לסוף איעתר","משכיר:"],[2,"זבין ריחיא וחמרא","לטחון בה מזונות ביתו:"],[4,"אחד זנה ואחד נותן לה דמי מזונות","ולא אמרינן שניהם יתנו לה מזונות ואע\"פ שלא פסק לה דמים מתחלה אלא מזונות חייבוהו לתת דמיהם כשיש לה מזונות ממקום אחר הכא נמי אע\"פ שלא פסק אלא טחינה עכשיו שאינו צריך יתן דמים:"],[5,"טחון וזבין","באותה שלקחת:"],[5,"טחון ואותיב","למזונותיך באותה שאצלי:"],[6,"ולא אמרן","דלא יהיב דמי:"],[6,"אלא דלית ליה טחינא לריחיא","שאין שוכר מוצא לטחון בשכר כל שעה לפיכך אומר לו אני יושב בטל אטחון לך ולא אתן דמים:"],[6,"אבל","כל זמן שמוצא לטחון טוחן בשכר ונותן לזה דמים:"],[6,"מדת סדום","זה נהנה וזה לא חסר לא היו עושין טובה:"],[7,"מתני' אי אפשי לזוז מבית בעלי","לצאת מבית בעלי:"],[11,"גמ' ולא בבקתי","בית צר כעין צריף כדאמרינן במסכת שבת (דף עז:) בקתא בי עקתא אם היה מדור שלו צר לא קבל עליו להוציא את בניו ולהושיבה:"],[13,"בנכסים מועטין","שהבנות זוכות בהן כדתנן (לקמן כתובות דף קח:) הבנות יזונו והבנים ישאלו על הפתחים:"],[13,"וקדמו","קודם שיבואו לב\"ד ומכרום:"],[17,"שיפצה","חזקה בדקיה:"],[17,"מאי","מי אמרינן לא מפקינן לה כל ימים שיכול להתקיים או דלמא אמרי' לה לאו כל כמינך:"],[19,"ברכת הבית ברובה","בני אדם שעוזרין זה את זה משתכרין ומזל דרבים עדיף:"],[20,"וליתבו לה","לפי מה שנתמעטה ברכת הבית ביציאתה:"],[21,"לשון חכמים","יש ללמוד ממנה ברכה ועושר ורפואה:"],[22,"אם היה פקח","זה שלוקח פירות הרבה ואין לו שהות למושכם אלא נתן מעות:"],[22,"שוכר את מקומו","דהוי לה כי חצירו וחצירו קונה לו הרי אתה למד מכאן סחורה שלא יוכל המוכר לחזור הרי לך עושר למוד מלשון חכמים:"],[23,"לא ילעוס כו'","למדת שהחטים הלעוסין יפה למכה:"],[24,"נר יהא דלוק במקומו","אצל השולחן כמו בחיי דכל ע\"ש היה בא לביתו משנפטר כדלקמן:"],[24,"יוסף חפני","דמן חיפא:"],[26,"את אביך","כל אתין רבויין:"],[26,"וי\"ו יתירה","דואת אמך:"],[27,"ה\"מ","דחייב בכבוד אשת אביו בחיי אביו:"],[28,"בי שמשי","ערב שבת ונראה בעיני לפי שבין השמשות שלו שגור בפי כל והכל חרידים אליו לגמור מלאכתן עד שלא תחשך קרו ליה בי שמשי:"],[29,"שלא להוציא לעז כו'","לומר לא צדיקים היו שלא היה להן רשות לבא לביתם כמו רבי:"],[30,"סבור מינה בהדין עלמא","שהיה מצוה שיתעסקו בקבורתו:"],[30,"דקדים ערסייהו לערסי'","הם נקברו תחלה:"],[31,"והאי דאמר הכי","שנזקק להודיע שימותו וישרתוהו:"],[31,"דלא לימרו","אינשי עלייהו כשימותו מילתא דאיסורא הוה בהו שלא זכו להתעסק בו ואיגלאי מילתא דהאי דלא שכיבו בשני דרבי זכותיה דרבי אגנא עלייהו:"],[32,"עיירות","גדולות על הכפרים וכרכין גדולים מהם:"]],[[6,"ולא אמרן אלא דלית ליה טחינה לריחיא","תימה הואיל והאי עובדא בדלית טחינה לריחיא אמאי איצטריך רב עוירא למימר התם תרי כריסתא לית לה הכא טחון וזבין אפי' לא הוה משכח משכיר למיטחן ומיזבן דהוה חד כריסא לא הוה דמי למתני' דבמתניתין ליכא פסידא דבעל כי יהיב לה דמי מזונות ממה שהיה נותן מזונות עצמן אבל השוכר אית ליה פסידא אם יתן שכר הטחינה שהרי אינו מוצא לטחון ומכיסו יצטרך לפרוע ואמר רבי דבלאו האי טעמא דטחון וזבין טחון ואותיב הוה מצי לבטולי המקח שלא יצטרך ליתן לו אגרא הואיל ואית ליה פסידא אבל מ\"מ המשכיר יאמר כמו כן לדידי אית לי פסידא שכר ריחיא שלי ויכול לבטל המקח קודם הזמן ונהי דשוכר לא יצטרך ליתן לו שכר מכיסו אבל לעכב הריחים עד זמן שהתנו ביניהן לא יוכל השוכר הואיל ומשכיר אית ליה פסידא אבל השתא דמצי למימר ליה טחון וזבין טחון ואותיב ולית לך פסידא על כורחיך תניח לי הריחים עד הזמן שהרי לי הוה פסידא ולך אין פסידא:"],[17,"ה\"ג שיפצא מאי","ושם דבר הוא כלומר מהו שתשפץ וכן פי' ר\"ח:"],[19,"ברכת הבית ברובה","פי' ר\"ח כגון הא דאמרינן (שבת דף קכב.) נר לאחד נר למאה וכן כל כהאי גוונא אין נותנין:"]]],[["והושיבו ישיבה לאחר שלשים יום שמעון בני חכם גמליאל בני נשיא חנינא בר חמא ישב בראש:","אל תספדוני בעיירות: סבור מינה משום טרחא הוא דקאמר כיון דחזי דקספדי בכרכים וקאתו כולי עלמא אמרו שמע מינה משום יקרא הוא דקאמר","הושיבו ישיבה לאחר שלשים יום דלא עדיפנא ממשה רבינו דכתיב (דברים לד, ח) ויבכו בני ישראל את משה בערבות מואב שלשים יום תלתין יומין ספדין ביממא וליליא מכאן ואילך ספדו ביממא וגרסי בליליא או ספדו בליליא וגרסי ביממא עד דספדי תריסר ירחי שתא","ההוא יומא דאשכבתיה דרבי נפקא בת קלא ואמרה כל דהוה באשכבתיה דרבי מזומן הוא לחיי העוה\"ב ההוא כובס כל יומא הוה אתי קמיה ההוא יומא לא אתא כיון דשמע הכי סליק לאיגרא ונפל לארעא ומית יצתה בת קול ואמרה אף ההוא כובס מזומן הוא לחיי העולם הבא:","שמעון בני חכם: מאי קאמר הכי קאמר אע\"פ ששמעון בני חכם גמליאל בני נשיא","אמר לוי צריכא למימר אמר רבי שמעון בר רבי צריכא לך ולמטלעתך מאי קשיא ליה הא קרא קאמר (דברי הימים ב כא, ג) ואת הממלכה נתן ליהורם כי הוא הבכור","ההוא ממלא מקום אבותיו הוה ורבן גמליאל אינו ממלא מקום אבותיו הוה","ורבי מאי טעמא עבד הכי נהי דאינו ממלא מקום אבותיו בחכמה ביראת חטא ממלא מקום אבותיו הוה:","חנינא בר חמא ישב בראש לא קיבל רבי חנינא שהיה ר' אפס גדול ממנו שתי שנים ומחצה יתיב רבי אפס ברישא ויתיב רבי חנינא אבראי ואתא לוי ויתיב גביה","נח נפשיה דרבי אפס ויתיב רבי חנינא ברישא ולא הוה ליה ללוי איניש למיתב גביה וקאתא לבבל והיינו דאמרי ליה לרב גברא רבה אקלע לנהרדעא ומטלע ודריש כלילא שרי אמר שמע מינה נח נפשיה דרבי אפס ויתיב רבי חנינא ברישא ולא הוה ליה ללוי איניש למיתב גביה וקאתא","ואימא רבי חנינא נח נפשיה ור' אפס כדיתיב יתיב ולא הוה ליה ללוי איניש למיתב גביה וקאתא איבעית אימא לוי לר' אפס מיכף הוה כייף ליה","ואי בעית אימא כיון דאמר ר' חנינא בר חמא ישב בראש לא סגי דלא מליך דכתיב בהו בצדיקים (איוב כב, כח) ותגזר אומר ויקם לך","והא הוה ר' חייא נח נפשיה והאמר ר' חייא אני ראיתי קברו של רבי והורדתי עליו דמעות איפוך","והאמר רבי חייא אותו היום שמת רבי בטלה קדושה איפוך","והתניא כשחלה רבי נכנס ר' חייא אצלו ומצאו שהוא בוכה אמר לו רבי מפני מה אתה בוכה והתניא מת מתוך השחוק סימן יפה לו מתוך הבכי סימן רע לו פניו למעלה סימן יפה לו פניו למטה סימן רע לו פניו כלפי העם סימן יפה לו כלפי הכותל סימן רע לו פניו ירוקין סימן רע לו פניו צהובין ואדומים סימן יפה לו מת בע\"ש סימן יפה לו במו\"ש סימן רע לו מת בערב יוהכ\"פ סימן רע לו במוצאי יוהכ\"פ סימן יפה לו מת מחולי מעיים סימן יפה לו מפני שרובם של צדיקים מיתתן בחולי מעיים","א\"ל אנא אתורה ומצות קא בכינא","איבעית אימא איפוך ואיבעית אימא לעולם לא תיפוך ר' חייא עסוק במצות הוה ורבי סבר לא אפגריה","והיינו דכי הוו מינצו ר' חנינא ור' חייא א\"ל ר' חנינא לר' חייא בהדי דידי מינצת דאם חס ושלום נשתכחה תורה מישראל מהדרנא ליה מפלפולי","א\"ל ר' חייא אנא עבדי דלא משתכחה תורה מישראל דאייתינא כיתנא ושדיינא ומגדלנא נישבי וציידנא טביא ומאכילנא בישרא ליתמי ואריכנא מגילתא ממשכי דטביא וסליקנא למתא דלית בה מקרי דרדקי וכתיבנא חמשא חומשי לחמשא ינוקי ומתנינא שיתא סידרי לשיתא ינוקי לכל חד וחד אמרי ליה אתני סידרך לחברך","והיינו דאמר רבי כמה גדולים מעשה חייא א\"ל ר\"ש ב\"ר אפילו ממך א\"ל אין א\"ל רבי ישמעאל ברבי יוסי אפילו מאבא א\"ל חס ושלום לא תהא כזאת בישראל","אמר להן לבני קטן אני צריך נכנס ר' שמעון אצלו מסר לו סדרי חכמה","אמר להן לבני גדול אני צריך נכנס רבן גמליאל אצלו ומסר לו סדרי נשיאות אמר לו בני נהוג נשיאותך ברמים זרוק מרה בתלמידים","איני והא כתיב (תהלים טו, ד) ואת יראי ה' יכבד ואמר מר זה יהושפט מלך יהודה כשהיה רואה תלמיד חכם היה עומד מכסאו ומחבקו ומנשקו וקורא לו רבי רבי מרי מרי","לא קשיא הא בצינעא הא בפרהסיא","תניא רבי מוטל בציפורי ומקום מוכן לו בבית שערים והתניא (דברים טז, כ) צדק צדק תרדף הלך אחר ר' לבית שערים","ר' בבית שערים הוה אלא כיון דחלש אמטיוהי לציפורי"],[[0,"והושיבו ישיבה","לעסוק בתורה:"],[0,"לאחר שלשים יום","של פטירתי מיד ולא תהיו עסוקין בהספד:"],[0,"שמעון בני חכם","הוא ולקמן פריך מאי קאמר:"],[0,"חנינא בר חמא ישב בראש","הישיבה:"],[1,"סבור מינה משום טורח","דבני כפרים דסמיכו לעיירות ואתו למספדיה כיון דחזו דקא אספדוהו בכרכין וקא אתו כולי עלמא מעיירות ומכפרים אמרי משום יקרא הוא דקאמר:"],[3,"יומא דאשכבתיה","יום פטירתו:"],[5,"צריכא למימר","דר\"ג דבכור הוי נשיאה:"],[5,"לך ולמטלעתך","פסח היה כדאמרינן בעלמא (סוכה דף נג.) לוי אחוי קידה ואטלע:"],[5,"מאי קשיא ליה","לר\"ש ברבי דאמר צריכא למימר אמאי צריכא הא קרא כתיב:"],[6,"ההוא ממלא מקום אבותיו הוה","כלומר אין באחיו חשוב ממנו אבל כאן הרי אחיו חכם ממנו:"],[8,"יתיב רבי חנינא אבראי","חוץ לבית המדרש שלא היה נכפף לר' אפס:"],[9,"וקאתא","לבבל:"],[9,"כלילא שרי","לצאת בה בשבת מאי טעמא מאן דרכה למיפק בכלילא אשה חשובה ואשה חשובה לא שלפא ומחויא בפרק במה אשה יוצאה (שבת דף נט:):"],[10,"מיכף הוה כייף ליה","קודם שיגלה ממקומו אבל לר' חנינא לא כייף:"],[12,"והא הוה ר' חייא","ולמנייה רבי ראש ישיבה:"],[12,"קברו של רבי","ארונו של רבי הורדתי עליו דמעות:"],[14,"בערב שבת סימן יפה","שיכנס למנוחה מיד:"],[14,"במוצאי יוהכ\"פ","נמחלו עוונותיו וסימן יפה לו:"],[16,"לא אפגריה","לא אבטלו ממצות:"],[18,"שדיינא","זרענא:"],[18,"ומגדלנא נישבי","מקלע אני מכמורת ודומה לו אין פורסין נשבין ליונים (ב\"ב דף כג.):"],[18,"וציידנא טביי","צביים:"],[18,"ואריכנא מגילתא","ומתקן אני קלפים אריכנא לשון תיקון כדאמר במסכת סוכה (דף מד:) אריך או לא אריך כלומר מתוקן או אינו מתוקן ובס' עזרא (סימן ד) נמי כתיב וערות מלכא לא אריך לנא למחזא:"],[19,"לא תהא כדבר הזה בישראל","כלומר שלא אומר כדבר זה לעולם:"],[21,"נהוג נשיאותך ברמים","שתהא יושב בין הגדולים:"],[21,"זרוק מרה","אימה שתהא אימתך עליהם:"],[23,"בצינעא","מכבד כל אחד ואחד:"],[23,"בפרהסיא","מטיל עליהם אימה להודיע נשיאותו:"],[24,"רבי מוטל","בחליו בצפורי ומקום קברו מוכן לו בבית שערים:"]],[[3,"מזומן לחיי העולם הבא","תימה והלא כל ישראל יש להם חלק לעוה\"ב ופירש הרב ר' מאיר כל היכא דאמר מזומן לחיי העולם הבא היינו בלא דין ובלא יסורין:"],[13,"אותו היום שמת רבי בטלה קדושה","שהיו קורין אותו רבינו הקדוש והא דתניא בשילהי סוטה (דף מט.) משמת ר' בטלה ענוה ויראה י\"ל קדושה בכלל והרב רבי חיים כהן היה אומר אילמלי הייתי כשנפטר ר\"ת הייתי מטמא לו דהאי בטלה קדושה דקאמר הכא היינו קדושת כהונה וכן מוכח מדקאמר אותו היום משמע אותו היום דוקא ותו לא ובהדיא אמר בירושלמי דמס' ברכות בפ' מי שמתו דכשמת רבי אמרו אין כהונה היום ואין נראה לרבי דכמדומה לרבי דהתם מיירי בטומאת בית הפרס דרבנן אבל טומאה דאורייתא לא:"]]],[["דמדליא ובסים אוירא","ההוא יומא דנח נפשיה דרבי גזרו רבנן תעניתא ובעו רחמי ואמרי כל מאן דאמר נח נפשיה דר' ידקר בחרב","סליקא אמתיה דרבי לאיגרא אמרה עליוני' מבקשין את רבי והתחתוני' מבקשין את רבי יהי רצון שיכופו תחתונים את העליונים כיון דחזאי כמה זימני דעייל לבית הכסא וחלץ תפילין ומנח להו וקמצטער אמרה יהי רצון שיכופו עליונים את התחתונים","ולא הוו שתקי רבנן מלמיבעי רחמי שקלה כוזא שדייא מאיגרא [לארעא] אישתיקו מרחמי ונח נפשיה דרבי","אמרו ליה רבנן לבר קפרא זיל עיין אזל אשכחיה דנח נפשיה קרעיה ללבושיה ואהדריה לקרעיה לאחוריה פתח ואמר אראלים ומצוקים אחזו בארון הקדש נצחו אראלים את המצוקים ונשבה ארון הקדש אמרו ליה נח נפשיה אמר להו אתון קאמריתו ואנא לא קאמינא","בשעת פטירתו של רבי זקף עשר אצבעותיו כלפי מעלה אמר רבש\"ע גלוי וידוע לפניך שיגעתי בעשר אצבעותי בתורה ולא נהניתי אפילו באצבע קטנה יהי רצון מלפניך שיהא שלום במנוחתי יצתה ב\"ק ואמרה (ישעיהו נז, ב) יבא שלום ינוחו על משכבותם","על משכבך מיבעי ליה מסייע ליה לר' חייא בר גמדא דאמר רבי חייא בר גמדא אמר ר' יוסי בן שאול בשעה שהצדיק נפטר מן העולם אומרים מלאכי השרת לפני הקב\"ה רבש\"ע צדיק פלוני בא אומר להם יבואו צדיקים ויצאו לקראתו ואומרים לו יבא בשלום ינוחו על משכבותם","אמר ר' אלעזר בשעה שהצדיק נפטר מן העולם שלש כיתות של מלאכי השרת יוצאות לקראתו אחת אומרת לו בא בשלום ואחת אומרת הולך נכחו ואחת אומרת לו יבא שלום ינוחו על משכבותם בשעה שהרשע נאבד מן העולם שלש כיתות של מלאכי חבלה יוצאות לקראתו אחת אומרת (ישעיהו מח, כב) אין שלום אמר ה' לרשעים ואחת אומרת לו (ישעיהו נ, יא) למעצבה ישכב ואחת אומרת לו (יחזקאל לב, יט) רדה והשכבה את ערלים:","\u0001מתני׳\u0002 כל זמן שהיא בבית אביה גובה כתובתה לעולם כל זמן שהיא בבית בעלה גובה כתובתה עד עשרים וחמש שנים שיש בכ\"ה שנים שתעשה טובה כנגד כתובתה דברי ר' מאיר שאמר משום רשב\"ג","וחכ\"א כל זמן שהיא בבית בעלה גובה כתובתה לעולם כל זמן שהיא בבית אביה גובה כתובתה עד עשרים וחמש שנים","מתה יורשיה מזכירין כתובתה עד עשרים וחמש שנים:","\u0001גמ׳\u0002 אמר ליה אביי לרב יוסף ענייה שבישראל עד עשרים וחמש שנים ומרתא בת בייתוס עד עשרים וחמש שנים","אמר ליה לפום גמלא שיחנא","איבעיא להו לרבי מאיר מהו שתשלש תיקו:","וחכמים אומרים כל זמן: אמר ליה אביי לרב יוסף אתאי קודם שקיעת החמה גובה כתובתה לאחר שקיעת החמה לא גביא בההיא פורתא אחילתא","אמר ליה אין כל מדת חכמים כן היא בארבעים סאה טובל בארבעים סאה חסר קורטוב אינו יכול לטבול בהן","אמר רב יהודה אמר רב העיד רבי ישמעאל ברבי יוסי לפני רבי שאמר משום אביו לא שנו אלא שאין שטר כתובה יוצא מתחת ידיה אבל שטר כתובה יוצא מתחת ידיה גובה כתובתה לעולם ורבי אלעזר אמר אפילו שטר כתובה יוצא מתחת ידיה אינה גובה אלא עד עשרים וחמש שנים","מתיב רב ששת ב\"ח גובה שלא בהזכרה היכי דמי אי דלא נקט שטרא במאי גבי אלא דנקיט שטרא וב\"ח הוא דלאו בר אחולי הוא הא אלמנה אחילתא","הוא מותיב לה והוא מפרק לה לעולם דלא נקיט שטרא והכא במאי עסקינן כשחייב מודה","והאמר ר' אלעא שונין גרושה הרי היא כבעל חוב היכי דמי אי דלא נקיטא כתובה במאי גביא אלא לאו דנקיטא כתובה וגרושה היא דלאו בת אחולי היא הא אלמנה אחילתא","הכא נמי כשחייב מודה","אמר רב נחמן בר יצחק תני רב יהודה בר קזא במתניתא דבי בר קזא תבעה כתובתה"],[[0,"דמדליא","דאמרינן במסכת מגילה (דף ו.) למה נקרא שמה צפורי שיושבת בראש ההר כציפור:"],[2,"דעל כמה זימנין לבית הכסא","דחולי מעיים הוה ליה:"],[2,"וחלץ תפילין ומנח להו","וקא מצער לחלוץ ולהניח:"],[4,"פתח ואמר","הספד:"],[4,"אראלים ומצוקים","מלאכים וצדיקים מצוקי ארץ:"],[5,"ולא נהניתי בעולם הזה","[אפילו] לפי טורח שיגעתי באצבע קטנה שלי:"],[6,"יבואו צדיקים ויצאו לקראתו ויבא בשלום","ואחר כך ינוחו צדיקים על משכבותם:"],[7,"הולך נכחו","בדרך ישרה:"],[8,"מתני' כל זמן שהיא בבית אביה","והיורשים זנוה שם:"],[8,"גובה כתובתה","כשתרצה:"],[8,"שתעשה טובה","מנכסי יתומים נותנת לחם ומלח לשכניה:"],[9,"וחכמים אומרים","לא הוזכרו עשרים וחמש לענין הטובה שתעשה ולא אפסדוה רבנן כתובה וכשהוזכרו עשרים וחמש לענין המחילה הוזכרו דהואיל ושתקה ולא תבעה כל השנים הללו מחלתה הלכך כל זמן שהיא בבית בעלה אין שתיקתה מחילה אלא מפני שמכבדין אותה היא בושה למחות על כתובתה אבל בבית אביה מששתקה כ\"ה שנים מחילה היא:"],[10,"מתה יורשיה מזכירין כתובתה כו'","כלומר צריכה למחות על כתובתה בתוך כ\"ה שנים:"],[11,"גמ' ענייה שבישראל","שכתובתה מועטת איבדה לרבי מאיר בטובה שעושה בכ\"ה שנים:"],[11,"ומרתא בת בייתוס","שהיתה עשירה וכתובתה מרובה תפסיד כתובתה בטובה של כ\"ה שנים:"],[12,"לפום גמלא שיחנא","המשוי לפי הגמל אף כאן לפי עושרה טובתה:"],[13,"מהו שתשלש","לר\"מ דטעמא משום טובה:"],[13,"שתשלש","שנחשוב טובתה לחשבון כתובתה לפי חשבון השנים להפסיד לכל שנה אחת מעשרים וחמש בכתובתה אם לא שהתה כ\"ה שנים אלא חציין או שלישית או רביעית תשלש לשון חלוקה לפי חשבון הוא כדתנן (מכות דף ה.) משלשין בממון ואין משלשין במכות:"],[15,"כל מדת חכמים כן","העמידוה יתד ולא תמוט:"],[16,"אבל שטר כתובה יוצא","בבית דין מתחת ידה:"],[16,"גובה כתובתה לעולם","שאילו מחלתה היתה מוסרת להם שטר הכתובה:"],[17,"שלא בהזכרה","אם שתק עשרים וחמש שנים ולא מיחה על חובו לא הפסיד בכך:"],[17,"אלמנה בת אחולי היא","שנהנית מהן כל השנים הללו וכתובתה אינה מלוה ולא חיסרה בה ממון:"],[18,"לעולם דלא נקיט","הלכך דווקא בעל חוב הא אלמנה דלא נקטא שטרא אחילת' ודקשיא לך במאי גביא כשחייב מודה:"],[19,"שונין","בעלי ברייתא:"],[19,"גרושה הרי היא כבעל חוב","לגבות לעולם שלא בהזכרה דוודאי לא מחלה:"],[20,"כשחייב מודה","שלא נתקבלה כתובתה:"],[21,"בר קזא","שם חכם:"]],[[2,"ומנח תפילין","ואע\"ג שחולי מעיים פטורין מן התפילין לפי שאין יכולין ליזהר היטב אבל ר' היה מנהיג עצמו בקדושה יותר מדאי והיה יודע היטב ליזהר. מ\"ר:"],[5,"לא נהניתי אפילו באצבע קטנה","דאמרינן במדרש עד שאדם מתפלל שיכנס תורה לתוך גופו יתפלל שלא יכנסו מעדנים לתוך גופו ומייתי הא עובדא דרבי:"],[11,"ומרתא בת ביתוס עשרים וחמש שנים","אמר לי רבי דהך פירכא ליתא אליבא דבר קפרא דאמר לקמן לא שנו אלא מנה ומאתים אבל תוספת אית לה דלענין כתובה דאורייתא מרתא בת בייתוס וענייה שבישראל שוות אלא אליבא דר' יוחנן דאמר דאפילו תוספת אין לה איירי הכא ולי נראה דאליבא דכו\"ע איתא דהכא אליבא דרבי מאיר איירי ולקמן לא קאי בר קפרא אלא אליבא דרבנן דאמרי גובה כתובתה בבית אביה עד כ\"ה שנים והואיל ושהתה כל כך מחלתה ואמר בר קפרא דדוקא מנה ומאתים מחלה אבל תוספת דהויא כמו מתנה בעלמא לא מחלה כמו שאר בעל חוב דלא מחיל אבל לרבי מאיר דמפסדה משום שיש בעשרים וחמש שנה שתעשה טובה כנגד כתובה אין חילוק בין תוספת למנה ומאתים דלפום גמלא שיחנא דאי לא תימא הכי אלא אדר\"מ קאי אם כן מדקאמר דתוספת יש לה אלמא לית ליה דלפום גמלא שיחנא אם כן קשה לדידיה אלמנה דכתובתה מנה עד כ\"ה שנים ובתולה דכתובתה מאתים עד כ\"ה שנים ודומה לי דבר פשוט דאליבא דרבנן קאי לקמן דכולה סוגיא דלקמן מיירי אליבא דרבנן:"],[19,"היכי דמי אי דלא נקיטא כתובה במאי גביא","תימה אמאי לא דייק כמו כן במתניתין במאי גביא בשלא שהתה כ\"ה אלא לאו בנקיטא כתובה וקתני דמחלה בכ\"ה וי\"ל דאמתני' ליכא למיפרך דאיכא למימר דמתני' בעידי מיתה והא אליבא דרב קיימא דלדידיה (לעיל כתובות פט:) אלמנה גביא בעדי מיתה והא דקאמר אי דלא נקיט' כתובה בידה במאי גביא היינו גט דכמאן דכתב ביה מנה ומאתים דמי דלרב (שם) גרושה לא גביא אלא בגט:"]]],[["הרי היא כבתחלה ואם היה שטר כתובה יוצא מתחת ידיה גובה כתובתה לעולם","שלח ליה רב נחמן בר רב חסדא לרב נחמן בר יעקב ילמדנו רבינו כששטר כתובה יוצא מתחת ידה מחלוקת או כשאין שטר כתובה יוצא מתחת ידה והלכה כדברי מי","שלח ליה בשאין שטר כתובה יוצא מתחת ידה מחלוקת אבל שטר כתובה יוצא מתחת ידה גובה כתובתה לעולם והלכה כדברי חכמים","כי אתא רב דימי א\"ר שמעון בן פזי א\"ר יהושע בן לוי משום בר קפרא לא שנו אלא מנה מאתים אבל תוספת יש לה","ורבי אבהו א\"ר יוחנן אפילו תוספת אין לה דאמר רבי אייבו אמר רבי ינאי תנאי כתובה ככתובה דמי","אתמר נמי א\"ר אבא אמר רב הונא אמר רב לא שנו אלא מנה מאתים אבל תוספת יש לה","אמר ליה רבי אבא לרב הונא אמר רב הכי אמר ליה אישתיקן קאמרת או אשקיין קאמרת אמר ליה אישתיקן קאמינא:","חמתיה דרב חייא אריכא אינתת אחוה הואי ואלמנה בבית אביה הואי וזנה עשרים וחמש שנין בבי נשא","לסוף אמרה ליה הב לי מזוני אמר לה לית לך מזוני הב לי כתובה אמר לה לא מזוני אית לך ולא כתובה אית לך","תבעתיה לדינא קמיה דרבה בר שילא אמר ליה אימא לי איזי גופא דעובדא היכי הוה אמר ליה זניתה עשרים וחמש שנים בבי נשא בחיי דמר דבכתפאי אמטאי לה","אמר ליה טעמא מאי אמור רבנן כל זמן שהיא בבית בעלה גובה כתובתה לעולם דאמרינן משום כיסופא הוא דלא תבעה הכא נמי משום כיסופא הוא דלא תבעה זיל הב לה","לא אשגח כתב לה אדרכתא אניכסיה אתא לקמיה דרבא א\"ל חזי מר היכי דנן א\"ל שפיר דנך","אמרה ליה אי הכי ליזיל להדר לי פירי דמן ההוא יומא עד האידנא אמר לה אחוי לי אדרכתיך חזייה דלא הוה כתוב בה ואישתמודענא דנכסים אלו דמיתנא אינון אמר לה אדרכתא לאו שפיר כתיבא","אמרה ליה תיזיל אדרכתא אישקול מיומא דשלימי יומא אכרזתא עד השתא אמר לה הני מילי היכא דלא כתיב טעותא באדרכתא אבל היכא דכתיב טעותא באדרכתא לית לן בה","אמרה ליה והא מר הוא דאמר אחריות טעות סופר הוא","אמר לה רבא בהא ליכא למימר טעות סופר הוא דבהא אפי' רבה בר שילא טעי מעיקרא הוא סבור הני והני דידיה מה לי מהני מה לי מהני","ולא היא זימנין דאזלה ומשבחה להו ודבעלה מכספי ואמר לה שקיל דידך והב לי דידי ואתי לאפוקי לעז על בי דינא:","\u0001הדרן עלך הנושא\u0002","מתני׳ \u0001שני\u0002 דייני גזירות היו בירושלים אדמון וחנן בן אבישלום חנן אומר שני דברים אדמון אומר שבעה מי שהלך למדינת הים ואשתו תובעת מזונות חנן אומר"],[[0,"הרי היא כבתחלה","ומונה כ\"ה שנים משעת תביעה:"],[1,"והלכה כדברי מי","כדברי ר' מאיר או כדברי חכמים:"],[3,"לא שנו","דבכ\"ה שנים מחלה:"],[3,"אלא מנה מאתים","שהם שם כתובה:"],[3,"אבל תוספת יש לה","דמתנה היא ולאו כתובה:"],[4,"תנאי כתובה","תוספת:"],[6,"אישתיקן קאמרת או אשקיין קאמרת","האי דמתמהת ואמרת אמר רב הכי משום דלא סבירא לך הוא ולאשתיקן קאמרת או משום דחביבה עלך ולאשקיין קאמרת דאי אמרה רב משקית לי חמרא דשפיר אמר:"],[7,"אינתת אחוה הואי","ומת בלא בנים וירשו רב חייא אחיו:"],[8,"לא כתובה ולא מזוני","דאלמנה בבית אביה אינה גובה אלא עד כ\"ה שנים כרבנן:"],[9,"בכתפאי אמטאי לה","מזונותיה מיום ליום:"],[10,"הא נמי משום כיסופא","מחמת הכבוד הזה שעשית לה:"],[11,"אדרכתא","פסק דין לגבות נכסיו בכל אשר תמצא:"],[12,"אמרה ליה","לרבא:"],[12,"ליהדר לי פירי","דארעא דשיעור כתובתאי דאכל מיומא דאיכתיבא לי אדרכתא עלייהו שמאותו היום הם ברשותי דהכי אמר רבה בפ' המפקיד (ב\"מ דף לה:) גבי שומת ב\"ד לוקח מאימתי אכיל פירי אמר רבה מכי מטי אדרכתא לידיה אביי אמר משנחתמה רבא אמר מכי שלמו יומי אכרזתא:"],[12,"אישתמודענא","הכרנו שהנכסים הללו שכתבנו אדרכתא זו עליהם של מת היו ששיעבוד כתובתה של זו עליהם:"],[12,"לאו שפיר כתיבא","שנכתבה על כל שדות של זה ושדות שלו אינן משועבדות לכתובתיך אלא אותן שירש מבעליך:"],[13,"תיזיל אדרכתא","דלא שפיר כתיבא:"],[13,"אשקול","פירי מיום שמצאתי שדה משדות המת והראתי אדרכתא שבידי לבית דין ושמאוה והכריזו עליה ל' יום כמשפט דאפילו לרבא דמרע כח הלוקח טפי בפרק המפקיד (בבא מציעא דף לה:) מודה דמכי שלמו יומי אכרזתא אכיל לוקח פירי:"],[13,"אבל היכא","דאדרכתא בטעות כתיבא לא זכית בה עד דמטיא ארעא לידך שהרי מכח אדרכתא שמאוה בית דין והכריזו:"],[14,"והא מר הוא דאמר","בפרק שנים אוחזין (בבא מציעא דף טו:):"],[14,"אחריות טעות סופר הוא","שטר שאין בו אחריות גובה מנכסים משועבדים שלא הלוה זה מעות אלא באחריות שיעבוד נכסיו והסופר טעה הכא נמי ב\"ד צוו לסופר לכתוב אדרכתא הוגנת והוא טעה דלא כתב אישתמודענא והכל יודעים שלא נכתבה אלא על נכסי המת:"],[15,"בהא רבה בר שילא","שצוה לכתוב ליך אדרכתא טעה וסבור שתגבה מנכסים שלו:"],[16,"דאזלה ומשבחה להו","לשדה ששמו לה ב\"ד:"],[16,"ודבעלה מכספי","שלא ישביחם היורש שהוא בטוח שיחזור ויקח את שלו מידה ויאמר לה טלי שלי המשועבד ליך:"],[16,"ואתי לאפוקי לעז על בית דין","שלא עיינו בתקנתא של זו:"],[17,"","הדרן עלך הנושא"],[18,"מתני' שני דייני גזירות","מפרש בגמרא:"],[18,"חנן אומר שני דברים","שלא היו חכמים מודים לו:"]],[[3,"אמר רב הונא אמר רב לא שנו אלא מנה מאתים אבל תוספת יש לה","תימה א\"כ אמאי קאמר רב לעיל לא שנו אלא כשאין שטר כתובה יוצאה מתחת ידה אבל כששטר כתובה יוצאה מתחת ידה גובה כתובתה לעולם ומאי ראיה היא משום שטר כתובה הואיל ואינה גובה בה לרב:"],[9,"","ה\"ג אתיא לקמיה דרבה. דרבה מיבעי ליה למיהדר פירי מיומא דכתיבא אדרכתא דהכי סבירא ליה לרבה בפ' המפקיד (ב\"מ דף לה: ושם) אבל רבא סבירא ליה מכי שלימו יומי אכרזתא מיהו מדקאמרה והא מר הוא דאמר אחריות טעות סופר הוא נראה דגרסינן רבא דרבא הוא דאמר הכי בפ\"ק דב\"מ (דף טו: ושם) ומצינן למימר דשפיר גריס רבא והאי דקאמרה ליה ליזיל ולהדר פירי מן ההוא יומא דכתיבא אדרכתא עד האידנא היא אמרה כן אבל לרבא לא סבירא ליה הכי ומאי דקאמר לה רבא אחוי לי אדרכתא נראה לי לאו משום דאי הוה שפיר כתיבא אדרכתא דליהדר מיומא דכתיבא אדרכתא אלא משום דאי לא כתיבא אדרכתא שפיר דלא מיחייב לאהדורי פירי אפילו מכי שלמו יומי דאכרזתא כיון דבטעות כתיבא אדרכתא כדמסיק:"],[11,"ה\"ג אתיא לקמיה דרבה","דרבה מיבעי ליה למיהדר פירי מיומא דכתיבא אדרכתא דהכי סבירא ליה לרבה בפ' המפקיד (ב\"מ דף לה: ושם) אבל רבא סבירא ליה מכי שלימו יומי אכרזתא מיהו מדקאמרה והא מר הוא דאמר אחריות טעות סופר הוא נראה דגרסינן רבא דרבא הוא דאמר הכי בפ\"ק דב\"מ (דף טו: ושם) ומצינן למימר דשפיר גריס רבא והאי דקאמרה ליה ליזיל ולהדר פירי מן ההוא יומא דכתיבא אדרכתא עד האידנא היא אמרה כן אבל לרבא לא סבירא ליה הכי ומאי דקאמר לה רבא אחוי לי אדרכתא נראה לי לאו משום דאי הוה שפיר כתיבא אדרכתא דליהדר מיומא דכתיבא אדרכתא אלא משום דאי לא כתיבא אדרכתא שפיר דלא מיחייב לאהדורי פירי אפילו מכי שלמו יומי דאכרזתא כיון דבטעות כתיבא אדרכתא כדמסיק:"],[17,"","הדרן עלך הנושא"],[18,"מתני' שני דייני גזירות היו בירושלים אדמון וחנן בן אבישלום","הכי גורס ר\"ת דהא לר\"מ דאמר בפ' חלק (סנהדרין דף קג:) דאבשלום אין לו חלק לעולם הבא היכי מסקינן בשמיה הא אמרינן ביומא בפ' הממונה (דף לח:) ושם רשעים ירקב דלא מסקינן בשמייהו ואבישלום שם אדם כדכתיב (אביה בן אבישלום) והכי נמי הא דאמר בפ\"ק דשבת (דף יב: ושם) שבנא איש ירושלים לא גרסינן שבנא אלא שכנא דשבנא רשע הוה ויש מפרש דתרי שבנא היו דכתיב בישעיה (כ\"ב) כה אמר ה' צבאות לך בא אל הסוכן הזה אל שבנא אשר על הבית וכתיב בתריה מה לך פה וגו' הנה ה' מטלטלך וגו' הרי משמע שהיה רשע ואחריו כתוב בסוף (שם לז) ויהי כשמוע המלך חזקיהו ויקרע את בגדיו ויתכס בשק ויבא בית ה' וישלח [את] אליקים אשר על הבית ואת שבנא הסופר ואת זקני העם מתכסים בשקים וגו' הרי משמע דשבנא אחרינא היה ולאו מילתא היא דהוא נמי שבנא הראשון ואין מוקדם ומאוחר דבעל כורחיך ההוא בתרא דהיה במעשה דסנחריב רשע הוה דאמרי' (סנהדרין דף כו.) ששלח לסנחריב שבנא וסיעתו השלימו חזקיה וסיעתו לא השלימו וכשרצה לצאת הוא וסיעתו חוץ לחומה יצא הוא תחלה ובא גבריאל וסגר הדלת והרגו סנחריב ואז נתנבא עליו ישעיה הנה ה' מטלטלך ואף על גב דהכא קרי ליה סופר והתם על הבית מכל מקום אחד הוא. מ\"ר:"]]],[["תשבע בסוף ולא תשבע בתחלה נחלקו עליו בני כהנים גדולים ואמרו תשבע בתחלה ובסוף אמר רבי דוסא בן הרכינס כדבריהם אמר רבן יוחנן בן זכאי יפה אמר חנן לא תשבע אלא בסוף:","\u0001גמ׳\u0002 ורמינהי שלשה דייני גזילות היו בירושלים אדמון בן גדאי וחנן המצרי וחנן בן אבישלום קשיא תלת אתרין קשיא גזירות אגזילות","בשלמא תלת אתרין לא קשיא דחשיב ליה קתני דלא חשיב ליה לא קתני אלא גזירות אגזילות קשיא","אמר רב נחמן בר יצחק שהיו גוזרין גזירות על גזילות כדתניא קיטמה נטיעה ר' יוסי אומר גוזרי גזירות שבירושלים אומרים נטיעה בת שנתה שתי כסף בת שתי שנים ארבע כסף","ורמינהי שלשה דייני גזירות היו בירושלים אדמון וחנן ונחום א\"ר פפא מאן תנא נחום ר' נתן היא דתניא רבי נתן אומר אף נחום המדי מגוזרי גזירות שבירושלים היה ולא הודו לו חכמים","ותו ליכא והאמר ר' פנחס אמר רבי אושעיא שלש מאות ותשעים וארבעה בתי דינין היו בירושלים כנגדן בתי כנסיות וכנגדן בתי מדרשות וכנגדן בתי סופרים דיינין טובא הוו וכי קאמרינן אגוזרי גזירות קאמרינן","אמר רב יהודה אמר רב אסי גוזרי גזירות שבירושלים היו נוטלין שכרן תשעים ותשע מנה מתרומת הלשכה לא רצו מוסיפין להם לא רצו אטו ברשיעי עסקינן אלא לא ספקו אע\"פ שלא רצו מוסיפין עליהן","קרנא הוה שקיל איסתירא מזכאי ואיסתירא מחייב ודאין להו דינא והיכי עביד הכי והכתי' (שמות כג, ח) ושוחד לא תקח","וכ\"ת ה\"מ היכא דלא שקיל מתרוייהו דלמא אתי לאצלויי דינא קרנא כיון דשקיל מתרוייהו לא אתי לאצלויי דינא וכי לא אתי לאצלויי דינא מי שרי","והתניא ושוחד לא תקח מה ת\"ל אם ללמד שלא לזכות את החייב ושלא לחייב את הזכאי הרי כבר נאמר (דברים טז, יט) לא תטה משפט אלא אפי' לזכות את הזכאי ולחייב את החייב אמרה תורה ושוחד לא תקח","הני מילי היכא דשקיל בתורת שוחד קרנא בתורת אגרא הוה שקיל ובתורת אגרא מי שרי והתנן הנוטל שכר לדון דיניו בטלין הנ\"מ אגר דינא קרנא אגר בטילא הוה שקיל","ואגר בטילא מי שרי והתניא מכוער הדיין שנוטל שכר לדון אלא שדינו דין ה\"ד אילימא אגר דינא דינו דין והתניא הנוטל שכר לדון דיניו בטילין אלא אגר בטילא וקתני מכוער הדיין","הני מילי בטילא דלא מוכחא קרנא בטילא דמוכחא הוה שקיל דהוה תהי באמברא דחמרא ויהבי ליה זוזא","כי הא דרב הונא כי הוה אתי דינא לקמיה אמר להו הבו לי גברא דדלי לי בחריקאי ואידון לכו דינא","אמר רבי אבהו בא וראה כמה סמויות עיניהן של מקבלי שוחד אדם חש בעיניו נותן ממון לרופא ספק מתרפא ספק אינו מתרפא והן נוטלין שוה פרוטה ומסמין עיניהן שנאמר (שמות כג, ח) כי השוחד יעור פקחים","תנו רבנן (דברים טז, יט) כי השוחד יעור עיני חכמים קל וחומר לטפשין ויסלף דברי צדיקים קל וחומר לרשעים מידי טפשים ורשעים בני דינא נינהו אלא הכי קאמר כי השוחד יעור עיני חכמים אפילו חכם גדול ולוקח שוחד אינו נפטר מן העולם בלא סמיות הלב ויסלף דברי צדיקים"],[[0,"תשבע בסוף","כשישמעו בו שמת ותבא לגבות כתובתה תשבע שלא עכבה בידה משל בעלה כלום:"],[0,"ולא תשבע בתחלה","בשעת גיבוי מזונות:"],[1,"","גמ' אדמון בן גדאי:"],[3,"גוזרין גזירות","קנסות:"],[3,"","קיטמה נטיעה גרסינן בב\"ק גבי בהמה שנכנסה לרשות הניזק והזיקה קטמה נטיעת אילן כמה שמין אותה:"],[3,"שתי כסף","שתי מעות:"],[5,"בתי דינין","של עשרים ושלשה:"],[5,"בתי כנסיות","להתפלל:"],[5,"בתי מדרשות","למשנה ולתלמוד:"],[5,"בתי סופרים","ללמוד תינוקות:"],[6,"נוטלין שכרן","ומתפרנסין הימנו לפי שלא היו עסוקין במלאכתן:"],[6,"ברשיעי עסקינן","שנוטלין שכר לדון יותר מכדי חייהן:"],[6,"לא ספקו","למזונות:"],[6,"אע\"פ שלא רצו","ליטול:"],[7,"איסתירא","סלע:"],[10,"בתורת שוחדא","שלא תחייבני אם זכאי אני:"],[10,"בתורת אגרא","שכר טורח:"],[10,"הנוטל שכר לדון","משנה היא במס' בכורות (דף כט.):"],[10,"אגר דינא","לא אומר לכם הדין כי אם בשכר כך וכך:"],[10,"אגר בטילא","שהיה בטל ממלאכתו:"],[12,"דהוה תהי באמברי דחמרא","מריח באוצרות יין אי זה ראוי להתקיים והקרוב להתקלקל ימכרוהו מיד ושכר זה היה מצוי לו בכל יום:"],[13,"כי הא","דבטילא דמוכח שרי:"],[13,"הבו לי גברא דדלי","מיא משקה שדותי:"],[13,"בחריקאי","במקומי חריקאי אומר אני שהוא לשון פגום כמו קרנים חרוקות דשחיטת חולין (נט:) כלו' שאני מסתלק ונפגם מקומי:"]],[[1,"קשיא תלתא אתרין קשיא גזילות אגזירות","וא\"ת אדרבה אי גזילה וגזירה תרי מילי נינהו תלתא אתרי לא קשיא דדייני גזילה הוו תלתא דייני גזירות לא הוו אלא תרי ואמר רבי חדא דאינו סברא שתהא לדיין א' שתי שררות דכמה אנשים חשובים היו בירושלים שהיו יכולין לעמוד לכל שררה ושררה ועוד אי לאחד מהם הוו שתי שררות לחנן המצרי היה לו להיות שהיה חשוב יותר מחנן בן אבישלום כמו שפי' ר\"ת. מ\"ר:"],[2,"דחשיב ליה קתני","ואין לפרש דחשיב ליה יותר דהא מוכח בברייתא דחנן המצרי היה חשוב יותר מחנן בן אבישלום מדקתני ליה ברישא אלא ה\"פ דחשיב ליה בתר הכי דאיירי בהו מתני' חנן אומר שני דברים אדמון אומר שבעה קתני דלא חשיב ליה כגון חנן המצרי שלא דבר כלום לא קתני ולי נראה דחשיב ליה החשוב יותר ואף על גב דקתני חנן המצרי ברישא הכי נמי אשכחן מעשה ברבי אליעזר ור' יהושע ורבי אלעזר בן עזריה ור\"ע אע\"פ שר\"ע היה חשוב מרבי אלעזר בן עזריה שהוא היה ראש לחכמים ובכל דוכתי אמרינן (פסחים נ.) כגון ר\"ע וחבריו ובשילהי פ\"ק דיבמות (דף טז.) גבי מעשה דרבי דוסא בן הרכינס דאמר להם רבי יהושע אני אלך ואחריו מי רבי אלעזר בן עזריה ואחריו מי ר\"ע וכשנכנסו אצלו אמר לר' יהושע יש בן לעזריה חברינו הרי לא היה יודע שר' אלעזר בעולם ולר' עקיבא אמר אתה הוא ששמך הולך מסוף העולם ועד סופו ואפ\"ה מזכיר ר' אלעזר ברישא והיינו טעמא שהיה ממשפחה מיוחסת יותר מר\"ע שהיה עשירי לעזרא וגם בשביל נשיאותו הכא נמי דקתני חנן המצרי ברישא לא בשביל שהיה חשוב יותר אלא מפני שהוא ממשפחה מיוחסת יותר מחנן בן אבישלום ואומר רבי דמ\"מ תקשי לן אמאי לא משני כדמשני ר\"ת ולאו פירכא היא דאי תנא להו לפי שדברו במשנתנו הוה ליה למיתני שני דייני גזירות שהיו בירושלים אבל מדקתני היו בירושלים משמע שנים היו ותו לא ועוד מדתניא בסמוך רבי נתן אומר אף נחום המדי אחד מדייני גזירות שבירושלים היה ועל כרחך אברייתא לא קאי דא\"כ לר' נתן ארבע הוו ואנן מוקמינן דההיא דקתני שלשה אדמון וחנן ונחום המדי לרבי נתן אלא ודאי דחשיב ליה החשובין יותר משום הכי קאמר אף נחום המדי היה אחד מגוזרי גזירות והיה חשוב כמותם. מ\"ר:"],[2,"","קשיא תלתא אתרין קשיא גזילות אגזירות. וא\"ת אדרבה אי גזילה וגזירה תרי מילי נינהו תלתא אתרי לא קשיא דדייני גזילה הוו תלתא דייני גזירות לא הוו אלא תרי ואמר רבי חדא דאינו סברא שתהא לדיין א' שתי שררות דכמה אנשים חשובים היו בירושלים שהיו יכולין לעמוד לכל שררה ושררה ועוד אי לאחד מהם הוו שתי שררות לחנן המצרי היה לו להיות שהיה חשוב יותר מחנן בן אבישלום כמו שפי' ר\"ת. מ\"ר:"],[6,"גוזרי גזירות שבירושלים היו נוטלין שכרן מתרומת הלשכה","הא דלא פריך הכא והיכי עבדי הכי והכתיב ושוחד לא תקח כדפריך עליה דקרנא אומר ר\"ת משום דלא אסור אלא מבעלי דינים אבל הכא משל צבור ורבי מפרש דהכא לאו בתורת שכר היו נוטלין אלא הכא כל שעה היו יושבין בדין ולא היו עוסקין בשום מלאכה ולא היה להם במה להתפרנס והיה מוטל על הצבור לפרנסן אבל קרנא אקראי בעלמא היה יושב ולא היה לו ליטול שכר ומהאי טעמא נמי אתי שפיר הא דקאמר לקמן (כתובות דף קו.) מלמדי הלכות שחיטה והלכות קמיצה היו נוטלין שכרן מתרומת הלשכה אף על פי ששכר תלמוד תורה אסור כדאיתא בפרק אין בין המודר (נדרים דף לז.) מ\"ר:"]]],[["אפילו צדיק גמור ולוקח שוחד אינו נפטר מן העולם בלא טירוף דעת","כי אתא רב דימי אמר דרש רב נחמן בר כהן מאי דכתיב (משלי כט, ד) מלך במשפט יעמיד ארץ ואיש תרומות יהרסנה אם דומה דיין למלך שאינו צריך לכלום יעמיד ארץ ואם דומה לכהן שמחזר על הגרנות יהרסנה","אמר רבה בר רב שילא האי דיינא דשאיל שאילתא פסול למידן דינא ולא אמרן אלא דלית ליה לאושולי אבל אית ליה לאושולי לית לן בה","איני והא רבא שאיל שאילתא מדבי בר מריון אע\"ג דלא שיילי מיניה התם לאחשובינהו הוא דבעי","אמר רבא מאי טעמא דשוחדא כיון דקביל ליה שוחדא מיניה איקרבא ליה דעתיה לגביה והוי כגופיה ואין אדם רואה חובה לעצמו מאי שוחד שהוא חד א\"ר פפא לא לידון איניש דינא למאן דרחים ליה ולא למאן דסני ליה דרחים ליה לא חזי ליה חובה דסני ליה לא חזי ליה זכותא","אמר אביי האי צורבא מרבנן דמרחמין ליה בני מתא לאו משום דמעלי טפי אלא משום דלא מוכח להו במילי דשמיא","אמר רבא מריש הוה אמינא הני בני מחוזא כולהו רחמו לי כיון דהואי דיינא אמינא מינייהו סנו לי ומינייהו רחמו לי כיון דחזאי דמאן דמיחייב ליה האידנא קא זכי למחר אמינא אם מרחם כולהו רחמו לי אי מסנו כולהו סנו לי","ת\"ר (שמות כג, ח) ושוחד לא תקח אינו צריך לומר שוחד ממון אלא אפילו שוחד דברים נמי אסור מדלא כתיב בצע לא תקח היכי דמי שוחד דברים","כי הא דשמואל הוה עבר במברא אתא ההוא גברא יהיב ליה ידיה אמר ליה מאי עבידתיך אמר ליה דינא אית לי א\"ל פסילנא לך לדינא","אמימר הוה יתיב וקא דאין דינא פרח גדפא ארישיה אתא ההוא גברא שקליה א\"ל מאי עבידתיך א\"ל דינא אית לי אמר ליה פסילנא לך לדינא מר עוקבא הוה שדי רוקא קמיה אתא ההוא גברא כסייה א\"ל מאי עבידתיך א\"ל דינא אית לי א\"ל פסילנא לך לדינא","ר' ישמעאל בר' יוסי הוה רגיל אריסיה דהוה מייתי ליה כל מעלי שבתא כנתא דפירי יומא חד אייתי ליה בה' בשבתא א\"ל מאי שנא האידנא א\"ל דינא אית לי ואמינא אגב אורחי אייתי ליה למר לא קביל מיניה א\"ל פסילנא לך לדינא","אותיב זוזא דרבנן וקדיינין ליה בהדי דקאזיל ואתי אמר אי בעי טעין הכי ואי בעי טעין הכי אמר תיפח נפשם של מקבלי שוחד ומה אני שלא נטלתי ואם נטלתי שלי נטלתי כך מקבלי שוחד על אחת כמה וכמה:","ר' ישמעאל בר אלישע אייתי ליה ההוא גברא ראשית הגז אמר ליה מהיכא את א\"ל מדוך פלן ומהתם להכא לא הוה כהן למיתבא ליה א\"ל דינא אית לי ואמינא אגב אורחאי אייתי ליה למר א\"ל פסילנא לך לדינא לא קביל מיניה","אותיב ליה זוגא דרבנן וקדייני ליה בהדי דקאזיל ואתי אמר אי בעי טעין הכי ואי בעי טעין הכי אמר תיפח נפשם של מקבלי שוחד ומה אני שלא נטלתי ואם נטלתי שלי נטלתי כך מקבלי שוחד על אחת כמה וכמה:","רב ענן אייתי ליה ההוא גברא כנתא דגילדני דבי גילי א\"ל מאי עבידתיך א\"ל דינא אית לי לא קביל מיניה א\"ל פסילנא לך לדינא","אמר ליה דינא דמר לא בעינא קבולי לקביל מר דלא למנען מר מאקרובי בכורים דתניא (מלכים ב ד, מב) ואיש בא מבעל שלישה ויבא לאיש האלהים לחם בכורים עשרים לחם שעורים וכרמל בצקלונו וכי אלישע אוכל בכורים הוה אלא לומר לך כל המביא דורון לתלמיד חכם כאילו מקריב בכורים","אמר ליה קבולי לא בעינן דאיקביל השתא דאמרת לי טעמא מקבילנא שדריה לקמיה דרב נחמן שלח ליה נידייניה מר להאי גברא דאנא ענן פסילנא ליה לדינא אמר מדשלח לי הכי שמע מינה קריביה הוא הוה קאים דינא דיתמי קמיה אמר"],[[0,"אינו נפטר מן העולם","והכי קאמר ק\"ו שיסמא את עיניו כשיהא טפש בסופו וישב לדון:"],[1,"שאינו צריך כלום","שהוא עשיר ואין צריך להחניף:"],[2,"דשאיל שאילתא","דרגיל לישאל מבני עירו בהמות וכלים:"],[4,"מאי טעמא דשוחדא","למה אסור ליטלו לזכות את הזכאי:"],[4,"אין אדם רואה חובה לעצמו","אין דעתו מתקרב לצד החובה לחייב את עצמו ואפילו מתכוין לדין אמת:"],[4,"שהוא חד","הנותן והמקבל נעשים לב אחד:"],[6,"בני מחוזא","עירו של רבא:"],[6,"מינייהו","מקצתם אוהבים אותי אותם שזכיתי:"],[6,"אם מרחם","אם אוהבים נעשו כולם אוהביי:"],[8,"במברא","גשר:"],[8,"יהיב ליה ידא","לסומכו:"],[10,"כנתא דפירי","סל פירות מפרדס של רבי ישמעאל:"],[11,"זוזא","זוג:"],[11,"בהדי דאזיל ואתי","בכל אשר הולך ובא היה לבו לזכותו של אותו אריס ובאין לו פתחי זכיות ואומר בלבו הלואי ויטעון כך וכך ויזכה בדין:"],[12,"ראשית הגז","בכל שנה שגוזז אותן חייב ליתן לכהן אחד מששים:"],[14,"גילדני דבי גילי","דגים קטנים:"],[15,"וכי אלישע אוכל ביכורים היה","והלא לא כהן היה שהרי מצינו בדברי הימים שנתייחס אביו על שבט גד דכתי' ויעני ושפט בבשן ומצינו במסכת פסחים באלו דברים (פסחים דף סח.) דשפט דהאי קרא הוא אביו של אלישע:"],[16,"שמע מינה קריביה הוא","להכי פסול ליה לדינא:"]],[[0,"אפילו צדיק גמור ונוטל שוחד","והיינו ק\"ו לרשעים שכבר נטל שוחד בפעם ראשונה דבפעם ראשונה כשנוטל אכתי צדיק הוי שעדיין לא נטלו וק\"ו לטפשים בפעם שניה שנוטל שוחד שכבר נעשה טפש מפעם ראשונה שנטלו. מ\"ר. ורשב\"ם פי' דהאי קל וחומר לטפשים אינו מן הברייתא אלא מדתניא חכמים וצדיקים משמע שרוצה לומר ק\"ו לטפשים ולכך מתמה וכי הם בני דינא ומשני הכי קאמר ולא נידוק כמו שאמר והכי נמי אמרינן בהמקבל בסופו (ב\"מ דף קיד:) ת\"ר אם איש עני הוא לא תשכב בעבוטו ומשמע הא עשיר שכב ומשני הכי קאמר:"],[1,"מאי דכתיב מלך במשפט יעמיד ארץ אם דומה דיין למלך שאינו צריך לכלום","הכא משמע דצריכות ממון קאמר משום שוחד מדמסיק עליה האי דיינא דשאיל שאילתא ולעיל נמי ממילי דשוחד איירי ובסנהדרין בפ\"ק (דף ז: ושם) מייתי הך דרשא גופה דרב נחמן בר כהן אדיין שאינו בקי וצריך לשאול הוראות ודינין דמסיק התם דרש רב נחמן בר כהן מאי דכתיב מלך במשפט יעמיד ארץ ובתר הכי מסיק דבי נשיאה אוקמו דיינא דלא גמיר וכולה שמעתא דהתם מיירי בדיינא שאינו הגון מחמת שאינו בקי ואומר ר\"ת דמהאי קרא איכא למידק שאינו צריך לא לממון ולא לדברי תורה. מ\"ר:"],[4,"לא למאן דסני ליה ולא למאן דרחים ליה","לאו באוהב ושונא דאיירי ביה רבי יהודה ורבנן גבי עדות איירי דלגבי דיין אפי' רבנן מודו דפסול כדמסיק מקרא בפ' זה בורר (סנהדרין דף כט.) דא\"כ הוה ליה לאתויי הכא קרא דהתם אלא התם באוהב כגון שושבינו ושונא שלא דיבר עמו שלשה ימים אבל הכא באוהב כי הנך דפרח גדפא ארישא אתא ההוא גברא שקליה דאינו אלא חומרא בעלמא שהיו מחמירין על עצמן כדאשכחן בכמה דברים אבל פסולין לא הוו. מ\"ר:"],[8,"","לא למאן דסני ליה ולא למאן דרחים ליה. לאו באוהב ושונא דאיירי ביה רבי יהודה ורבנן. גבי עדות איירי דלגבי דיין אפי' רבנן מודו דפסול כדמסיק מקרא בפ' זה בורר (סנהדרין דף כט.) דא\"כ הוה ליה לאתויי הכא קרא דהתם אלא התם באוהב כגון שושבינו ושונא שלא דיבר עמו שלשה ימים אבל הכא באוהב כי הנך דפרח גדפא ארישא אתא ההוא גברא שקליה דאינו אלא חומרא בעלמא שהיו מחמירין על עצמן כדאשכחן בכמה דברים אבל פסולין לא הוו. מ\"ר:"],[15,"וכי אלישע אוכל בכורים היה","אין צריך לדחוק כפי' הקונטרס דהכי פי' וכי אלישע אוכל בכורים היה והלא בשומרון היה ואין בכורים נאכלין חוץ לחומה כדמוכח בריש אלו הן הלוקין (מכות יז.) ובפ' בהמה המקשה (חולין דף סח: ושם) והכי איתא בהדיא בסדר אליהו זוטא דתלמידי חכמים כפרה להם לישראל בכל מקום מושבותיהם שנא' תקריב מנחת בכורים ואומר ואיש בא מבעל שלישה וגו' וכי אלישע אוכל בכורים היה והלא אין שם מקדש ולא מזבח ולא כהן גדול אלא אלישע ותלמידיו יושבין לפניו מכאן אמרו וכו':"]]],[["האי עשה והאי עשה עשה דכבוד תורה עדיף סלקיה לדינא דיתמי ואחתיה לדיניה כיון דחזא בעל דיניה יקרא דקא עביד ליה איסתתם טענתיה:","רב ענן הוה רגיל אליהו דאתי גביה דהוה מתני ליה סדר דאליהו כיון דעבד הכי איסתלק יתיב בתעניתא ובעא רחמי ואתא כי אתא הוה מבעית ליה בעותי","ועבד תיבותא ויתיב קמיה עד דאפיק ליה סידריה והיינו דאמרי סדר דאליהו רבה סדר אליהו זוטא","בשני דרב יוסף הוה ריתחא אמרי ליה רבנן לרב יוסף ליבעי מר רחמי אמר להו השתא ומה אלישע דכי הוו רבנן מיפטרי מקמיה הוו פיישי תרי אלפן ומאתן רבנן בעידן ריתחא לא הוה בעי רחמי אנא איבעי רחמי","וממאי דפיישי הכי דכתיב (מלכים ב ד, מג) ויאמר משרתו מה אתן זה לפני מאה איש מאי לפני מאה איש אילימא דכולהו לפני מאה איש בשני בצורת טובא הוו אלא דכל חד וחד קמי מאה איש","כי הוו מיפטרי רבנן מבי רב הוו פיישי אלפא ומאתן רבנן מבי רב הונא הוו פיישי תמני מאה רבנן רב הונא הוה דריש בתליסר אמוראי כי הוו קיימי רבנן ממתיבתא דרב הונא ונפצי גלימייהו הוה סליק אבקא וכסי ליה ליומא ואמרי במערבא קמו ליה ממתיבתא דרב הונא בבלאה","כי מיפטרי רבנן מבי רבה ורב יוסף הוו פיישי ארבע מאה רבנן וקרו לנפשייהו יתמי כי הוו מיפטרי רבנן מבי אביי ואמרי לה מבי רב פפא ואמרי לה מבי רב אשי הוו פיישי מאתן רבנן וקרו נפשייהו יתמי דיתמי","א\"ר יצחק בר רדיפא א\"ר אמי מבקרי מומין שבירושלים היו נוטלין שכרן מתרומת הלשכה אמר רב יהודה אמר שמואל ת\"ח המלמדין הלכות שחיטה לכהנים היו נוטלין שכרן מתרומת הלשכה","אמר רב גידל אמר רב ת\"ח המלמדים הלכות קמיצה לכהנים נוטלין שכרן מתרומת הלשכה אמר רבה בר בר חנה אמר ר' יוחנן מגיהי ספרים שבירושלים היו נוטלין שכרן מתרומת הלשכה","אמר רב נחמן אמר רב נשים האורגות בפרכות נוטלות שכרן מתרומת הלשכה ואני אומר מקדשי בדק הבית הואיל ופרכות תחת בנין עשויות","מיתיבי נשים האורגות בפרכות ובית גרמו על מעשה לחם הפנים ובית אבטינס על מעשה הקטרת כולן היו נוטלות שכרן מתרומת הלשכה","התם בדבבי דאמר רבי זירא אמר רב שלשה עשר פרכות היו במקדש שני שבעה כנגד שבעה שערים אחד לפתחו של היכל ואחד לפתחו של אולם ב' בדביר ב' כנגדן בעליה:","ת\"ר נשים המגדלות בניהן לפרה היו נוטלות שכרן מתרומת הלשכה אבא שאול אומר נשים יקרות שבירושלים היו זנות אותן ומפרנסות אותן","בעא מיניה רב הונא מרב"],[[0,"האי עשה והאי עשה","מצות הדיינים עשה ושפטתם צדק:"],[0,"עשה דכבוד תורה","דיניה דהאי גברא דהוא עשה דאיכא כבוד תורה דרב ענן בהדיה עדיף:"],[2,"סדר אליהו רבה","שלמד חוץ לתיבה סדר אליהו זוטא שלמד בתוך התיבה:"],[3,"הוה ריתחא","כעס של מקום ובא רעב לעולם:"],[3,"דכי מיפטרי","תלמידיו ממנו לעמוד מבית המדרש:"],[3,"הוו פיישי גביה","אוכלי שלחנו תרי אלפים ומאתים דכתיב עשרים לחם ולחם בכורים הא עשרים וחד וכרמל הרי עשרים ותרתין וכל אחד לפני מאה איש הרי תרי אלפין ומאתים:"],[5,"בתליסר אמוראי","השומעין מפיו ומשמיעין לרבים זה מכאן וזה מכאן ומלפנים ומלאחור ומתחלקין למקומות הרבה שהיה העם רב:"],[5,"וכסי ליה ליומא","מאפיל את החמה והיה ניכר בא\"י:"],[8,"מגיהי ספרים","של כל אדם ואדם שאסור להשהות ספר שאינו מוגה משום אל תשכן באהליך עולה וראו בית דין שהיו מתעצלין בדבר והפקירו תרומת הלשכה לכך:"],[10,"","בית אבטינס ובית גרמו במסכת יומא (דף לח.):"],[11,"בדבבי","בפרכות שכנגד הפתחים דלצניעותא עבידי ואינן תחת בנין אבל כל צורך בנין כגון פרכות המבדילות בין היכל לקדשי הקדשים שהיו במקדש שני במקום אמה טרקסין שעשה שלמה בבנין ראשון ואנשי הגולה עשו את ההיכל גבוה מאד ולא יכול בנין בעובי אמה להתקיים בגובה כזה ולהרחיבו לא יכלו לפי שמקצרים את ההיכל או את קדשי הקדשים ועשו שתי פרכות וביניהם אמה כדאמרינן במסכת יומא (דף נא:) ואותן פרכות נעשו מקדשי בדק הבית:"],[11,"ז' שערים","לעזרה:"],[11,"שתים בדביר","תחת אמה טרקסין:"],[11,"ושתים כנגדן בעליה","להבדיל בין עליית היכל לעליית קדשי הקדשים וגם הן במקום אמה טרקסין:"],[12,"המגדלות בניהן לפרה","בחצרות הבנויות בסלעים בירושלים ותחתיהם חלל מפני קבר התהום כדתנן במס' פרה (פ\"ג משנה ב') ומייתינן לה בפרק הישן תחת המטה (סוכה דף כא.) ובאין נשים עוברות ויולדות שם ומגדלות שם בניהם לצורכי פרה אדומה לעסוק בשריפתה ומילוי מימיה ולהזות כל שבעה על כהן השורפה כדאמרינן במסכת יומא (דף ד.) ומעלה זו עשו לה להתעסק בה תינוקות שלא נטמאו מימיהם מפני שזלזלו בה לעשותה בטבול יום כדתנן מטמאין היו הכהן השורף את הפרה ומטבילין אותו להוציא מלבן של צדוקין שהיו אומרין במעורבי שמש היתה נעשית:"],[12,"נשים יקרות","עשירות:"],[12,"מפרנסות","בלבוש וכסות:"]],[[2,"והיינו דאמרינן סדר אליהו רבה וסדר אליהו זוטא","א\"ר לפי שהפסיק בלמודו לרב ענן חלקו לשני סדרים ובפעם ראשון למד ממנו יותר מן הארבע ידות קרי לראשון סדר אליהו רבה ולבתרא קרי זוטא:"],[7,"מבקרי מומין שבירושלים היו נוטלין שכרן","תימה דהתנן בבכורות פרק עד כמה (בכורות דף כט: ושם) הנוטל שכר להיות רואה בכורות אין שוחטין אותן על פיו וי\"ל כמו שתרצתי למעלה ועוד דהתם דוקא בבכורות שיש לחוש שמא משום שכר יתירנו אבל הכא מיירי בבדיקת מומי שאר קדשים והכי איתא בשילהי פרק התרומה בשקלי' (דף ז.) דאמר מבקרי מומי קדשים נוטלים שכרן מתרומת הלשכה:"],[8,"מלמדין הלכות קמיצה","והא דלא חשיב הלכות מליקה שבכלל הלכות שחיטה הן:"],[11,"שבעה כנגד ז' שערים","לשבעה שערי עזרה קאמר אומר רבי דס\"ל כתנא דמתני' דמס' מדות בפ\"ק (משנה ד) דתנן ז' שערים היו בעזרה ג' בצפון וג' בדרום ואחד במזרח והא דתנן התם לעיל בשלשה מקומות הכהנים שומרים כו' על חמשה שערי העזרה כו' במס' תמיד בפ\"ק (דף כז.) פריך להו ומשני אביי תרי מנייהו לא בעי שימור ורבא משני תנאי היא דתניא אין פוחתין [מג' גזברין וז' אמרכלין רבי נתן אומר אין פוחתין] מי\"ג גזברים כנגד י\"ג שערים דל חמשה דהר הבית פשו להו תמניא אלו ח' דעזרה אלמא איכא תנא דאמר תמניא הוו ואיכא תנא דאמר חמשה הוו תימה אמאי מייתי רבא הנך תנאי ממתניתין דמדות היה יכול להביא דתנן התם בפ' שני (משנה ו) שלש עשרה השתחוואות היו שם אבא יוסף בן חנן אומר כנגד י\"ג שערים ועוד תימה דהרי כאן מחלוקת רביעי דעל כרחין לההוא תנא דס\"ל די\"ג שערים היו בעזרה לא מצי למימר דקסבר ח' ודל חמשה דהר הבית דהא מפרש התם שמם של אותן שערים ואין מזכירין אפי' אחד מאותן שערים דהר הבית המפורש בפ\"ק דמדות שני שערי חולדה מן הדרום וקיפונוס מן המערב וטדי מן הצפון שער מזרחי שושן הבירה עליו צורה ואומר ר\"ת דלעולם ס\"ל לההוא תנא דז' שערים היו בעזרה והא דחשיב י\"ג היינו עם השערים הקטנים דהכל חשיב תדע דהא חשיב פישפשין שהיו לשער נקנור אבל גדולים לא היו בעזרה אלא ז' והן אותן המפורשים בפ\"ק והמעיין שם ימצא דשער הקרבן דפ\"ק הוא שער הבכורות דפ\"ב ואותן י\"ג שערים דמדות שנויים נמי במסכת שקלים כל אותה משנה ממש בפ' י\"ג שופרות אבל אין שנוי בה אבא יוסף בן חנן כמו ששנוי במס' מדות ובגמרא דירושלמי קאמר מתני' אבא יוסף בן חנן דקאמר כנגד י\"ג שערים דלרבנן ז' שערים הוו בעזרה דעתייהו דרבנן היכן היו השתחוואות האלו כי ההיא דתנינן תמן י\"ג פרצות היו בה שפרצו מלכי יון וחזרו וגדרום וגזרו כנגדם י\"ג השתחוואות ואם תאמר לרבנן נמי דתני שבעה שערים מאי קמתמה כנגד מי הוו השתחוואות אינהו נמי מודו דעם הקטנים היו שלשה עשר כדפרישית ואומר רבינו תם כיון דלא חשיבי בעינייהו כל כך שיקראו אותם שערים אין נראה שיהא השתחוואות כנגדם אבל אבא יוסף בן חנן קרא אותם שערים. מ\"ר:"]]],[["כלי שרת מהו שיעשו מקדשי בדק הבית צורך מזבח נינהו ומקדשי בדק הבית אתו או צורך קרבן נינהו ומתרומת הלשכה היו עושין אותן א\"ל אין נעשין אלא מתרומת הלשכה","איתיביה (דברי הימים ב כד, יד) וככלותם הביאו לפני המלך ויהוידע (הכהן) את שאר הכסף ויעשהו כלים לבית ה' כלי שרת וגו'","א\"ל דאקרייך כתובי לא אקרייך נביאי (מלכים ב יב, יד) אך לא יעשה בית ה' ספות וגו' כי לעושי המלאכה יתנוהו","אי הכי קשו קראי אהדדי לא קשיא כאן שגבו והותירו כאן שגבו ולא הותירו","וכי גבו והותירו מאי הוי א\"ר אבהו לב ב\"ד מתנה עליהן אם הוצרכו הוצרכו ואם לאו יהו לכלי שרת","תנא דבי רבי ישמעאל כלי שרת באין מתרומת הלשכה שנאמר את שאר הכסף איזהו כסף שיש לו שיריים הוי אומר זה תרומת הלשכה","ואימא שיריים גופייהו כדאמר רבא העולה עולה ראשונה ה\"נ הכסף כסף ראשון","מיתיבי הקטורת וכל קרבנות צבור באין מתרומת הלשכה מזבח הזהב ולבונה וכלי שרת באין ממותר נסכים","מזבח העולה הלשכות והעזרות באין מקדשי בדק הבית חוץ לחומת העזרה באין משירי הלשכות זו היא ששנינו חומת העיר ומגדלותיה וכל צרכי העיר באין משירי הלשכה","תנאי היא דתנן מותר תרומה מה היו עושין בה ריקועי זהב ציפוי לבית קדשי הקדשים ר' ישמעאל אומר מותר פירות לקיץ המזבח מותר תרומה לכלי שרת","ר\"ע אומר מותר תרומה לקיץ המזבח מותר נסכים לכלי שרת רבי חנינא סגן הכהנים אומר מותר נסכים לקיץ המזבח מותר תרומה לכלי שרת וזה וזה לא היו מודים בפירות","פירות מאי היא דתניא מותר תרומה מה היו עושין בה לוקחין פירות בזול ומוכרין אותם ביוקר והשכר מקיצין בו את המזבח וזו היא ששנינו מותר פירות לקיץ המזבח","מאי זה וזה לא היו מודין בפירות דתנן מותר שירי לשכה מה היו עושין בהן לוקחין בהן יינות שמנים וסלתות והשכר להקדש דברי ר' ישמעאל רבי עקיבא אומר אין משתכרין בשל הקדש אף לא בשל עניים","בשל הקדש מאי טעמא לא אין עניות במקום עשירות בשל עניים מאי טעמא לא דלמא מתרמי להו עניא וליכא למיתבא ליה:","מי שהלך למדינת הים: איתמר רב אמר"],[[0,"כלי שרת","שמשרתין בהן במזבח החיצון שהוא בנין של אבנים:"],[1,"וככלותם","לחזק את בדק הבית בימי יהואש ופסוק זה בדברי הימים:"],[3,"שגבו","לצורך בדק הבית והותירו שאין צריכין לכולו עושין מן המותר כלי שרת:"],[4,"מאי הוי","הא לא לקדושת קרבן גבו:"],[5,"כסף שיש לו שיריים","כסף הקופות שהוא נתרם מן הלשכה ושיריים נשארים בלשכה:"],[5,"זה תרומת הלשכה","כסף שבקופות:"],[6,"ואימא שיריים גופייהו","משיריים הנותרים בלשכה כלי שרת באין ולא מן התרומה עצמה:"],[6,"העולה עולה ראשונה","מנין שלא יהא דבר קודם על המערכה לתמיד של שחר ת\"ל וערך עליה העולה והוינן בה מאי תלמודא ואמר רבא העולה משמע העולה האמורה ראשון בסדרי קרבנות והיא עולת הבקר שנא' ואמרת להם זה האשה כו' וה\"א יתירא קא דריש וה\"נ את שאר הכסף בכסף שיש לו שאר:"],[7,"מזבח הזהב","כלי הוא ולא בנין שאינו מחובר לאדמה ויכולין לטלטלו לפיכך נידון ככלי:"],[7,"ולבונה","של לחם הפנים:"],[7,"מותר נסכים","פליגי בה במס' מנחות בפרק שתי מדות (מנחות דף צ.) רבי חייא ב\"ר יוסף אמר בירוצי מדות שהמספקין סלתות שקבלו מעות הקדש לספק סלתות כל ימות השנה מודדין להקדש במדה מבורצת טפופה ולא מחוקה והמקריבן מוחק המדה והם מותר נסכים ומוכרים אותן ור' יוחנן אמר כאותה ששנינו המקבל עליו לספק [כל ימות השנה להקדש] סלתות מארבע סאין בסלע ועמדו משלש שנתייקרו מספק מארבע והמקבל לספק משלש והוזלו ועמדו מד' מספק ד' וזו היא ששנינו מותר נסכים לקיץ המזבח:"],[8,"מזבח העולה","שהוא בנין בא מקדשי בדק הבית:"],[8,"חוץ לחומת העזרה","כגון עזרת נשים והחיל וחומת העיר ומגדלותיה באים משיריים הנותרים בלשכה כשתרמוה בקופות:"],[9,"תנאי היא","דאיכא למאן דאמר כלי שרת מתרומת הלשכה באין:"],[9,"מותר תרומה","הנשאר בקופות בר\"ח ניסן שמכאן ואילך אין לוקחין קרבנות צבור אלא מתרומה חדשה כדאמרינן בר\"ה (דף ז.) קרבנות צבור הבאין באחד בניסן מצוה להביא מן החדש:"],[9,"ציפוי לבית קדשי הקדשים","מחפין בהם הרצפה והכתלים:"],[9,"","מותר ריוח פירות ולקמן מפרש מאי ניהו:"],[10,"לקיץ המזבח","כשהוא בטל מנדרים ונדבות לוקחין עולות ומקריבין בשר למזבח ועורות לכהנים:"],[10,"וזה וזה","ר' עקיבא ור' חנינא:"],[10,"לא היו מודין","שיהא שום מותר בפירות:"],[11,"והשכר מקיצין בהן","והקרן לכלי שרת כדקאמר רבי ישמעאל:"],[12,"מאי זה וזה לא היו מודים","מאי פירושא דלא היו מודים כדתנן דפליג ר\"ע אדרבי ישמעאל ולא הודה לו שיהו משתכרין בשל הקדש:"]],[[4,"וכי גבו והותירו מאי הוי","אבל אהנך דלעיל לא פריך בית גרמו ובית אבטינס דבכל הנהו היו בית ישראל מקדישין אותן לצורך כך כמו לצורך קרבנות שכל אותן דברים רגילות הן והיינו דקתני דבאין מתרומת הלשכה עצמה ולא קתני מותר היינו משום דלאו מחמת לב ב\"ד מישתרו אלא מחמת ישראל אבל להך תירוצא פריך דמסיק היכא דלא הותירו אסירי והיכא דהותירו שרי פריך מאי שנא דהא פשיטא שלא לדעת כן מקדישין כיון דלא שרית ליה כי לא הותירו ומשני לב ב\"ד מתנה עליהן והן מקדישין לדעת ב\"ד:"],[5,"תנא דבי רבי ישמעאל כלי שרת באין מתרומת הלשכה","הא תרומת הלשכה היינו מותר תרומת הלשכה כדמוכח במתני' דפליג אר\"ע דקתני מותר תרומה לכלי שרת וא\"ת כי פריך הש\"ס ואימא שיריים גופייהו והיינו משום דכתיב שאר ולישני דהא שאר הכסף היינו מותר תרומה י\"ל דבמילתא דפסיקא ליה בעי לאוקמי קרא דהיינו שיריים דבכל שנה איתנהו אבל במותר דלא פסיקא ליה לא ניחא ליה לאוקמי לקרא:"],[6,"כדאמר רבא העולה עולה ראשונה","תימה אמאי איצטריך האי דרשא דרבא תיפוק ליה מהיכא דמפקא מתניתין דזבחים בפרק כל התדיר (זבחים דף פט. ושם) דקתני כל התדיר מחבירו קודם לחברו התמידים קודמין למוספים כו' וקא בעי בגמרא מנ\"ל ומתמה מנא לן כדקתני טעמא מלבד עולת הבקר אשר לעולת התמיד וכ\"ת דהתם איצטריך היכא דליכא אלא חד דאשמעינן קרא דעקרינן לגמרי מוספין מקמי תמידין לא היא דמהתם נפקא לן בכ\"מ דתדיר ושאינו תדיר תדיר קודם כדמפיק התם מכאלה תעשו שיהו כל עשיות שוות ואי בכי האי גוונא מיירי מהתם לא נפקא לן ועוד מסברא רישא דכל התדיר מחבירו קודם לחבירו מיתניא דומיא דבבא שאחריה דקתני כל המקודש מחבירו קודם לחבירו דם חטאת קודם לדם עולה מפני שהוא מרצה כו' וכל הנך בקדימה ממש מיירי והא נמי ליכא לתרוצי דאי מהתם דמלבד עולת הבקר הוה אמינא דווקא עולה דקדמה למוספין משום דתדירא ומוספין לא תדירי אבל תמידין לעולת נדבה דהויא ליה נמי תדירא לעולם אימא לך לא תקדום להכי איצטריך קרא דהעולה עולה ראשונה דבמנחות פרק התכלת (מנחות דף מט. ושם) מייתי לקרא דרבא אקדימה דעולה למוספין דאמרי' התם בעא מיניה רב חייא בר אבא מרב חסדא צבור שאין להם תמידין ומוספין אי זה מהם קודם כו' ומסיק אמר ליה תניתוה התמידין אין מעכבין את המוספין ולא המוספין את התמידים ה\"ד אילימא דאית ליה וליקדם והתניא מנין שלא יהא דבר קודם לתמיד של שחר ת\"ל וערך עליה העולה ואמר רבא כו' אלא בדלית ליה ואי בתמידין ומוספין דהיום פשיטא שתדיר קודם אלא במוספין דהיום ותמידין דלמחר אלמא אקדימה דעולה למוספין מייתי לה ותימה דרשת המשנה הוה ליה לאיתויי דקתני בהדיא מלבד עולת הבקר ובההיא דשילהי הגוזל קמא (ב\"ק דף קיא. ושם) קשה יותר דקתני הביא אשמו עד שלא הביא גזילו לא יצא ומפרש בגמ' מלבד איל הכפורים מכלל דכסף קדים ופריך אלא מעתה מלבד עולת הבקר ה\"נ דמוספין ברישא והא תניא מנין שלא יהא דבר כו' ואמר רבא העולה עולה ראשונה והשתא הוה ליה לאתויי מתני' דכל התדיר דאדרבה מדכתי' מלבד מכלל דעולה קדמה ונרא' לפרש דודאי מדכתי' העולה נפקא דהקטרת תמיד קדמה להקטרת מוספין דגבי הקטרה הוא דכתי' מלבד עולת הבקר אשר לעולת התמיד תעשו את אלה התם עשוי דדם נינהו והשתא בב\"ק לא הוה מצי לאתויי מתני' דכל התדיר דודאי גבי איל הכפורים משמע לשון מלבד דכסף קדים כיון דהוא כתוב תחלה בפרשה והדר כתיב איל הכפורים אבל גבי עשיות ליכא למידק דמוספין קדמי כיון דכתיב עולה ברישא והדר עשיה דדם דמוספין אבל הקטרה דמוספין כתיב ברישא להכי פריך שפיר מההוא דרבא ומיהו בההוא דמנחות ודאי הוה מצי לאתויי ההיא דכל התדיר:"]]],[["פוסקין מזונות לאשת איש ושמואל אמר אין פוסקין מזונות לאשת איש אמר שמואל מודה לי אבא בשלשה חדשים הראשונים לפי שאין אדם מניח ביתו ריקן","בששמעו בו שמת כולי עלמא לא פליגי כי פליגי בשלא שמעו בו שמת רב אמר פוסקין דהא משועבד לה ושמואל אמר אין פוסקין","מ\"ט רב זביד אמר אימא צררי אתפסה רב פפא אמר חיישינן שמא אמר לה צאי מעשה ידיך במזונותיך","מאי בינייהו איכא בינייהו גדולה ולא ספקה","אי נמי קטנה וספקה","תנן מי שהלך למדינת הים ואשתו תובעת מזונות חנן אמר תשבע בסוף ולא תשבע בתחלה נחלקו עליו בני כהנים גדולים ואמרו תשבע בתחלה ובסוף עד כאן לא פליגי אלא לענין שבועה אבל מזוני יהבינן לה תרגמה שמואל בששמעו בו שמת","תא שמע מי שהלך למדינת הים ואשתו תובעת מזונות בני כהנים גדולים אומרים תשבע חנן אומר לא תשבע ואם בא ואמר פסקתי לה מזונות נאמן","הכא נמי בששמעו בו שמת והא אם בא ואמר קאמר אם בא לאחר שמועה","ת\"ש מי שהלך למדינת הים ואשתו תובעת מזונות ואם בא ואמר צאי מעשה ידיך במזונותיך רשאי קדמו בית דין ופסקו מה שפסקו פסקו הכא נמי בששמעו בו שמת","ת\"ש מי שהלך למדינת הים ואשתו תובעת מזונות ב\"ד יורדים לנכסיו וזנין ומפרנסין לאשתו אבל לא בניו ובנותיו ולא דבר אחר","אמר רב ששת במשרה את אשתו ע\"י שליש אי הכי בניו ובנותיו נמי כשהשרה לזו ולא השרה לזו מאי פסקא","אלא אמר רב פפא כששמעה בו שמת בעד אחד היא דאי בעית אינסובי בעד אחד מצי מינסבא מזוני נמי יהבינן לה","בניו ובנותיו דאי בעו למיחת לנכסיו בעד אחד לא מצו נחתי מזוני נמי לא יהבינן להו","מאי דבר אחר רב חסדא אמר תכשיט רב יוסף אמר צדקה מ\"ד תכשיט כל שכן"],[[0,"פוסקין מזונות","ב\"ד יורדין לנכסי מי שהלך למדינת הים ופוסקין מזונות לאשתו:"],[1,"בששמעו בו שמת כ\"ע לא פליגי","דפוסקין דלמאי ניחוש לה אי לצררי הרי סופה לגבות כתובתה ותשבע שלא עיכבה משלהם כלום ואי לשמא אמר לה צאי מעשה ידיך במזונותיך וקבלה עליה משמת אינה משועבדת לו מעשה ידיה וא\"ת והרי היא משועבדת ליתומים ואף הם יאמרו לה כן אף הוא לא היה יכול לומר לה אלא א\"כ היא מתרצה:"],[2,"צררי","צרורות כספים נתן בידה למזונות:"],[2,"חיישי' שמא אמר לה צאי מעשה ידיך במזונותיך","וקבלה עליה:"],[3,"איכא בינייהו גדולה","הראויה להתפיסה מעות ולא ספקה מזונות במעשה ידיה שהן שני בצורת או שאינה בעלת מלאכה לצררי איכא למיחש לצאי מעשה ידיך במזונותיך ליכא למיחש דכיון דלא ספקה לא קבלה עליה:"],[3,"איכא בינייהו גדולה","הראויה להתפיסה מעות ולא ספקה מזונות במעשה ידיה שהן שני בצורת או שאינה בעלת מלאכה לצררי איכא למיחש לצאי מעשה ידיך במזונותיך ליכא למיחש דכיון דלא ספקה לא קבלה עליה:"],[4,"אי נמי קטנה","ובעלת מלאכה והשנים כתקנן:"],[4,"וספקה","לרב זביד פוסקין דלא עביד איניש דמתפיס צררי לקטנה לרב פפא אין פוסקין דאיכא למימר צאי מעשה ידיך למזונותיך אמר לה:"],[6,"ואם בא ואמר פסקתי לה מזונות","אתפסתיה צררי:"],[6,"נאמן","ובשבועה ומחזרת מה שנתנו לה ב\"ד:"],[7,"לאחר שמועה","לאחר ששמעו בו שמת בא:"],[9,"ולא דבר אחר","מפרש לקמיה:"],[10,"במשרה אשתו ע\"י שליש","העמיד אפוטרופוס לזונה ועכשיו משך האפוטרופוס את ידו דהשתא ודאי לצררי ליכא למיחש ולא לשמא אמר לה צאי מעשה ידיך למזונותיך:"],[10,"אי הכי","דהשרה אותה ע\"י שליש אפי' בניו ובנותיו נמי דהא גלי דעתיה דניחא ליה שיהו נזונין משלו:"]],[[1,"ששמעו בו שמת","פירש הקונטרס דלמאי ניחוש לה אי לצררי הרי סופה ליטול כתובתה ולישבע שלא עיכבה משלהם כלום והשתא בעי למימר דפליגי בלא שמעו בו שמת היינו בלא שבועה דאי בשבועה אמאי לא תטול וזה אינו דהא בסמוך פריך עד כאן לא פליגי אלא לשבועה אבל למזונות יהבינן לה אלמא לשמואל אפילו בשבועה אין לה ונראה לרבי דהיינו טעמא דבשמעו בו שמת לכולי עלמא פוסקין דאין כאן שום הוכחה לאשה דתפסה צררי ולא שאמר לה צאי מעשה ידיך במזונותיך אבל בלא שמעו שמת אמר שמואל דאין פוסקין דמוכחא מילתא מדאינו חוזר שנסתלק ממנה בשום ענין לרב זביד בצררי ולרב פפא דאמר לה צאי כו' והלכך אפי' בשבועה לא מהימנא. מ\"ר. ולבי מגמגם לפירושו דפריך בסמוך מהא דתניא מי שהלך למדינת הים ואשתו תובעת מזונות בני כהנים גדולים אומרים תשבע כו' ואם בא כו' ומשני בששמעו בו שמת ודוחק לשנויי בא לאחר שמועה ונמצא שהיה שקר מה ששמעו בו שמת והוה מצי לשנויי בלא שמעו בו שמת וכגון דפסקיה מברא או שום אונס שאינו יכול לשוב דמודה שמואל דפוסקין לה מזונות כיון דהשתא ליכא הוכחה ואמר לי רבי דהא מילתא לא שכיח הוא שיארע אונס או יפסיקו הנהר יותר מיום או יומים:"],[1,"בששמעו בו שמת כולי עלמא לא פליגי","נראה לרבי דהאי שמעו בו שמת בשני עדים מדקאמר לקמן ששמעו בו שמת בעד אחד מכלל דעד השתא ס\"ד בשני עדים ובקול נמי ליכא למימר מדפריך לקמן ת\"ש האשה שהלכה היא ובעלה למדינת הים כו' ובאה ואמרה גירשני בעלי מתפרנסת והולכת עד כדי כתובתה ומשני כששמעו בו שמת פירוש שמת קודם אותו הזמן שאמרה שנתגרשה ופריך מ\"ש עד כדי כתובתה אפילו לעולם נמי ואי שמעו בו שמת בקול קאמר מאי קושיא וכי יש להאמין הקול הואיל והיא אמרה שגירשה ולא מת ולא דמיא לההיא דפרק המפקיד (ב\"מ דף לח: ושם) שבוי שנשבה רב אמר אין מורידים קרוב לנכסיו ושמואל אמר מורידין כששמעו בו שמת כולי עלמא לא פליגי דמורידין וההוא שמעו בו שמת היינו בעד אחד דאי בשני עדים מאי חידוש הוא הלא הם יורשים אותו וא\"ת ואעד אחד היאך מורידין והתנן ביבמות בפרק האשה שהלכה (יבמות דף קטז: ושם) גבי האשה שאמרה מת בעלי שאין האחים נכנסים לנחלה על פיה ומדהיא לא מהימנא עד אחד נמי לא מהימן וי\"ל דהתם מיירי לירד ולמכור אבל בהמפקיד מיירי לירד על מנת שלא למכור כדמוכח התם והא דתניא לקמן ב\"ד יורדין לנכסיו וזנין ומפרנסין את אשתו אבל לא בניו ובנותיו ומוקמינן לה בששמעו בו שמת בעד אחד וקאמר בניו ובנותיו דאי בעו מיחת לנכסים בעד אחד לא מצו נחתי מזוני נמי לא יהבינן להו התם נמי למכור אבל בפירות הגדלים בשדה אכלי להו שפיר:"],[2,"חיישינן שמא אמר לה כו'","וקיבלה עליה ופטרתו ופטור הוא בכך אע\"ג דהשתא לא ספקה:"],[4,"קטנה וספקה","וא\"ת הואיל וספקה נימרו לה ב\"ד צאי מעשה ידיך למזונותיך ולמה יורדים לנכסיו למאן דחייש לצררי ואי לא ספקה א\"כ היכי מחלה למ\"ד צאי מעשה ידיך והא אין מחילת קטנה כלום וי\"ל כגון דספקה לדברים גדולים ולא ספקה לדברים קטנים דלדברים קטנים מהני מחילתה אי נמי בפעוטות דמקחן מקח ומתנתן מתנה. מ\"ר:"],[5,"תרגמה שמואל בששמעו בו שמת","תימה א\"כ מאי טעמא דבני כהנים גדולים דמה לי דמת בביתו מה לי ששמעו בו שמת ע\"פ עדים ואין נראה לפרש ששמעו בו ע\"פ עד אחד וי\"ל דאפי' מת בביתו פליגי בני כהנים גדולים והא דנקט למי שהלך למדינת הים רבותא נקט דס\"ד ניחוש כ\"כ לצררי דאפילו בשבועה לית לה. מ\"ר:"],[6,"ואם בא ואמר פסקתי לה מזונות נאמן","פירש רש\"י אף להוציא מידה מה שנתנו לה ב\"ד בשבועה דהכי משמע דאנשבעה קאי והיינו טעם דסתמא דמילתא מתפיס לה צררי הלכך מוציאין מידה בשבועה ונראה לרבי להצריכה שבועה ובשבועה תגבה מה שלוותה ואכלה דאי לאו הכי לא תמצא מי שילוה לה שיראים להפסיד אבל עכשיו שהיא נשבעת אין יראים כלום שסומכין עליה שתשבע. מ\"ר:"],[8,"ואם בא ואמר לה צאי מעשה ידיך במזונותיך רשאי","כלומר אם לוותה ואכלה לא אפרע שאם לא היו מלוים לזו היתה דוחקת עצמה אף ע\"ג דלא ספקה והאי דאמרינן לקמן לוותה ואכלה עמדה ומיאנה ודייקינן טעמא דמיאנה הא לא מיאנה יהבינן לה התם שפסקו לה ב\"ד:"],[10,"מאי פסקא","תימה לרבי אין סתמא דמילתא אשתו דחייב במזונותיה משרה על ידי שליש בניו ובנותיו דלא מיחייב במזונותיהם לא משרה ורבינו שמשון מפרש הסוגיא אי הכי בניו ובנותיו נמי אי אמרת בשלמא דלא איירי מתני' במשרה אשתו ע\"י שליש אלא אשתו ובניו סמוכין על שולחנו ניחא דאשתו מפרנסין הואיל והוא חייב לזונה משום חשש דשמא התפיסה צררי אין ב\"ד נמנעין מלזונה אבל בניו ובנותיו דאינו חייב במזונותיהן אין לירד לנכסיו לפרנסם דבקל יש לחוש שמא התפיסם צררי והניח להם מעות לפרנסם עד שישוב אבל השתא דמוקמת במשרה ע\"י שליש ליכא למיחש לצררי ומשני במשרה אשתו ע\"י שליש אבל בניו סמוכין על שולחנו ולא השרה ע\"י שליש ולהכי חיישינן לצררי ופריך מאי פסקא דזה אין רגילות דאשתו ישרה ע\"י שליש ובניו יהיו סמוכין על שולחנו:"]]],[["צדקה מ\"ד צדקה אבל תכשיט יהבינן לה דלא ניחא ליה דתינוול","תא שמע היבמה ג' חדשים הראשונים ניזונת משל בעלה","מיכן ואילך אינה ניזונת לא משל בעלה ולא משל יבם עמד בדין וברח ניזונת משל יבם","אמר לך שמואל למאי ניחוש לה להאי אי משום צררי לא מיקרבא דעתיה לגבה אי משום מעשה ידיה לא משתעבדא ליה","תא שמע האשה שהלכה היא ובעלה למדינת הים ובאת ואמרה מת בעלי רצתה ניזונת רצתה גובה כתובתה גירשני בעלי מתפרנסת והולכת עד כדי כתובתה","הכא נמי כששמעו בו שמת ומאי שנא עד כדי כתובתה דאיהי היא דאפסידה אנפשה","תא שמע כיצד אמרו ממאנת אין לה מזונות אי אתה יכול לומר ביושבת תחת בעלה שהרי בעלה חייב במזונות אלא כגון שהלך בעלה למדינת הים לותה ואכלה עמדה ומיאנה טעמא דמיאנה הא לא מיאנה יהבינן לה","אמר לך שמואל הכא למאי ניחוש לה אי משום צררי צררי לקטנה לא מתפיס ואי משום מעשה ידיה קטנה לא ספקה","מאי הוה עלה כי אתא רב דימי אמר מעשה בא לפני רבי בבית שערים ופסק לה מזונות לפני רבי ישמעאל בצפורי ולא פסק לה מזונות תהי בה רבי יוחנן וכי מה ראה רבי ישמעאל שלא פסק לה מזונות הא לא נחלקו בני כהנים גדולים וחנן אלא לענין שבועה אבל מזוני יהבינן לה","א\"ל רב שמן בר אבא כבר תרגמה רבינו שמואל בבבל כששמעו בו שמת א\"ל פתריתו בה כולי האי","כי אתא רבין אמר מעשה בא לפני רבי בבית שערים ולא פסק לה מזונות לפני רבי ישמעאל בציפורי ופסק לה מזונות א\"ר יוחנן מה ראה רבי שלא פסק לה דהא לא נחלקו חנן ובני כהנים גדולים אלא לענין שבועה אבל מזונות יהבינן לה אמר ליה רב שמן בר אבא כבר תרגמה שמואל בבבל כששמעו בו שמת אמר ליה פתריתו בה כולי האי","והלכתא כותיה דרב ופוסקין מזונות לאשת איש והלכתא כותיה דרב הונא אמר רב דאמר רב הונא אמר רב יכולה אשה שתאמר לבעלה איני ניזונת ואיני עושה","והלכתא כותיה דרב זביד בקוניא דאמר רב זביד הני מאני דקוניא חיורי ואוכמי שרו","ירוקי אסירי ולא אמרן אלא דלית בהו קרטופני אבל אית בהו קרטופני אסירי:","\u0001מתני׳\u0002 מי שהלך למדינת הים ועמד אחד ופירנס את אשתו חנן אומר איבד את מעותיו","נחלקו עליו בני כהנים גדולים ואמרו ישבע כמה הוציא ויטול א\"ר דוסא בן הרכינס כדבריהם א\"ר יוחנן בן זכאי יפה אמר חנן הניח מעותיו על קרן הצבי:","\u0001גמ׳\u0002 תנן התם המודר הנאה מחבירו"],[[0,"צדקה","אין ב\"ד פוסקין צדקה לעניים מנכסיו בזמן ששאר בני העיר פוסקין עליהן צדקה:"],[0,"תכשיט","בשמים להתקשט בהן אשתו:"],[1,"שלשה חדשים הראשונים","שאינה יכולה לא להנשא ולא להתייבם ניזונת משל בעלה:"],[2,"עמד בדין","ואמרה לו כנוס או חלוץ:"],[4,"רצתה ניזונת כו'","שהאשה נאמנת לומר מת בעלי ותינשא וכשם שנאמנת לינשא כך נאמנת ליטול כתובתה כדאמרינן במסכת יבמות מספר כתובתה נלמד לכשתנשאי לאחר תטלי מה שכתוב ליכי:"],[4,"מתפרנסת והולכת כו'","כתובה לא גביא שמא לא גירשה ובגירושין לא האמינוה אבל מזוני יהבינן לה ובפרעון כתובה ממה נפשך אם גירשה הרי נטלתן בכתובתה ואם לאו הרי הוא חייב במזונותיה:"],[5,"איהי היא דאפסדה אנפשה","שאמרה גרשני וגרושה אין לה מזונות וכי תימא כיון דשמעה שמת תגבה כתובתה יחד אין הכי נמי והאי דקאמר מתפרנסת והולכת אם אינה רוצה ליטול כתובתה דסבורה שמא לא מת ונוח לה ליטול לשם מזונות שאם יבא בעלה תהא כל כתובתה קיימת ומתפרנסת עד כדי כתובתה ותו לא יהבינן לה:"],[12,"מאני דקוניא","כלי חרס שמחפין עליהם עופרת שקורין פלומבלי\"ר בלע\"ז:"],[12,"חיורי שרו","לפי שהעופרת מחליק את החרס ואינו מניחו לבלוע אבל הירוקים מעורב צריף שקורין אלו\"ם בתוך העופרת והוא עז ומחלחל את החרס ובולע והכי אמרי' במסכת ע\"ז (דף לג:) דמצרפי ובלעי:"],[13,"ירוקי אסירי","לענין חמץ בפסח וגיעולי עובדי כוכבים ויין נסך:"],[13,"קרטופנא","ביקועי קיריויני\"ש בלע\"ז:"],[14,"מתני' חנן אומר איבד את מעותיו","שלא אמרתי לך הלוני ואני אפרע אבל אם הלוה את האשה מעות למזונותיה על מנת שתשלם לו הוא תובעה והיא תובעת הבעל וישלם כדאמר לעיל בממאנת ולוותה ואכלה ועמדה ומיאנה טעמא דמיאנה הא לא מיאנה משלם:"]],[[2,"עמד בדין וברח","בפרק החולץ (יבמות דף מא: ושם) פרש\"י דוקא ברח אבל חלה הוא או חלתה היא לא משמע לפי דבריו דקנס הוא ותימה אם כן מאי קפריך הואיל ומשום קנס מתפרנסת ויש לומר דאי חיישינן כולי האי לצררי כדחייש שמואל לא היה לקונסו כל כך ור\"ח פירש שמצא בירושלמי בריש אף ע\"פ דברח לאו דוקא אלא ה\"ה חלה דניזונת משלו וא\"ת והא אמרינן חלה הוא או היא אינו מעלה לה מזונות לחד לישנא גבי הגיע זמן ולא נשאו יש לומר שאני הכא שהיה לו לכנוס מיד אחר הגעת הזמן אחר שלשה חדשים אבל התם כשהתחיל חליו לפני שהגיע זמן מאי הוה ליה למיעבד ומיהו קשה אי בחלה נמי מעלה לה מזונות אמאי אמרי' בסמוך דלא משעבדא ליה למעשה ידיה וי\"ל דבחלה נמי קנסינן ליה משום דלא כנס מיד אחר שלשה חדשים ואחר שעמד בדין מיד ואם תאמר לפרש\"י דמפרש דוקא ברח אבל חלה לא בפ\"ק (דף ב.) דמיבעיא לן חלה מהו אמאי לא פשיט מהכא דאמרי' דוקא ברח אבל חלה לא וכל שכן הוא דהא הכא דאין לה מזונות אף על פי שפשע קצת שהיה לו לכונסה מיד אחר שעמד בדין אבל התם חלה קודם שהגיע הזמן מאי הוה ליה למיעבד דעל כורחין בהכי מיירי דאי חלה הוא אחר כך פשיטא דאין להפסידה ואיכא למימר דיבמה שאני דלאו אגידא ביה כולי האי כמו ארוסתו ואינה עומדת כל כך לכונסה לא מיחייב מזונות כולי האי ומיהו קשה לפירוש רש\"י דעל כורחין מוקי האי ברח שלא מחמת מרדין אלא מחמתה דאי לאו הכי היינו חלה ואם כן מאי קפריך הכא למ\"ד אין פוסקין מזונות לאשת איש הרי הכא לא שייך התפסת צררי הואיל ומחמתה ברח:"],[12,"הני מאני דקוניא","פי' בקונטרס פלומי\"ר בלע\"ז כלי חרס שמתיכין לתוכו עופרת ואין נראה לר\"ת דבזבחים פרק איזהו מקומן (זבחים דף נד) גבי עשיית מזבח תניא מביא סיד וקוניא וממחה ושופך הוה ליה למימר אבר שהוא לשון ברייתא ועוד אמר רבי מדמסיק עלייהו בפ\"ב דמסכת ע\"ז (דף לג: ושם) ובפרק כל שעה (פסחים דף ל: ושם) משום דמצרפי פירוש שמעורב בהם צריף שקורין אלו\"ם בלע\"ז על כן נראה כדפירש הערוך דקוניא היינו כלי חרס המחופה בהתכת זכוכית ולהכי מסיק עליה דמצרפי משום דזכוכית תחילת ברייתו מן החול ובאותו חול מעורב צריף ולהכי בלעי וכן מורה רבינו תם באותם פלומי\"ר שלנו שמתיכין לתוכן עופרת אינן נאסרין ביי\"נ יותר משאר כלי חרס ועוד מדקדק ר\"ת אף אם היה כולו מעופרת לא היה נאסר ועכשיו שאין בו אלא עופרת מעט יאסר אבל בהתכת זכוכית ניחא דאפי' כולן של זכוכית אינו נאסר לפי שנתבשל היטב ואינו נבלע אבל קוניא לא נתבשל כל כך ובלע טפי:"],[13,"ירוקי","פירש בקונטרס לענין חמץ בפסח וגיעולי עובדי כוכבים ויין נסך ולא משום דאיצטריך למיפסק הלכה כרב זביד לענין חמץ בפסח דהא מרימר דפליג עליה ושרי ירוקי דוקא לענין יין נסך אבל לענין חמץ בפסח מודה דאסירי אפי' חיורי כדאיתא בהדיא בפ' אין מעמידין (ע\"ז דף לג:) ומפרש התם טעמא דתשמישו בחמין:"],[14,"חנן אומר איבד מעותיו","ליכא לאקשויי מהא דקיימא לן (לעיל כתובות פ.) היורד לתוך שדה של חבירו ונטעה שלא ברשות דשמין לו כאריס ולבונה חורבתו של חבירו דנותן לו מה שההנהו (ב\"מ קא. ע\"ש) דהתם השבח בעין הוא ודין הוא שיטול אבל הכא לא השביח לו שום שבח נכסים אלא שהצילו מגביית בעל חובו ולא מידי יהיב ליה והוה כמבריח ארי מנכסי חבירו דאע\"ג דמהנה אותו לא מתחייב מידי כדמסיק בנדרים באין בין המודר (דף לג:) וא\"ת הא אמרי' בהשוכר את הפועלים (ב\"מ דף צג:) שומר חנם שהיה לו לקדם ברועים ובמקלות ולא קידם חייב ומפרש שומר חנם בחנם שומר שכר בשכר ומסיק דחוזר ונוטל מבעל הבית משמע דשומר חנם נמי אם קדם ברועים ובמקלות בשכר חוזר ונוטל מבעל הבית ואמאי אברוחי אריא בעלמא הוא וכן הא דתנן בפ' אלו מציאות (ב\"מ דף לא: ושם) היה בטל מסלע לא יאמר לו תן לי סלע אלא נותן לו שכרו כפועל בטל של אותה מלאכה דבטיל מינה ופירש בקונטרס שאם היה עוסק במלאכה חמורה ונוטל שכר מרובה כמה היה פוחת משכרו ויעסוק במלאכה קלה כמו השבת אבידה וכך יתנו לו ואמאי אברוחי אריא בעלמא הוא ולפי מה שפירש רבינו תם דדוקא במפרנס את אשתו קאמר חנן לפי שיכולה לצמצם ולהתפרנס בדוחק אבל שאר פורע לו חובו לא כמו שאמר לקמן לא קשיא מידי ואומר רבי כי מן הדין היה ודאי פטור כדמשמע הכא אלא תקנת חכמים התם שישלמו לו כדי שישיב אבידתו של חבירו וכן בקדם ברועים ובמקלות בשכר דחוזר ונוטל שכר מבעל הבית כדי שיעסוק להבריח את הארי ואפי' עולה השכר כדי דמיהן נפקא מינה לכושרא דחיותא אבל פורע חובו ועמד אחר ופרנס את אשתו למה לנו לעשות תקנה על זה ומהאי טעמא נמי הא דאמר בהנזקין (גיטין נח:) הבא מחמת חוב ומחמת אנפרות אין בו משום סיקריקון פירוש אם שהתה בידו י\"ב חדש אין נותן רביע לבעלים ויחזיק בקרקעות אלא מחזיר לו הקרקע נראה לרבי דלא בחנם מחזיר אלא משלם לו מה שהוציא להוציאה מיד העובד כוכבים ורבינו גרשון פי' בתשובותיו כמו כן דאע\"ג דלא הוי אלא כמבריח ארי בעלמא יש לו לשלם מידי דהוה אקדם ברועים ובמקלות בשכר וגבי משיב אבידה דאל\"כ אין לך אדם מציל של חבירו מיד העובדי כוכבים ולא כפי' הקונטרס שפירש בגיטין שמחזיר לו בחנם וא\"ת והא דתנן בהגוזל בתרא (ב\"ק דף קטו:) שטף נהר חמורו וחמור חבירו שלו יפה מנה ושל חבירו מאתים והניח זה את שלו והציל את של חבירו אין לו אלא שכרו ואמאי דמי חמורו היה לו לשלם והיה רבי רוצה לומר דמשום הכי אין לו אלא שכרו דמיירי כגון שבעל החמור בפניו וכי עשו חכמים תקנה ה\"מ שלא בפניו אבל בפניו לא וקשה א\"כ אפי' שכרו לא יהא לו דהא תנן בפ' הכונס (בבא קמא דף נח. ושם) נפלה לגינה ונהנית משלמת מה שנהנית ומפרש רב בגמרא אפי' נחבטה דס\"ד מבריח ארי מנכסי חבירו ומה שנהנית נמי לא משלם קמ\"ל ופריך אימא ה\"נ ומשני מבריח ארי מנכסי חבירו מדעתו והאי שלא מדעתו א\"נ מבריח ארי לית ליה פסידא האי אית ליה פסידא ומשמע לישנא קמא מדעתו אע\"ג דאית ליה פסידא פטור ועל כורחין לא אפשר לפרש כן מההיא דאלו מציאות (ב\"מ דף לא:) ודהשוכר את הפועלים (שם דף צג:) אלא הכי פירושו מבריח ארי מדעתו היכא דלית ליה פסידא האי שלא מדעתו לאו משום דאי לא הוי פסידא יהא חייב דפשיטא אם נחבטה ולא נתקלקלו הפירות למה יהא חייב אלא כלומר האי שלא מדעתו שעל כרחו הוא מבריח ארי ואם דוחקים את האדם על כרחו להבריח את הארי ממצרו של חבירו אע\"ג דלית ליה פסידא חייב לשלם לו שכר טורחו והשתא בההיא דהגוזל בתרא אם נפרש דדמי חמורו אינו חייב לשלם לפי שהוא בפניו אלמא חשבינן כאילו לית ליה פסידא א\"כ לא יהא לו אפי' שכרו כיון דמדעתו הוא ולית ליה פסידא על כן נראה לרבי דהיינו טעמא דאינו משלם דמי חמורו שלא תקנו חכמים שיהא חייב לשלם אלא מה שהוא מהנה אותו ואינו מהנה אותו אלא כדי שכרו שהרי גם הוא היה מוצא להציל בכדי שכרו דעל כרחך מיירי שיכול להציל שלא יזכה אותו מן ההפקר:"]]],[["שוקל לו את שקלו ופורע את חובו ומחזיר לו אבידתו ובמקום שנוטלין שכר תפול הנאה להקדש","בשלמא שוקל לו את שקלו מצוה קעביד דתנן תורמין על האבוד ועל הגבוי ועל העתיד לגבות","ומחזיר לו אבידתו נמי מצוה קעביד אלא פורע לו את חובו הא קמשתרשי ליה","אמר רב אושעיא הא מני חנן היא דאמר איבד את מעותיו","ורבא אמר אפי' תימא רבנן הכא במאי עסקינן שלוה על מנת שלא לפרוע","בשלמא רבא לא אמר כרב אושעיא דמוקים לה כרבנן אלא רב אושעיא מ\"ט לא אמר כרבא אמר לך רב אושעיא נהי דהנאה לית ליה"],[[0,"גמ' שוקל לו את שקלו","שוקל בשבילו שקל שהוא חייב לכל שנה לקרבנות צבור:"],[0,"ופורע לו את חובו","אם חייב ממון לנושה מותר לזה שיפרענו בשבילו:"],[0,"ומחזיר לו אבידתו","אם ראה חמורו תועה מותר להשיבו:"],[0,"במקום שנוטלין שכר","על טורח השבתה:"],[0,"תפול","הניית השכר להקדש שהרי שניהן מודרין בהנאה זה מזה:"],[1,"מצוה קא עביד","כלומר מצוה בעלמא קא עביד ואינו מהנהו לזה שאם לא שקל עליו לא הפסיד כלום שיש לו חלק בקרבנות:"],[1,"דתנן תורמין","את הלשכה בשלש קופות:"],[1,"על האבוד","אף על מי ששלח שקלו ואבד:"],[1,"ועל הגבוי","שעדיין לא הגיע כאן:"],[1,"ועל העתיד לגבות","ואפילו לא נגבה לאחר מכאן יש לו חלק בתרומה ובקרבנות אלא שחיסר מצוה נמצא שכר המצוה על הנותן:"],[2,"משתרשי ליה","מרויחו:"],[3,"חנן היא דאמר איבד מעותיו","זה שפרנס את אשת חבירו ונתכוון לשם הלואה שישלם לו בעלה איבד מעותיו ואין יכול לומר לו את חובך פרעתי שלם לי והוא הדין נמי לכל חוב שעליו ועמד חברו ופרעו וזה לא אמר לו הלויני אינו חייב לו כלום וכיון דאילו פרעיה לשם הלואה לאו הלואה היא כי פרעיה נמי לשם מחילה לאו מידי יהיב ליה:"],[4,"אפילו תימא רבנן","דאמרי חייב אע\"פ שלא אמר לו הלויני וגבי שאר חוב נמי חייב לשלם וכי מחיל אסור במודר הנאה והכא דקתני פורע לו את חובו בשלוה זה תחלה הלואה מן המלוה על מנת שלא לפרוע עד שירצה לא יוכל הנושה ללחצו הלכך לאו מידי יהיב ליה:"]],[[0,"ובמקום שנוטלין שכר תפול ההנאה להקדש","בפ' אין בין המודר (נדרים דף לג:) מוקי לה בין בשנכסי שניהם אסורין זה על זה משום הכי תפול הנאה להקדש דלא מצי מחזיר ליטול שכר ולא מצי בעל אבידה לעכבו בין בשנכסי מחזיר דוקא אסורין על בעל אבידה ולא נכסי בעל אבידה אסורין על המחזיר ואם אין המחזיר רוצה לקבל שכר בעל אבידה אינו יכול לעכבו ותפול הנאה להקדש:"],[1,"ועל העתיד לגבות","פי' בקונטרס אפי' לא נגבה לבסוף וקשה לרבי חדא דהוה ליה למיתני ועל העתיד לגבות ותו לא דהוי אבוד וגבוי בכלל ועוד דתנן (בשקלים דף ג:) ומייתי לה בהזהב (ב\"מ דף נח. ושם) בני העיר ששקלו שקליהם ונגנבו מהשלוחין או שאבדו השלוחין אם עד שלא נתרמה התרומה נשבעים השלוחים לבני העיר ובני העיר שוקלים ומביאים אחרים תחתיהם אבל משנתרמה אחריות אהקדש ואם כפירוש הקונטרס דאפי' לא נגבו לבסוף תורמין עליהם אמאי בני העיר שוקלים ומביאין אחרים תחתיהם אי משום מצוה אפי' משנתרמה נמי ועוד פירש רש\"י על האבוד מי ששלח שקלו ואבד ועל הגבוי שעדיין לא הגיע וקשה דא\"כ זו ואין צ\"ל זו קתני אלא נראה לפרש על האבוד שבא ליד גבאי ואבד ועל הגבוי ביד השליח ונאבד מיד השליח לאחר שנתרמה התרומה דאי נאבד קודם שנתרמה התרומה חייבין בעלים באחריות ועל העתיד לגבות שיבא לידי גבוי לבסוף והא דאמר הכא שוקל לו את שקלו באבוד וגבוי דלא מיחייבי בעלים באחריות:"],[3,"הא מני חנן היא דאמר איבד מעותיו","הואיל וכן שאינו יכול עתה לתובעו ממנו אע\"פ שמ\"מ מהנהו שאין צריך לשלם חובו משום הכי לא מיתסר שאינו אלא גרמא בעלמא שעל ידי שפורע זה לבעל חובו מיפטר ודמי להא דתנן באין בין המודר (נדרים דף מג.) המודר הנאה מחבירו ואין לו מה יאכל ילך אצל חנוני הרגיל אצלו כו' ויתן לשום מתנה אע\"ג דעל ידו משתרשי ליה מזוני שרי הואיל ולא עביד אלא גרמא בעלמא ולא דמי לעושה לו מלאכה דאסור אע\"ג דלא מצי תבע ליה מיניה דהתם מדידיה לדידיה קא מיתהני אבל הכא גרמא בעלמא הוא ורבינו תם מפרש דאיירי דוקא במזונות אשתו ומשום הכי פטור דאין הדבר ברור שהיה מתחייב זה הבעל מזונות שמא היה יכול להפטר שהאשה עצמה היתה מצמצמת אם לא היתה מוצאה מי שממציא לה מעות אע\"ג דבפסקו לה ב\"ד מיירי דאי לאו הכי לא הוי מיחייב לכ\"ע שאף לאשה עצמה לא היה מיחייב בלא פסק ב\"ד מכ\"מ היתה מצמצמת דלא ליקרו לה רעבתנותא אבל גבי שטר חוב אפי' חנן מודה דלא איבד מעותיו דהנאה גמורה היא הואיל ולא היה יכול להפטר בשום ענין והכי פי' הא מני חנן היא כלומר האי פורע מיירי באותו חוב דאיירי בה חנן דהיינו במזון האשה דוקא וחנן היא וכן פירש רבינו חננאל ושני רב אושעיא הא דתנן ופורע את חובו מזונות אשתו הן ואליבא דחנן וריב\"א הביא ראיה מירושלמי דה\"ה בשאר חובין דגרסינן התם בפירקין אבא בר ממל בעי הפורע שטר חוב של חבירו שלא מדעתו בפלוגתא דחנן ובני כהנים גדולים א\"ר אסי טעמא דבני כהנים גדולים תמן לא עלה בדעתו שתמות אשתו ברעב ברם הכא מפייסנא ליה ומחיל לי הגע בעצמך דהוה גביה משכון מפייס הוינא ליה ויהיב לי משכוני עד כאן בבעל חוב שאינו דוחק ואפי' בבעל חוב דוחק נשמענה מן הדא שוקל לו את שקלו לא שקיל אין ממשכנא הדא אמרת אפי' בעל חוב דוחק אלמא מחלוקת בבעל חוב כמו למזונות ואומר רבינו תם על כרחך פליג גמרא ירושלמית אגמרא שלנו דמוקים ההוא טעמא דשוקל את שקלו כבני כהנים גדולים אע\"ג דממשכנין על השקלים ורב אושעיא מוקי לה כחנן ופליג לגמרי דלית ליה הך סברא ומפרש דלא פליגי אלא במזון האשה כדפרשינן ועוד דעל כרחין סוגיא דירושלמי לא אתיא כסוגיא דהכא דלדברי רבא צריך לפרש דשוקל לו שקלו היינו באבוד וגבוי דאי לאו הכי שוקל לו שקלו אמאי הא קא משתרשי ליה ובירושלמי משמע דלא מיירי באבוד דפשיט מיניה בעל חוב דוחק:"]]],[["כיסופא מי לית ליה התם נמי אית ליה הנאה בההיא הנאה דמיכסיף מיניה:","\u0001מתני׳\u0002 אדמון אומר שבעה מי שמת והניח בנים ובנות בזמן שהנכסים מרובין הבנים יורשים והבנות נזונות ובנכסים מועטים הבנות יזונו והבנים יחזרו על הפתחים אדמון אומר בשביל שאני זכר הפסדתי אמר רבן גמליאל רואה אני את דברי אדמון:","\u0001גמ׳\u0002 מאי קאמר אמר אביי ה\"ק בשביל שאני זכר וראוי לעסוק בתורה הפסדתי","אמר ליה רבא מאן דעסיק בתורה הוא דירית מאן דלא עסיק בתורה לא ירית אלא אמר רבא הכי קאמר בשביל שאני זכר וראוי לירש בנכסים מרובין הפסדתי בנכסים מועטין:","\u0001מתני׳\u0002 הטוען את חבירו כדי שמן והודה בקנקנים אדמון אומר הואיל והודה במקצת הטענה ישבע וחכ\"א אין הודאת מקצת ממין הטענה אמר רבן גמליאל רואה אני את דברי אדמון:","\u0001גמ׳\u0002 שמע מינה לרבנן טענו חטין ושעורין והודה בשעורין פטור","לימא תהוי תיובתא דרב נחמן אמר שמואל דא\"ר נחמן אמר שמואל טענו חטין ושעורים והודה לו באחד מהן חייב","אמר רב יהודה אמר רב בטוענו מדה אי הכי מ\"ט דאדמון","אלא אמר רבא דכולי עלמא היכא דאמר ליה מלא עשרה כדי שמן יש לי בבורך שמן קטעין ליה קנקנים לא קטעין ליה עשרה כדי שמן מלאים יש לי אצלך שמן וקנקנים קטעין ליה","כי פליגי היכא דאמר ליה עשרה כדי שמן יש לי אצלך אדמון אומר יש בלשון הזה לשון קנקנים ורבנן סברי אין בלשון הזה לשון קנקנים","אלא טעמא דאין בלשון הזה לשון קנקנים הא יש בלשון הזה לשון קנקנים חייב לימא תיהוי תיובתא דר' חייא בר אבא דא\"ר חייא בר אבא טענו חטין ושעורים והודה לו באחד מהם פטור","אמר רב שימי בר אשי נעשה כמי שטענו רימון בקליפתו מתקיף לה רבינא רימון בלא קליפתו לא מינטר שמן מינטר בלא קנקנים","אלא הכא במאי עסקינן דאמר ליה עשרה כדי שמן יש לי אצלך ואמר ליה אידך שמן לא היו דברים מעולם קנקנים נמי חמשה אית לך וחמשה לית לך","אדמון אומר יש בלשון הזה לשון קנקנים ומגו דקמשתבע אקנקנים משתבע נמי אשמן על ידי גלגול ורבנן סברי אין בלשון הזה לשון קנקנים מה שטענו לא הודה לו ומה שהודה לו לא טענו:","\u0001מתני׳\u0002 הפוסק מעות לחתנו ופשט לו את הרגל"],[[0,"כיסופא מי לית ליה","דקא מיכסיף מן המלוה תמיד הלכך אי רבנן היא דאמרי דלענין חוב לוה ע\"מ לפרוע ופרע חברו בשבילו חייב לשלם וגבי מודר הנאה מחילה היא ואסיר כי לוה ע\"מ שלא לפרוע נמי הנאה היא ומחילה מחיל גביה ואסיר אלא חנן היא ובין בחוב העומד לפרוע בין בעומד שלא לפרוע לית ליה גביה מידי ולאו מחילה היא ואע\"ג דסלקיה מפרעון ומכיסופא:"],[1,"מתני' נכסים מועטין","מפרש בבבא בתרא שאין בהן פרנסת שנים עשר חדש לזכרים ולנקבות:"],[1,"הבנות יזונו והבנים ישאלו על הפתחים","תקנת חכמים היא:"],[1,"הפסדתי","בתמיה:"],[2,"גמ' מאי קאמר","אם בשביל שאני זכר הפסדתי משמע אם בשביל שאני זכר וכחי יפה הפסדתי ומהו יפוי כחו:"],[4,"מתני' והודה לו בקנקנים","רקים בלא שמן:"],[7,"גמ' בטוענו מדה","לא תבע ממנו קנקנים אלא שמן הפקדתי אצלך ומאי כדי שמן דקתני מתני' מדה מלא עשרה כדי שמן דהוי ליה טענו חטים והודה לו בשעורים:"],[8,"בבורך","בור שלפני הבד:"],[8,"קנקנים לא טעין ליה","וכי הודה לו בקנקנים לאו הודאה היא:"],[8,"כדים מלאים","כדים ושמן משמע:"],[9,"עשרה כדי שמן","ולא אמר מלאים:"],[9,"יש בלשון הזה לשון קנקנים","כיון דלא אמר ליה מלא עשרה אין זה טוענו מדה אלא עשרה כדים מלאים והוה ליה טענו חטים ושעורים:"],[10,"אלא טעמא כו'","לשון קושיא הוא לאותובי למאן דאמר פטור דדוקיא דמתני' כרב נחמן מדקתני הטוען את חבירו כדי שמן ולא קתני כדים מלאים שמן שמעינן מינה דמשום דאין בלשון הזה לשון קנקנים פטרי רבנן הא אם תבעו שניהם חייב:"],[11,"נעשה כמי שתבעו רימון בקליפתו","לא דמו כדים ושמן לחטים ושעורים דכולי חדא מילתא הוא וממין הטענה הוא:"],[11,"שמן","בלא קנקנים מנטר בבור:"],[12,"אלא הכא במאי עסקי' כו'","אלא לא תימא כמו שטענו רימון אלא ר' חייא מוקי למתניתין כגון שהודה במקצת קנקנים ומקצתם כפר דבקנקנים גופייהו איכא כפירה והודאה ואי יש בלשון התביעה לשון קנקנים מיחייב עלייהו שבועה ושבועה דשמן דקא מחייב אדמון משום גלגול היא דקסבר יש בלשון התביעה לשון קנקנים:"],[14,"מתני' ופשט לו את הרגל","לשון בזיון הוא ואמר נואש שאינו חש לדבריו טול טיט שעל גבי רגלי ואני שמעתי תלה אותי על עץ ואין לי מה ליתן:"]],[[1,"אדמון אומר וכי בשביל שאני זכר הפסדתי","אע\"ג דאמר לקמן כל מקום שאמר רבן גמליאל רואה אני את דברי אדמון הלכה כמותו ומההוא פיסקא פריך הש\"ס לקמן אלמא דהכי הוי עיקר מ\"מ אומר ר\"ת דלית הלכתא כוותיה בהא דהא סוגיא דגמרא דלא כוותיה לעיל בפרק נערה (כתובות דף מג. ושם) אמר רבי אסי א\"ר יוחנן עשו אלמנה אצל הבת כבת אצל אחין בנכסים מועטים אלמא סתם דבריו כרבנן ועוד דלעיל פ' הנושא (כתובות דף קג.) אמרי' יתומים שקדמו ומכרו בנכסים מועטים מה שמכרו מכרו וסתמא דהש\"ס כרבנן בריש מי שמת (ב\"ב דף קלט:) ואומר ר\"ת דהיינו טעמא דאדמון לאו לאיפלוגי אמלתא דחכמים אתא אלא מתמה בעלמא הוא ור\"ג נמי דאמר בההיא רואה אני את דברי אדמון לאו משום פסק דין אלא משום שיש ודאי לתמוה:"],[3,"אמר רבא דעסיק באורייתא ירית","בתמיה מקשים מאי קמתמה רבא אין ה\"נ כדאמר לעיל בפרק נערה (כתובות דף מט. ושם) מצוה לזון את הבנות וק\"ו לבנים דעוסקין בתורה ואר\"ת דלא דמי דלעיל גבי מצוה יש מצוה לזון הבנים יותר מן הבנות אבל הכא שמת האב וירושתן קא שקלי מן התורה קא מתמה רבא אמילתיה דאדמון דקא בעי למימר דכשיעסוק בתורה יטול ירושה ואם לא יעסוק לא יטלנה וי\"מ דהכא מיירי בבנים גדולים ולהכי פריך מאן דעסיק כו' אבל לעיל מצוה לזון את הבנים בבנים קטנים מיירי משום דכולם עומדים לעסוק בתורה קאמר ק\"ו לבנים ולהכי לא פריך מאן דעסיק דכולם הן עומדים לעסוק בתורה:"],[5,"שמע מינה מדרבנן טענו חטין ושעורים וכו'","תימה מאי פריך לר\"נ מדרבנן והלא איכא אדמון דקאי כוותיה וכי תימא משום דרבים נינהו אדרבה אית לן למימר כאדמון דהלכתא כוותיה ואומר רבי דמכולהו פריך דמשמע דאדמון מודה בחטין ושעורים דמיפטר מדלא נקט חטין ושעורים אלא נקט כדי (יין ושמן) דכרימון בקליפתו דמי כדבעי למימר לקמן רב שימי בר אשי שאינו יודע הגמרא אמאי הוי נקיט האי לישנא דכדי שמן ומיהו לאחר שידע דאיכא לאפלוגינהו ביש בלשון הזה לשון קנקנים פריך איפכא נימא תיהוי תיובתא דרב חייא בר אבא ואפילו הכי משני נעשה כמי שטענו רימון בקליפתו:"],[7,"אי הכי מ\"ט דאדמון","תימה מאי קא קשיא ליה הא אשכחן ר\"ג דאית ליה האי סברא דמיחייב בטען לו חטין והודה לו בשעורים כדתנן בפ' שבועת הדיינין (שבועות לח: ושם) ונראה דה\"ק אי הכי מ\"ט דאדמון אליבא דר\"נ דהא בעינן למימר דלהוי אדמון כרב נחמן דכוותיה קי\"ל ור\"נ דוקא בטענו חטין ושעורים והודה לו באחד מהן מיחייב אבל טענו חטין והודה לו בשעורין פטור:"],[14,"הפוסק מעות לחתנו","מוקי לה בירושלמי כשפסק במעמדה אבל לא פסק במעמדה אפי' רבנן מודו והשתא אתי שפיר הא דאמר בגמרא כופין למאן אילימא כופין לאב איפכא איבעי ליה למימר הואיל ופסק במעמדה הוי תנאי גדולה תנאי ותנאי קטנה לאו כלום ומסיק כופין לבעל ליתן את הגט לקטנה משום דלאו תנאה אבל גדולה הואיל ובמעמדה התנה הרי הוא כמו שהיא עצמה התנית:"]]],[["תשב עד שתלבין ראשה אדמון אומר יכולה היא שתאמר אילו אני פסקתי לעצמי אשב עד שתלבין ראשי עכשיו שאבא פסק מה אני יכולה לעשות או כנוס או פטור אמר רבן גמליאל רואה אני את דברי אדמון:","\u0001גמ׳\u0002 מתני' דלא כי האי תנא דתניא אמר רבי יוסי ברבי יהודה לא נחלקו אדמון וחכמים על הפוסק מעות לחתנו ופשט לו את הרגל שיכולה היא שתאמר אבא פסק עלי מה אני יכולה לעשות","על מה נחלקו על שפסקה היא על עצמה שחכמים אומרים תשב עד שתלבין ראשה אדמון אומר יכולה היא שתאמר כסבורה אני שאבא נותן עלי ועכשיו שאין אבא נותן עלי מה אני יכולה לעשות או כנוס או פטור אמר רבן גמליאל רואה אני את דברי אדמון","תנא במה דברים אמורים בגדולה אבל בקטנה כופין כופין למאן אילימא לאב איפכא מיבעי ליה אלא אמר רבא כופין לבעל ליתן גט","אמר ר' יצחק בן אלעזר משמיה דחזקיה כל מקום שאמר רבן גמליאל רואה אני את דברי אדמון הלכה כמותו אמר ליה רבא לרב נחמן אפי' בברייתא א\"ל מי קאמרינן במשנה בכל מקום שאמר רבן גמליאל קאמרינן","אמר ר' זירא אמר רבה בר ירמיה ב' דברים שאמר חנן הלכה כיוצא בו שבעה דברים שאמר אדמון אין הלכה כיוצא בו מאי קאמר","אילימא הכי קאמר שני דברים שאמר חנן הלכה כמותו וכיוצא בו ושבעה דברים שאמר אדמון אין הלכה כמותו ולא כיוצא בו והאמר רבי יצחק בן אלעזר משמיה דחזקיה כל מקום שאמר רבן גמליאל רואה אני את דברי אדמון הלכה כמותו","אלא ה\"ק שני דברים שאמר חנן הלכה כמותו וכיוצא בו שבעה דברים שאמר אדמון אין הלכה כיוצא בו הא כמותו הלכה בכולהו","והאמר רבי יצחק בן אלעזר משמיה דחזקיה כ\"מ שאמר רבן גמליאל רואה אני את דברי אדמון הלכה כמותו אמר אין לא אמר לא","אלא ה\"ק שני דברי' שאמר חנן הלכה כמותו וכיוצא בו שבעה דברים שאמר אדמון יש מהן שהלכה כמותו וכיוצא בו ויש מהן שאין הלכה כמותו אלא כיוצא בו","בכ\"מ שאמר רבן גמליאל רואה אני את דברי אדמון הלכה כמותו אינך לא:","\u0001מתני׳\u0002 העורר על השדה והוא חתום עליה בעד אדמון אומר השני נוח לי והראשון קשה הימנו","וחכמים אומרים איבד את זכותו עשאה סימן לאחר איבד את זכותו:","\u0001גמ׳\u0002 אמר אביי לא שנו אלא עד אבל דיין לא איבד את זכותו דתני ר' חייא אין העדים חותמין על השטר אלא א\"כ קראוהו"],[[3,"גמ' במה דברים אמורים","אברייתא קאי:"],[3,"איפכא מיבעי ליה","אם באת לכוף את האב איפכא מסתברא טפי לפי שהגדולה תנאה תנאי:"],[4,"אפי' בברייתא","כשפסקה היא לעצמה:"],[5,"","הכי גרסינן א\"ר זירא אמר רבה בר ירמיה שני דברים שאמר חנן הלכה כיוצא בו שבעה דברים שאמר אדמון אין הלכה כיוצא בו מאי קאמר כו' - כיוצא בו דחנן רבן יוחנן בן זכאי כיוצא בו דאדמון רבן גמליאל:"],[5,"אין הלכה כיוצא בו","שלא ראה את דבריו אלא בשלשה שהיה לו לראות את דבריו בכולם:"],[11,"מתני' העורר על השדה כו'","ראובן מערער על שדה שביד שמעון ואומר לוי שמכרה לך גזלה ממני:"],[11,"והוא חתום","על שטר המכירה שכתב לוי לשמעון כשמכרה לו:"],[11,"אדמון אומר","יכול הוא שיאמר מה שלא ערערתי בשעה שלקחת מלוי וחתמתי בתוך השטר עד לפי שלוי אדם חזק וקשה להוציאה מידו ונוח לי שתהא בידך שאוציאנה ממך בדין:"],[12,"איבד את זכותו","דהואיל וחתם הודה שאין לו עסק בה:"],[12,"עשאה","המוחזק בה סימן לאחר שלא מכר לראובן זה העורר עליה אלא לאיש אחר היה מוכר שדה מצד זו ומצר לו ארבעת מצרי השדה וכתב לו במצרים מצר פלוני שדה שלי ועשה שדה זו סימן מצר ללוקח ובשמו של מוכר וזה חתם על אותו שטר ולא ערער:"],[12,"איבד את זכותו","אפילו לאדמון דאין לומר כאן השני נוח לי:"],[13,"גמ' אבל דיין","שהובא שטר המכירה בבית דין לקיימו כמשפט קיום שטרות שהעדים באין ומעידין על כתב ידם והדיינין כותבין שטרא דנן נפקא לקדמנא ואסהידו סהדי אחתימות ידייהו ואישרנוהי וקיימנוהי:"],[13,"לא איבד זכותו","שלא ידע מה כתוב בו שיערער עליו:"],[13,"דתני רבי חייא אין העדים חותמין על השטר אלא א\"כ קראוהו","שהרי על דברי השטר הם באים להעיד:"]],[[0,"תשב עד שתלבין ראשה","פי' רשב\"ם הא דאמר רב גידל בריש הנושא (לעיל כתובות דף קב:) עמדו וקדשו קנו הני מילי דקדשו מיד מתוך התנאי או לאחר זמן והזכירו התנאים בשעת קידושין אבל התנו עתה וקדש לאחר זמן ולא הזכירו התנאים לאו דברים הנקנים באמירה הם ובכי האי גוונא הכא תשב עד שתלבין ראשה ולא מצי תבע ליה בדינא והלשון משמע כן ועמדו וקדשו משמע מתוך התנאי וקשה לי מירושלמי אהא דתנן הפוסק מעות לחתנו ומת חתנו אמרו חכמים יכול הוא שיאמר לאחיך הייתי רוצה ליתן ולך אי אפשי ליתן ופריך ולאו דברים הנקנים באמירה הן ומשני כשפסק על מנת לכנוס ומאי קשה אפי' פסק על מנת שלא לכנוס אפ\"ה יכול שיאמר לו לך אי אפשי ליתן דמיירי בשלא עמדו וקדשו מתוך התנאי ומיהו לא קשה כולי האי דאי כשלא עמדו מתוך התנאי היכי קאמר לאחיך הייתי רוצה ליתן מ\"מ אין נראה לרבי פירושו דמכאן אין שום ראיה דהא דקאמר תשב עד שתלבין ראשה כשאין לו לאב כלום ליתן או הבעל אינו רוצה לטרוח ולהביאו לדין אבל אם היה רוצה להביאו בדין הוה ליה ליתן ומיהו הא לא משמע הכי לרבי לפרש כשאין לו כלום ליתן מדבעי למימר כופין לאב ור\"ש בירושלמי מוקי דרב גידל בנשואין ראשונים ומתניתין דהכא בנשואין שניים ואני חפשתי בירושלמי ומצאתי בריש אע\"פ דהך דרב גידל דוקא בנשואין הראשונים ודוקא באב הפוסק ע\"י בתו ולא אשה ע\"י בתה ולא אח על ידי אחותו:"],[4,"ואפילו בברייתא אמר ליה אין כל מקום קאמרינן","תימה היכי מצי למיפסק הלכתא כתרווייהו כברייתא וכמתני' והלא דברים סותרין זה את זה דבמתני' קתני אילו אני פסקתי כו' וברייתא קתני כסבורה אני י\"ל הכי פי' ואפי' בברייתא כלומר למאי דסבירא ליה לתנא דברייתא דבפסקה היא בעצמה פליגי קא אמרת דהלכתא כוותיה וא\"ל כל מקום קאמרינן למר כדאית ליה ולמר כדאית ליה:"],[6,"שני דברים שאמר חנן הלכה כמותו וכיוצא בו","פי' בקונטרס כיוצא בו דחנן רבן יוחנן בן זכאי כיוצא בו דאדמון ר\"ג וקשה לרבי חדא דלישנא לא משמע הכי ועוד מה לו להזכיר בדברי חנן כיוצא בו והא לא מיירי חנן אלא באותן שני דברים דוקא והוה ליה למימר הלכה כחנן ותו לא הלכך נראה לרבי כפר\"ח כיוצא בו בדינים אחרים הדומין לאלו והלכה כמותו ולא כיוצא בו כלומר בדינין הדומין לאלו אין הלכה כמותו ודומה להא דאמר בפרק כל הנשבעין (שבועות דף מח:) דאמר להו רב נחמן הבו דלא לוסיף עלה פי' הכינו עצמכם שלא תוסיפו עליה ללמד ממנו דבר הדומה לו:"],[11,"אדמון אומר השני נוח לי והראשון קשה הימנו","אע\"ג דלית הלכתא כאדמון בהא דהא לא קתני בה רואה אני את דברי אדמון לא תיקשי דמסקינן בחזקת הבתים (ב\"ב דף מג:) עלה דההיא מכר לו שדה אין מעיד לו עליה ומוקי לה בראובן שגזל משמעון ומכרה ללוי ואתא יהודה וקא מערער דלא ליזיל שמעון לאסהודי ללוי משום דניחא ליה דתיקום ארעא ביד לוי דאמר הראשון נוח לי והשני קשה הימנו הכא לא היה לו לחתום ולעשות דבר הנראה הודאה משום ניחותא דשני אבל התם לאו הודאה היא:"],[12,"","אדמון אומר השני נוח לי והראשון קשה הימנו. אע\"ג דלית הלכתא כאדמון בהא דהא לא קתני בה רואה אני את דברי אדמון לא תיקשי דמסקינן בחזקת הבתים (ב\"ב דף מג:) עלה דההיא מכר לו שדה אין מעיד לו עליה ומוקי לה בראובן שגזל משמעון ומכרה ללוי ואתא יהודה וקא מערער דלא ליזיל שמעון לאסהודי ללוי משום דניחא ליה דתיקום ארעא ביד לוי דאמר הראשון נוח לי והשני קשה הימנו הכא לא היה לו לחתום ולעשות דבר הנראה הודאה משום ניחותא דשני אבל התם לאו הודאה היא:"],[12,"עשאה סימן לאחר","מתוך הלשון משמע דאעורר קאי כגון שמכר אחת משדותיו ועשאה סי' בשם המוחזק ובגמ' הכי פי' לא שנו אלא לאחר אבל לעצמו לא איבד כלומר אם מכר מערער אחת משדותיו למוחזק לאו הודאה היא דאי לאו דעבדי הכי לא היה המוחזק קונה שדה ממני ואני הייתי צריך למעות ולא גרסי' מזבין אלא זבין ובירושלמי משמע כרש\"י שהביא בפי' ר\"ח ולא סוף דבר שעשאה העורר סימן לאחר אלא אפילו עשאה אחר לאחר והעורר חתום בעד איבד זכותו:"],[13,"לא שנו אלא עד אבל דיין לא דתני רבי חייא כו'","הקשה ה\"ר יצחק ב\"ר ברוך דהכא משמע דאין הדיינים מעידין על מה שכתוב בשטר אלא על חתימת העדים וקשה מהא דאמר בחזקת הבתים (שם דף נב.) אחד מן האחין שהיה נושא ונותן בתוך הבית והיו אונות ושטרות יוצאות על שמו אמר רב עליו להביא ראיה ומסיק ראיה בקיום השטר אלמא דעל ידי חתימת הדיינים אנו יודעים שהשטרות שלו הם אלמא אכולה מילתא קמסהדי ותירץ רבי דהתם ודאי אית לן למימר דדיינים רמו אנפשייהו לאסהודי לגמרי שהרי היו יודעים שהיה נושא ונותן בתוך הבית וסתמא דמילתא לאו דידיה הוא הלכך אי לאו דידעי דשלו היה לא היו מקיימין אלא בשם היתומים:"]]],[["אבל הדיינין חותמים אע\"פ שלא קראוהו:","עשאה סימן לאחר: אמר אביי לא שנו אלא לאחר אבל לעצמו לא איבד את זכותו","דאמר אי דלא עבדי ליה הכי לא הוה מזבין לה ניהלי מאי אית לך למימר איבעי לי למימסר מודעא חברך חברא אית ליה וחברא דחברך חברא אית ליה","ההוא דעשאה סימן לאחר ערער ושכיב ואוקים אפוטרופא אתא אפוטרופוס לקמיה דאביי א\"ל עשאה סימן לאחר איבד את זכותו","אמר אי הוה אבוהון דיתמי קיים הוה טעין ואמר תלם אחד עשיתי לך א\"ל שפיר קאמרת דאמר ר' יוחנן אם טען ואמר תלם אחד עשיתי לך נאמן זיל הב ליה מיהת תלם אחד","הוה עלה ריכבא דדיקלי אמר ליה אי הוה אבוהון דיתמי קיים הוה טעין ואמר חזרתי ולקחתי ממנו א\"ל שפיר קאמרת דא\"ר יוחנן אם טען ואמר חזרתי ולקחתיו ממנו נאמן אמר אביי האי מאן דמוקים אפוטרופא נוקים כי האי דידע לאפוכי בזכותא דיתמי:","\u0001מתני׳\u0002 מי שהלך למדינת הים ואבדה דרך שדהו אדמון אומר ילך לו בקצרה וחכמים אומרים יקנה לו דרך במאה מנה או יפרח באויר:","\u0001גמ׳\u0002 מ\"ט דרבנן שפיר קאמר אדמון אמר רב יהודה אמר רב כגון שהקיפוה ארבעה בני אדם מארבע רוחותיה אי הכי מאי טעמא דאדמון","אמר רבא בארבעה דאתו מכח ארבעה וארבעה דאתו מכח חד כולי עלמא לא פליגי דמצי מדחי ליה כי פליגי בחד דאתי מכח ארבעה","אדמון סבר מכל מקום דרכא אית לי גבך ורבנן סברי אי שתקת שתקת ואי לא מהדרנא שטרא למרייהו ולא מצית לאשתעויי דינא בהדייהו","ההוא דאמר להו דיקלא לברת אזול יתמי פלוג לנכסי לא יהבו לה דיקלא סבר רב יוסף למימר היינו מתניתין","א\"ל אביי מי דמי התם כל חד וחד מצי מדחי ליה הכא דיקלא גבייהו הוא מאי תקנתייהו ליתבו לה דיקלא וליהדרו וליפלגו מרישא:","ההוא דאמר להו דיקלא לברת שכיב ושביק תרי פלגי דדיקלא","יתיב רב אשי וקא קשיא ליה מי קרו אינשי לתרי פלגי דיקלי דיקלא או לא אמר ליה רב מרדכי לרב אשי הכי אמר אבימי מהגרוניא משמיה דרבא קרו אינשי לתרי פלגי דיקלי דיקלא:"],[[0,"אבל הדיינים חותמין","בקיום אע\"פ שלא קראוהו שהרי אינן מעידין אלא ששטר זה בא לפנינו והעדים הכירו שהיא חתימתן:"],[1,"לא שנו אלא לאחר","דוקא נקט מתני' סימן לאחר אבל עשאה המוחזק בה סימן לעצמו של ראובן זה העורר עליה שהיה שמעון מוכר שדה שבצדה לראובן זה העורר עליו וכשמצר לו סימני המצרים כתב על שדה זו מיצר פלוני שלי ולא מיחה ראובן:"],[2,"אי לאו דעבדי הכי","אם לא שתקתי:"],[2,"למימסר מודעא","לומר לעדים בסתר הוו יודעין שעל שדה זו שאצל זו שאני לוקח אני מערער ומה ששתקתי למה שכתבה במצריה בשמו שאם אני מוחה לא ימכור לי זאת:"],[2,"חברך חברא אית ליה","ויודיעוהו ושוב לא ימכור לי:"],[4,"תלם אחד","מענית המחרישה על פני כל השדה שמכר הודיתי לו בין שדה זו שאני עורר ובין אותה שמכר ועל אותו תלם כתב מצר פלוני שלי וחתמתי על השטר ולא מחיתי:"],[4,"הב ליה מיהת תלם אחד","לאחר שהביא אפוטרופוס של יתומים ראיה שהיתה של אביהם וגזלה הימנו ולא היה למחזיק זכות בה אלא לפי שעשאה אביהן סימן בשמו של מחזיק א\"ל אביי לאפוטרופוס זיל הב ליה למחזיק מיהת תלם אחד:"],[5,"הוה","על אותו תלם:"],[5,"ריכבא דדקלא","שורת דקלים מורכבין זה על גב זה:"],[5,"חזרתי ולקחתיו הימנו","לאחר שעשיתיו סימן בשמו:"],[5,"נאמן","דהפה שאסר הוא הפה שהתיר דמאחר שיש עדים שהיתה שלו ונגזלה הימנו אין לזה זכות באותו תלם אלא על פיו של זה שעשאה סימן לאחר והרי חזר ואמר לקחתיו:"],[6,"מתני' ואבדה דרך שדהו","שהחזיקו בה בעלי השדות שבמצריו:"],[6,"ילך לו בקצרה","על כרחם יטול לו דרך לשדהו אבל דרך קצרה יברור לו שלא ירבה ליטול:"],[7,"גמ' שפיר קאמר אדמון","דקס\"ד כשארבעת השדות שסביבותיו של אדם אחד הן דממה נפשך אורחיה גביה הוא:"],[7,"ארבעה בני אדם","דכל חד וחד מדחי ליה דרכך לאו גבאי הוא:"],[8,"וארבעה דאתו מכח חד","שלקחוה מאיש אחד אחר שהלך זה:"],[9,"אי שתקת שתקת","ואוזיל גבך כשתקנה הדרך ממני:"],[10,"ההוא דאמר","בשעת מיתתו:"],[10,"היינו מתני'","דאזלא גבי כל חד וחד ומצי מדחי לה כרבנן:"],[11,"כל חד וחד מצי מדחי ליה","של מזרח אומר לו בצפון דרך שלך ואין לך אצלי כלום וכן כל אחד ואחד:"],[11,"הכא דקלא גבייהו הוא","שהרי כל הנכסים היו יחד בשעת צוואה ועל כולם הטיל הדקל ולא פירש איזהו:"],[12,"ושבק תרי פלגי דדקלא","שהיה לו בשותפות ושאר דקלים הרבה היו לו והיתומים היו נותנין לה אותן שני חצאין שיש טורח בהן יותר:"],[13,"קרו אינשי כו'","ועל כרחה ידה על התחתונה שהנכסים בחזקת היתומים וזו אינה באה עליהם אלא מכח הצוואה:"]],[[4,"אמר ליה שפיר קאמרת דאמר ר' יוחנן כו'","אביי לא היה זכור בדברי ר' יוחנן עד שהזכירו האפוטרופוס דאילו היה זכור היה הוא עצמו טוען בשביל היתומים כדקיימא לן טוענין ליורשין:"],[5,"אם טען ואמר חזרתי ולקחתי ממנו מהימן","תימה אמאי נאמן הואיל והודה דלאו שלו הוא היאך יכול לטעון שוב חזרתי ולקחתי וכ\"ת דנאמן במיגו דאי בעי לא הוה חתם ולא הוה מודה לאו מילתא היא דבכי האי גוונא לא אמרי' מיגו כדפירשנו לעיל בפרק הכותב (כתובות דף פה. ושם) גבי ההיא אתתא דאפקידו גבה מלוגא דשטרי כמו שפירשנו שם ולפי מה שפירשנו במי שהיה נשוי (לעיל כתובות צב: ושם ד\"ה דינא) דלא טענינן ליתמי מזוייף הוא אומר רבי דמצינן לפרש הכא דמיירי כגון שאין כתב ידי העדים יוצא ממקום אחר ולכך נאמן לומר חזרתי ולקחתי ממנו מיגו דאי בעי אמר מזוייף הוא ולא נחתם ולא עשיתי סימן מהימן הוא לומר עשיתי סימן וחזרתי ולקחתי ממנו והא דלא קאמר אי הוה אבוהון הוה טעין מזוייף הוא דלא טענינן ליתמי מזוייף הוא מיהו חזרתי ולקחתי ממנו טענינן להו כיון דקסבר דאבוהון הוה מהימן בהך טענה מיגו דאי בעי אמר מזוייף הוא כדפרישית במי שהיה נשוי:"],[8,"","אמר ליה שפיר קאמרת דאמר ר' יוחנן כו'. אביי לא היה זכור בדברי ר' יוחנן עד שהזכירו האפוטרופוס דאילו היה זכור היה הוא עצמו טוען בשביל היתומים כדקיימא לן טוענין ליורשין:"],[9,"ורבנן סברי אי צייתת צייתת ואי לא מהדרנא שטרא למרייהו","אבל הא לא מצי למימר בחד דאתי מכח חד מזבנינא ליה לארבעה דלא מצית לאשתעויי דינא בהדייהו שלא יכול להפקיע דינו על ידי מכירתו הואיל וקודם שבא לידו לא היה ראוי לומר כן אבל בחד דאתי מכח ד' יכול לומר מהדרנא שטרא למרייהו וזכות הבא על ידו הוא יכול להפקיעו ולהעמידו בזכותו שהיה לו קודם שבאו לו אלו השדות לידו והא דקאמר בפ\"ק דב\"ק (דף ח.) מכר לאחד או לג' בני אדם כאחד פירוש עידית ובינונית וזיבורית כולן נכנסו תחת הבעלים ומוקי לה התם בשלקח עידית באחרונ' ופריך וליתו כולהו וליגבו מעידית משום דאמר להו אי שקליתו כדינייכו שקליתו ואי לא מהדרנא שטרא דזיבורית למריה ופריך נזקין נמי נימא הכי אלמא התם אמרי' הך טעמא לכולי עלמא לא קשה מידי דהתם לית ליה פסידא לגמרי דהא גבי מזיבורית ולהכי מודה התם דמצי אמר מהדרנא שטרא למריה אבל הכא דאיכא פסידא לגמרי סבירא ליה דלא אמרי' מהדרנא שטרא למרייהו והא דפריך אי הכי נזקין נמי נימא הכי הוא הדין דאבעל חוב מצי פריך אמאי גובה מן הבינונית אלא רבותא קפריך דאפי' נזקין דדינו מן התורה בעידית לימא הכי ורש\"י פי' לשם דווקא מנזקין קפריך אבל מבעל חוב ניחא ליה דגובה מן הבינונית דאי א\"ל מהדרנא שטרא דזיבורית למריה מצי א\"ל לכי תהדר אבל נזקין ניתיב בינונית ולא מצי אמר ליה לכי תהדר וכ\"ת כתובת אשה נמי אמאי גובה מן הזיבורית תימא ליה לכי תהדר הא לאו מילתא היא דבהך טענה ליכא לאפקועי יותר ממה שגובה אם היו כולן ברשות הבעלים הראשונים ולפי זה שפיר הוצרך לפרש כאן אי צייתת צייתת ואוזיל לגבך דהשתא מרויח במה שאינו מחזירו לו ולא משמע כלל הלשון כך ועוד דקתני במתני' יקח לו דרך במאה מנה משמע כמו שירצה מוכר:"]]],[["\u0001מתני׳\u0002 המוציא שטר חוב על חברו והלה הוציא שמכר לו את השדה אדמון אומר יכול הוא שיאמר אילו הייתי חייב לך היה לך להפרע את שלך כשמכרת לי את השדה וחכ\"א זה היה פקח שמכר לו את הקרקע מפני שהוא יכול למשכנו:","\u0001גמ׳\u0002 מ\"ט דרבנן שפיר קאמר אדמון באתרא דיהבי זוזי והדר כתבי שטרא כ\"ע לא פליגי דמצי א\"ל היה לך לפרוע את שלך כשמכרת לי את השדה","כי פליגי באתרא דכתבי שטרא והדר יהבי זוזי אדמון סבר איבעי ליה למימסר מודעא ורבנן סברי חברך חברא אית ליה וחברא דחברך חברא אית ליה:","\u0001מתני׳\u0002 שנים שהוציאו שטר חוב זה על זה אדמון אומר אילו הייתי חייב לך כיצד אתה לוה ממני וחכ\"א זה גובה שטר חובו וזה גובה שטר חובו:","\u0001גמ׳\u0002 אתמר שנים שהוציאו שטר חוב זה על זה רב נחמן אמר זה גובה וזה גובה רב ששת אמר הפוכי מטרתא למה לי אלא זה עומד בשלו וזה עומד בשלו","דכולי עלמא עידית ועידית בינונית ובינונית זיבורית וזיבורית ודאי הפוכי מטרתא הוא","כי פליגי דאית ליה לחד בינונית ולחד זיבורית רב נחמן סבר זה גובה וזה גובה קסבר בשלו הן שמין","אתי בעל זיבורית וגבי ליה לבינונית דהוה גביה עידית ואתא ההוא ושקיל זיבורית","ורב ששת אמר הפוכי מטרתא למה לי קסבר בשל כל אדם הן שמין סוף סוף כי אתי ההוא בינונית דנפשיה קשקיל","ולרב נחמן מאי חזית דאתי בעל זיבורית ברישא ליתי בעל בינונית ברישא וליגבי זיבורית וליהדר וליגבי ניהליה","לא צריכא דקדים תבעיה סוף סוף כי אתו למגבי בהדי הדדי קאתו","אלא לא צריכא דאית ליה לחד עידית ובינונית ואית ליה לחד זיבורית מר סבר בשלו הן שמין ומר סבר בשל כל אדם הן שמין","תנן וחכ\"א זה גובה וזה גובה תרגמה רב נחמן אליבא דרב ששת כגון שלוה זה לעשר וזה לחמש","ה\"ד אילימא ראשון לעשר ושני לחמש בהא לימא אדמון אילו הייתי חייב לך כיצד אתה לוה ממני הא לא מטא זמניה אלא ראשון לחמש ושני לעשר","ה\"ד אי דמטא זמניה מ\"ט דרבנן ואי דלא מטא זמניה הא לא מטא זמניה ומ\"ט דאדמון","לא צריכא דאתא בההוא יומא דמשלם חמש מר סבר עביד איניש דיזיף ליומיה ומ\"ס לא עביד איניש דיזיף ליומיה","רמי בר חמא אמר הכא ביתמי עסקינן דיתמי מיגבא גבי אגבויי לא מגבינן מינייהו והא זה גובה וזה גובה קתני זה גובה וזה ראוי לגבות ואין לו","אמר רבא שתי תשובות בדבר חדא דזה גובה וזה גובה קתני ועוד לגבינהו ארעא ליתמי וליהדר וליגבינהו מינייהו כדרב נחמן דאמר ר\"נ אמר רבה בר אבוה יתומים שגבו קרקע בחובת אביהן בעל חוב חוזר וגובה אותן מהן קשיא","ולוקמה דאית להו ליתמי זיבורית ואית ליה לדידיה עידית ובינונית דאזלי יתמי גבו בינונית ומגבו ליה זיבורית דאי נמי בשל כל אדם הן שמין הא אין נפרעין מנכסי יתומים אלא מזיבורית","הני מילי היכא דלא תפס אבל היכא דתפס תפס:","\u0001מתני׳\u0002 שלש ארצות לנשואין יהודה ועבר הירדן והגליל אין מוציאין מעיר לעיר ומכרך לכרך אבל באותה הארץ מוציאין מעיר לעיר ומכרך לכרך"],[[0,"מתני' והלה הוציא שמכר לו שדה","הלוה הוציא עליו שטר מכירה מאוחרת לשטר ההלואה ואומר שטרך מזוייף או פרוע שאם הייתי חייב לך לא היית מוכר לי את השדה שהיה לך לגבות את חובך:"],[0,"זה היה פקח שמכר לו את השדה","לפי שהיה זה מבריח מטלטליו ולא היה לו מהיכן ימשכננו על חובו ועכשיו יטול את הקרקע:"],[1,"גמ' באתרא שהלוקח יהיב זוזי והדר כתבי שטר מכירה כולי עלמא לא פליגי","שהיה למוכר לעכב בחובו המעות שקיבל ולא יכתוב לו השטר וכיון שכתבו הוכיח שאין לו עליו חוב:"],[2,"למימסר מודעא","ואיני מוכר לו אלא שאוכל למשכנו:"],[2,"חברא אית ליה","ויודיעהו ולא יקח עוד השדה:"],[3,"מתני' שנים שהוציאו שטר חוב זה על זה","ראובן על שמעון ושמעון על ראובן שטר שהוציא ראובן מוקדם ושל שמעון מאוחר:"],[3,"אדמון אומר","יכול שמעון לומר לראובן:"],[3,"אילו חייב הייתי לך","כדברי שטרך כיצד אתה לוה ממני אחרי כן היה לך לתבוע את חובך ממני:"],[3,"זה גובה וזה גובה","אפילו החוב שוה אין אומרים יעכב זה מלוה של חברו בשביל מלוה שהלוהו אלא ב\"ד יורדין לנכסי כל אחד ומגבין לשכנגדו את חובו:"],[4,"גמ' הפוכי מטרתא למה לי","הנושא שני מרצופין של עור ומשאן שוה מה יתרון לו להפוך של ימין לשמאל ושל שמאל לימין:"],[6,"בשלו הן שמין","מה שאמרו חכמים בעל חוב בבינונית בקרקעות הלוה שמין שאם יש ללוה שדה שהיא בינונית לכל אדם ואצלו היא עידית ששאר שדותיו גרועות הימנה אין ב\"ח גובה הימנה:"],[8,"ורב ששת סבר בשל כל אדם הן שמין","וסוף סוף כי הדר אתי האי למיגבי בינונית שהיתה שלו שקיל:"],[9,"ולרב נחמן","נהי נמי דבשלו הן שמין מאי חזית כו':"],[10,"סוף סוף כי אתו למיגבי בהדי הדדי אתו","שהרי שניהן הוציאו שטרותיהן בבית דין:"],[11,"מר סבר בשלו הן שמין","ולאו הפוכי מטרתא הוא דממה נפשך איכא רווחא לבעל זיבורית דאי חבריה קדים ברישא וגבי איכא גביה עידית ובינונית וזיבורית ומגבי להאיך בינונית ואי איהו קדים וגבי בינונית הויא גביה עידית ומגבי לחבריה זיבורית:"],[11,"ומר סבר בשל עולם הן שמין","וכיון דבהדדי אתו למיגבי יהבי בית דין בינונית לבעל זיבורית ברישא והדר גבי לה מיניה הלכך הפוכי מטרתא הוא:"],[12,"תנן זה גובה וזה גובה","נהי נמי דאית להו לרבנן ששניהם השטרות כשרים יעמוד זה בשלו וזה בשלו אלמא ש\"מ בשלו הן שמין ולאו הפוכי הוא:"],[12,"כגון שלוה זה לעשר","שלא יוכל הנושה לתובעו עד עשר שנים דאיכא רווחא דהמתנה:"],[13,"אילימא ראשון לעשר","ושני בא אצלו לסוף שנה ולוה לחמש:"],[13,"בהא לימא אדמון כו' הא לא מטא זמניה","ונוח היה לו לזה שהלוהו. ויתבענו לסוף חמש ועדיין יהא חובו מעוכב בידו עד השלמת עשר משיהא פורע לו בחובו:"],[13,"בהא לימא אדמון כו' הא לא מטא זמניה","ונוח היה לו לזה שהלוהו ויתבענו לסוף חמש ועדיין יהא חובו מעוכב בידו עד השלמת עשר משיהא פורע לו בחובו:"],[14,"אי דמטא זמניה","אם שלמו חמשת השנים כשבא המלוה ללוות מן הלוה:"],[14,"מ\"ט דרבנן","דמכשרי שטרו של מלוה ראשון הרי הגיע זמנו והיה לו לתובעו ולא ללוות דעבד לוה לאיש מלוה:"],[15,"לא צריכא דאתא","לגביה ולוה הימנו ביומא דמשלם חמש:"],[16,"ביתמי עסקינן","שמת אחד מהן והיתומים באים ותובעים ואין להם קרקע שיהא שכנגדם גובה שטרו מהן דלא משעבדי מטלטלי דיתמי לבעל חוב:"],[18,"","ה\"ג ולוקמה דאית להו ליתמי זיבורית ואית ליה לדידיה עידית ובינונית דאי נמי בשל כל אדם הן שמין אין נפרעים כו':"],[20,"מתני' ג' ארצות לנשואין","שלש ארצות הן בארץ ישראל חלוקות לענין נשואי אשה שאם נשא אשה באחת מהן אינו יכול לכופה לילך אחריו מארץ אל ארץ:"],[20,"אין מוציאין","מזו לזו לא מעיר לעיר ולא מכרך לכרך. כרך גדול מעיר והוא מקום שווקים ומכל סביביו באים שם לסחורה וכל דבר מצוי בו:"]],[[2,"ורבנן חברך חברא אית ליה","והא דמסקינן לעיל אליבא דכולי עלמא דלא איבעי ליה למימסר מודעא גבי לעצמו לא איבד זכותו דאמרינן חברך חברא אית ליה יש לומר דלא דמי דמה שעשאה סימן לא הוה כל כך הודאה כמו הכא שהוציא שמכר לו את השדה הילכך לא איבעי ליה למימסר מודעא אבל בהך הודאה פליגי דדמיא טפי להודאה ולפרש\"י אתי שפיר דלעיל ודאי לא הוה ליה למערער למימסר מודעא דדלמא שמע המוכר לו שדה מהא וימנע למוכרה ויהיה לו הפסד שלא ימצא שדות לקנות אבל הכא גבי מכירת שדה אינו כל כך הפסד דהרבה לוקחים ימצא דאמרי אינשי זבין קנית זבינת אפסדת:"],[10,"סוף סוף כי אתו למיגבי בהדי הדדי קאתו","אע\"ג דנזקקין לתובע תחילה היכא דאית ליה פסידא אין נזקקין כדמוכח התם (ב\"ק דף מו: ושם) טעמא כגון דזילי נכסיה:"],[20,"שלש ארצות לנשואין","תוספתא בד\"א בזמן שהיה מיהודה ואירס ביהודה או בן גליל שאירס בגליל אבל בן יהודה שאירס בגליל או בן גליל שאירס ביהודה כופין אותה לצאת שעל מנת כן נשאה:"]]],[["אבל לא מעיר לכרך ולא מכרך לעיר","מוציאין מנוה הרעה לנוה היפה אבל לא מנוה היפה לנוה הרעה רשב\"ג אומר אף לא מנוה רעה לנוה יפה מפני שהנוה היפה בודק:","\u0001גמ׳\u0002 בשלמא מכרך לעיר דבכרך שכיחי כל מילי בעיר לא שכיחי כל מילי אלא מעיר לכרך מ\"ט","מסייע ליה לרבי יוסי בר חנינא דא\"ר יוסי בר חנינא מנין שישיבת כרכים קשה שנאמר (נחמיה יא, ב) ויברכו העם לכל האנשים המתנדבים לשבת בירושלים:","רשב\"ג אומר כו': מאי בודק כדשמואל דאמר שמואל שינוי וסת תחלת חולי מעים כתוב בספר בן סירא (משלי טו, טו) כל ימי עני רעים והאיכא שבתות וימים טובים כדשמואל דאמר שמואל שינוי וסת תחלת חולי מעים","בן סירא אומר אף לילות בשפל גגים גגו ובמרום הרים כרמו ממטר גגים לגגו ומעפר כרמו לכרמים:","\u0001מתני׳\u0002 הכל מעלין לארץ ישראל ואין הכל מוציאין הכל מעלין לירושלים ואין הכל מוציאין אחד האנשים ואחד הנשים","נשא אשה בא\"י וגרשה בארץ ישראל נותן לה ממעות ארץ ישראל נשא אשה בא\"י וגרשה בקפוטקיא נותן לה ממעות ארץ ישראל נשא אשה בקפוטקיא וגרשה בארץ ישראל נותן לה ממעות ארץ ישראל רבן שמעון בן גמליאל אומר נותן לה ממעות קפוטקיא נשא אשה בקפוטקיא וגרשה בקפוטקיא נותן לה ממעות קפוטקיא:","\u0001גמ׳\u0002 הכל מעלין לאתויי מאי לאתויי עבדים","ולמאן דתני עבדים בהדיא לאתויי מאי לאתויי מנוה היפה לנוה הרעה","ואין הכל מוציאין לאתויי מאי לאתויי עבד שברח מחוצה לארץ לארץ דאמרינן ליה זבניה הכא וזיל משום ישיבת ארץ ישראל","הכל מעלין לירושלים לאתויי מאי לאתויי מנוה היפה לנוה הרעה","ואין הכל מוציאין לאתויי מאי לאתויי אפי' מנוה הרעה לנוה היפה ואיידי דתנא רישא אין מוציאין תנא סיפא נמי אין מוציאין:","ת\"ר הוא אומר לעלות והיא אומרת שלא לעלות כופין אותה לעלות ואם לאו תצא בלא כתובה היא אומרת לעלות והוא אומר שלא לעלות כופין אותו לעלות ואם לאו יוציא ויתן כתובה","היא אומרת לצאת והוא אומר שלא לצאת כופין אותה שלא לצאת ואם לאו תצא בלא כתובה הוא אומר לצאת והיא אומרת שלא לצאת כופין אותו שלא לצאת ואם לאו יוציא ויתן כתובה:","נשא אשה כו': הא גופא קשיא","קתני נשא אשה בארץ ישראל וגרשה בקפוטקיא נותן לה ממעות ארץ ישראל אלמא בתר שיעבודא אזלינן אימא סיפא נשא אשה בקפוטקיא וגרשה בארץ ישראל נותן לה ממעות ארץ ישראל אלמא בתר גוביינא אזלינן","אמר רבה מקולי כתובה שנו כאן קסבר כתובה דרבנן:","רבן שמעון בן גמליאל אומר נותן לה ממעות קפוטקיא: קסבר כתובה דאורייתא","תנו רבנן המוציא שטר חוב על חבירו כתוב בו בבל מגבהו ממעות בבל כתוב בו ארץ ישראל מגבהו ממעות ארץ ישראל כתוב בו סתם הוציאו בבבל מגבהו ממעות בבל הוציאו בארץ ישראל מגבהו ממעות ארץ ישראל כתוב בו כסף סתם מה שירצה לוה מגבהו מה שאין כן בכתובה","אהייא אמר רב משרשיא ארישא לאפוקי מדרשב\"ג דאמר כתובה דאורייתא:","כתוב בו כסף סתם מה שירצה לוה מגבהו ואימא נסכא א\"ר אלעזר דכתיב ביה מטבע ואימא פריטי אמר רב פפא פריטי דכספא לא עבדי אינשי","ת\"ר לעולם ידור אדם בא\"י אפי' בעיר שרובה עובדי כוכבים ואל ידור בחו\"ל ואפילו בעיר שרובה ישראל שכל הדר בארץ ישראל דומה כמי שיש לו אלוה וכל הדר בחוצה לארץ דומה כמי שאין לו אלוה שנא' (ויקרא כה, לח) לתת לכם את ארץ כנען להיות לכם לאלהים","וכל שאינו דר בארץ אין לו אלוה אלא לומר לך כל הדר בחו\"ל כאילו עובד עבודת כוכבים וכן בדוד הוא אומר (שמואל א כו, יט) כי גרשוני היום מהסתפח בנחלת ה' לאמר לך עבוד אלהים אחרים וכי מי אמר לו לדוד לך עבוד אלהים אחרים אלא לומר לך כל הדר בחו\"ל כאילו עובד עבודת כוכבים","ר' זירא הוה קמשתמיט מיניה דרב יהודה דבעא למיסק לארץ ישראל דאמר רב יהודה כל העולה מבבל לארץ ישראל עובר בעשה שנאמר"],[[0,"אבל לא מעיר לכרך","בגמ' מפרש טעמא:"],[1,"שהנוה היפה בודק","את הגוף למי שבא מנוה רע ומתוך כך חלאים באים עליו:"],[3,"גמ' ישיבת כרכין קשה","שהכל מתיישבין שם ודוחקין ומקרבים הבתים זו לזו ואין שם אויר אבל בעיר יש גנות ופרדסים סמוכים לבתים ואוירן יפה:"],[4,"שנוי וסת","אפילו לטובה:"],[5,"במרום הרים כרמו","שאין בידו ממון לקנות במקום טוב וקונה בראש ההר וכל זבלים שהוא מוציא לו נופל וזב לכרמים שתחתיו:"],[6,"מתני' הכל מעלין","את כל בני ביתו אדם כופה לעלות ולישב עמו בירושלים:"],[6,"אחד האנשים ואחד הנשים","אף האשה כופה את בעלה לעלות ולדור שם ואם לאו יוציא ויתן כתובה כדקתני בברייתא בגמ' בהדיא:"],[7,"מעות קפוטקיא","גדולות ושוקלות יותר משל א\"י:"],[8,"גמ' לאתויי עבדים","היה לו עבד עברי ילך העבד אחריו על כרחו:"],[12,"ואיידי דתנא כו'","דאילו משום מנוה הרע לנוה היפה לא איצטריך כיון דאשמעינן דמעלין מנוה היפה לנוה הרע כל שכן דאין מוציאין אפילו מן הרע ליפה:"],[13,"לעלות","מחוצה לארץ לארץ וכן משאר גבולין לירושלים:"],[14,"לצאת","מירושלים לגבולין או מארץ לחוצה לארץ:"],[17,"מקולי כתובה שנו כאן","כאן הקלו בכתובה וזו אחת מקולי כתובה:"],[18,"קסבר כתובה דאורייתא","הילכך בתר שיעבוד אזלינן כדין כל שטרי חוב:"],[19,"כתוב בו כסף סתם","מאה כסף ולא פירש אם סלעין אם דינרין אם פונדיונין:"],[19,"מה שירצה לוה מגבהו","ואפילו איסרין:"],[21,"ואימא נסכא","חתיכות כסף היה לכך לא פירש:"],[21,"ואימא פריטי","ותאמר שיתן לו נחשת או כסף שוה מאה פרוטות:"],[23,"וכי מי אמר לו לדוד כן","אלא מפני שהיה צריך לברוח ולצאת מארץ ישראל אל מלך מואב ואל אכיש:"],[24,"דבעי ר' זירא למיסק","ורב יהודה מוחה בידו להכי הוה משתמיט מיניה:"]],[[10,"ואין הכל מוציאין לאתויי מאי","ואם תאמר אמאי לא משני לאתויי עבד שברח לירושלים כדרבינן לעיל ואין הכל מוציאין דרישא ויש לומר דבירושלים ליכא למימר הכי דאין אנו רוצים שיהיו עבדים בירושלים יותר מדאי אלא מיוחסים. ר\"ת:"],[10,"הכי גרסי' בכל הספרים דאמרינן ליה זבניה הכא וזיל משום ישוב ארץ ישראל","מפרש ה\"ר יוסף בן ה\"ר יום טוב אע\"ג דגרסינן בהשולח (גיטין דף מה. ישם) ההוא עבדא דברח לא\"י אתא מריה אבתריה אתא לקמיה דרבי אמי אמר ליה ניכתוב לך שטרא אדמיה ואי לא מפקענא לך מדרבי אחי בר יאשיה דדריש אל תסגיר עבד אל אדוניו בעבד שברח מחוצה לארץ לארץ ישראל והכא לא מפקענא ליה מיניה אלא אמרי' ליה זיל זבניה התם מיירי כשלא היה מוצא בארץ ישראל למי ימכור לכך קאמר נכתוב לך שטרא אדמיה דאל\"כ כל העבדים יפקיעו עצמן מידי אדוניהם שיברחו לארץ ור\"ת פירש דהאי זבניה דהכא לאו מכירה ממש לאחרים אלא לעצמו והיינו נכתוב שטרא אדמיה:"],[13,"הוא אומר לעלות כו'","אינו נוהג בזמן הזה דאיכא סכנת דרכים והיה אומר רבינו חיים דעכשיו אינו מצוה לדור בא\"י כי יש כמה מצות התלויות בארץ וכמה עונשין דאין אנו יכולין ליזהר בהם ולעמוד עליהם:"],[14,"היא אומרת לצאת כופין אותה","תימה מאי איריא בא\"י אפי' בשאר ארצות נמי היאך תוכל לדוחקו לצאת ממקומו וי\"ל דהכא אפי' מנוה הרע לנוה היפה:"],[21,"ואימא נסכא","מהכא משמע דנסכא עדיפא ממעות ודינרין של כסף דאי פחותה מאי קושיא דאין ה\"נ דהא קאמר מה שירצה מגבהו אלא ודאי עדיפא ואפילו הכי פריך ואימא נסכא כיון שכתוב בו כסף סתמא לא משמע שהוא חייב לו מטבע ואמאי מגבהו מה שירצה דמשמע שיתן לו ממטבע הפחות:"]]],[["(ירמיהו כז, כב) בבלה יובאו ושמה יהיו עד יום פקדי אותם נאם ה' ורבי זירא ההוא בכלי שרת כתיב","ורב יהודה כתיב קרא אחרינא (שיר השירים ב, ז) השבעתי אתכם בנות ירושלים בצבאות או באילות השדה וגו'","ורבי זירא ההוא שלא יעלו ישראל בחומה ורב יהודה השבעתי אחרינא כתיב","ורבי זירא ההוא מיבעי ליה לכדרבי יוסי ברבי חנינא דאמר ג' שבועות הללו למה אחת שלא יעלו ישראל בחומה ואחת שהשביע הקדוש ברוך הוא את ישראל שלא ימרדו באומות העולם ואחת שהשביע הקדוש ברוך הוא את העובדי כוכבים שלא ישתעבדו בהן בישראל יותר מדאי","ורב יהודה (שיר השירים ב, ז) אם תעירו ואם תעוררו כתיב","ורבי זירא מיבעי ליה לכדרבי לוי דאמר שש שבועות הללו למה תלתא הני דאמרן אינך שלא יגלו את הקץ ושלא ירחקו את הקץ ושלא יגלו הסוד לעובדי כוכבים","(שיר השירים ב, ז) בצבאות או באילות השדה אמר רבי אלעזר אמר להם הקב\"ה לישראל אם אתם מקיימין את השבועה מוטב ואם לאו אני מתיר את בשרכם כצבאות וכאילות השדה","אמר רבי אלעזר כל הדר בארץ ישראל שרוי בלא עון שנאמר (ישעיהו לג, כד) ובל יאמר שכן חליתי העם היושב בה נשוא עון א\"ל רבא לרב אשי אנן בסובלי חלאים מתנינן לה","אמר רב ענן כל הקבור בארץ ישראל כאילו קבור תחת המזבח כתיב הכא (שמות כ, כד) מזבח אדמה תעשה לי וכתיב התם (דברים לב, מג) וכפר אדמתו עמו","עולא הוה רגיל דהוה סליק לארץ ישראל נח נפשיה בחוץ לארץ אתו אמרו ליה לרבי אלעזר אמר אנת עולא (עמוס ז, יז) על אדמה טמאה תמות אמרו לו ארונו בא אמר להם אינו דומה קולטתו מחיים לקולטתו לאחר מיתה","ההוא גברא דנפלה ליה יבמה בי חוזאה אתא לקמיה דר' חנינא א\"ל מהו למיחת וליבמה","א\"ל אחיו נשא כותית ומת ברוך המקום שהרגו והוא ירד אחריו","אמר רב יהודה אמר שמואל כשם שאסור לצאת מארץ ישראל לבבל כך אסור לצאת מבבל לשאר ארצות רבה ורב יוסף דאמרי תרוייהו אפילו מפומבדיתא לבי כובי ההוא דנפק מפומבדיתא לבי כובי שמתיה רב יוסף ההוא דנפק מפומבדיתא לאסתוניא שכיב אמר אביי אי בעי האי צורבא מרבנן הוה חיי","רבה ורב יוסף דאמרי תרוייהו כשרין שבבבל א\"י קולטתן כשרין שבשאר ארצות בבל קולטתן למאי אילימא ליוחסין והאמר מר כל הארצות עיסה לארץ ישראל וארץ ישראל עיסה לבבל אלא לענין קבורה","אמר רב יהודה כל הדר בבבל כאילו דר בארץ ישראל שנאמר (זכריה ב, יא) הוי ציון המלטי יושבת בת בבל אמר אביי נקטינן בבל לא חזיא חבלי דמשיח תרגמה אהוצל דבנימין וקרו ליה קרנא דשיזבתא","א\"ר אלעזר מתים שבחוץ לארץ אינם חיים שנאמר (יחזקאל כו, כ) ונתתי צבי בארץ חיים ארץ שצביוני בה מתיה חיים שאין צביוני בה אין מתיה חיים","מתיב ר' אבא בר ממל (ישעיהו כו, יט) יחיו מתיך נבלתי יקומון מאי לאו יחיו מתיך מתים שבא\"י נבלתי יקומון מתים שבחוץ לארץ ומאי ונתתי צבי בארץ חיים אנבוכד נצר הוא דכתיב דאמר רחמנא מייתינא עלייהו מלכא דקליל כי טביא","א\"ל רבי מקרא אחר אני דורש (ישעיהו מב, ה) נותן נשמה לעם עליה ורוח להולכים בה ואלא הכתיב נבלתי יקומון ההוא בנפלים הוא דכתיב","ורבי אבא בר ממל האי נותן נשמה לעם עליה מאי עביד ליה מיבעי ליה לכדרבי אבהו דאמר ר' אבהו אפילו שפחה כנענית שבא\"י מובטח לה שהיא בת העולם הבא כתיב הכא לעם עליה וכתיב התם (בראשית כב, ה) שבו לכם פה עם החמור עם הדומה לחמור","ורוח להולכים בה א\"ר ירמיה בר אבא א\"ר יוחנן כל המהלך ארבע אמות בארץ ישראל מובטח לו שהוא בן העולם הבא","ולר' אלעזר צדיקים שבחוץ לארץ אינם חיים אמר רבי אילעא ע\"י גלגול מתקיף לה ר' אבא סלא רבא גלגול לצדיקים צער הוא אמר אביי מחילות נעשות להם בקרקע","(בראשית מז, ל) ונשאתני ממצרים וקברתני בקבורתם אמר קרנא דברים בגו יודע היה יעקב אבינו שצדיק גמור היה ואם מתים שבחוצה לארץ חיים למה הטריח את בניו שמא לא יזכה למחילות","כיוצא בדבר אתה אומר (בראשית נ, כה) וישבע יוסף את בני ישראל וגו' א\"ר חנינא דברים בגו יודע היה יוסף בעצמו שצדיק גמור היה ואם מתים שבחוצה לארץ חיים למה הטריח את אחיו ארבע מאות פרסה שמא לא יזכה למחילות","שלחו ליה אחוהי לרבה יודע היה יעקב שצדיק גמור היה וכו' אילפא מוסיף בה דברים מעשה באחד שהיה מצטער על אשה אחת וביקש לירד כיון ששמע כזאת גלגל בעצמו עד יום מותו","אף על פי שחכם גדול אתה אינו דומה לומד מעצמו ללומד מרבו וא\"ת אין לך רב יש לך רב ומנו רבי יוחנן","ואם אין אתה עולה הזהר בשלשה דברים אל תרבה בישיבה שישיבה קשה לתחתוניות ואל תרבה בעמידה שעמידה קשה ללב ואל תרבה בהליכה שהליכה קשה לעינים אלא שליש בישיבה שליש בעמידה שליש בהילוך","כל ישיבה שאין עמה סמיכה עמידה נוחה הימנה עמידה ס\"ד והאמרת עמידה קשה ללב אלא ישיבה"],[[0,"בכלי שרת כתיב","קרא דלעיל מיניה כתיב כי כה אמר ה' אל העמודים ועל הים ועל המכונות וגו':"],[2,"שלא יעלו בחומה","יחד ביד חזקה:"],[4,"אם תעירו ואם תעוררו","שתי שבועות בכל אחת:"],[5,"שלא יגלו את הקץ","נביאים שביניהם:"],[5,"ושלא ירחקו את הקץ","בעונם ל\"א שלא ידחקו גרסינן לשון דוחק שלא ירבו בתחנונים על כך יותר מדאי:"],[5,"ושלא יגלו את הסוד","אמרי לה סוד העבור ואמרי לה סוד טעמי התורה:"],[6,"מתיר את בשרכם","לשון הפקר:"],[7,"ובל יאמר שכן חליתי","כלומר אל יתרעם לומר צר לי כי כולם נשואי עון:"],[9,"אתה על אדמה טמאה תמות","מקרא הוא בנבואת עמוס:"],[9,"ארונו בא","לקוברו בא\"י:"],[12,"כך אסור לצאת מבבל","לפי שיש שם ישיבות המרביצות תורה תמיד:"],[12,"דנפק מפומבדיתא לבי כובי","לגור שם:"],[13,"א\"י קולטתן","כדמפרש:"],[13,"אילימא ליוחסין","שנושאין נשים מא\"י והא בבל מיוחס טפי דאמר מר בפרק עשרה יוחסין (קדושין דף עא.):"],[13,"כל הארצות","הרי הן אצל בבל:"],[13,"כעיסה","המעורבת שאין ניכר בה מה בתוכה כך כל המשפחות ספק:"],[13,"אלא לענין קבורה","של בבל מוליכין ארונותיהם ליקבר בא\"י ושל שאר ארצות הרחוקים מא\"י וקרובים לבבל קוברים בבבל שיש שם זכות תורה:"],[14,"וקרו ליה","לימות המשיח:"],[17,"לעם עליה","על א\"י:"],[17,"ההוא בנפלים כתיב","ולעולם בא\"י:"],[20,"אינן חיים","בתמיה:"],[20,"ע\"י גלגול","מתגלגלים העצמות עד א\"י וחיין שם:"],[20,"מחילות נעשה להם בקרקע","ועומדים על רגליהם והולכים במחילות עד א\"י ושם מבצבצין ויוצאים:"],[21,"דברים בגו","יש כאן דברים מסותרים בדבר זה וצריך לתת להם לב:"],[21,"שצדיק גמור היה","ולא היה צריך לזכות א\"י:"],[23,"שלחו ליה אחוהי לרבה","רבה בר נחמני בפומבדיתא היה והיה לו אחים בא\"י ושלחו אגרת זו כדי שיעלה אצלם:"],[23,"אילפא מוסיף בה דברים","עוד שלחו לו כן:"],[23,"מעשה באחד שהיה מצטער על אשה אחת","שנתן בה עיניו והיא בח\"ל:"],[24,"ואע\"פ שחכם אתה","יפה לך לעלות כאן ללמוד מפי רב שאין דומה הלומד מעצמו כו':"],[24,"וא\"ת אין לך רב","כאן שיוכל ללמדך:"]],[[0,"בבלה יובאו ושמה יהיו","אע\"ג דהאי קרא בגלות ראשון כתיב י\"ל דבגלות שני נמי קפיד קרא:"],[5,"שלא יגלו סוד","העיבור כדאמרינן (שבת דף עה.) כי היא חכמתכם ובינתכם זהו סוד העיבור:"]]],[["שאין בה סמיכה עמידה שיש בה סמיכה נוחה הימנה","וכן אמרו יצחק ושמעון ואושעיא אמרו דבר אחד הלכה כר' יהודה בפרדות דתניא רבי יהודה אומר פרדה שתבעה אין מרביעין עליה לא סוס ולא חמור אלא מינה","אמר רב נחמן בר יצחק יצחק זה רבי יצחק נפחא שמעון זה ר\"ש בן פזי ואמרי לה ר\"ל אושעיא זה רבי אושעיא ברבי","אמר ר' אלעזר עמי הארצות אינן חיים שנאמר (ישעיהו כו, יד) מתים בל יחיו וגו' תניא נמי הכי מתים בל יחיו יכול לכל ת\"ל רפאים בל יקומו במרפה עצמו מדברי תורה הכתוב מדבר","א\"ל ר' יוחנן לא ניחא למרייהו דאמרת להו הכי ההוא במרפה עצמו לעבודת כוכבים הוא דכתיב א\"ל מקרא אחר אני דורש דכתיב (ישעיהו כו, יט) כי טל אורות טליך וארץ רפאים תפיל כל המשתמש באור תורה אור תורה מחייהו וכל שאין משתמש באור תורה אין אור תורה מחייהו","כיון דחזייה דקמצטער א\"ל רבי מצאתי להן תקנה מן התורה (דברים ד, ד) ואתם הדבקים בה' אלהיכם חיים כולכם היום וכי אפשר לדבוקי בשכינה והכתיב (דברים ד, כד) כי ה' אלהיך אש אוכלה","אלא כל המשיא בתו לתלמיד חכם והעושה פרקמטיא לתלמידי חכמים והמהנה תלמידי חכמים מנכסיו מעלה עליו הכתוב כאילו מדבק בשכינה","כיוצא בדבר אתה אומר (דברים ל, כ) לאהבה את ה' אלהיך ולדבקה בו וכי אפשר לאדם לידבק בשכינה אלא כל המשיא בתו לתלמיד חכם והעושה פרקמטיא לתלמידי חכמים והמהנה תלמידי חכמים מנכסיו מעלה עליו הכתוב כאילו מדבק בשכינה","א\"ר חייא בר יוסף עתידין צדיקים שמבצבצין ועולין בירושלים שנאמר (תהלים עב, טז) ויציצו מעיר כעשב הארץ ואין עיר אלא ירושלים שנאמר (מלכים ב יט, לד) וגנותי אל העיר הזאת","וא\"ר חייא בר יוסף עתידים צדיקים שיעמדו במלבושיהן ק\"ו מחטה מה חטה שנקברה ערומה יוצאה בכמה לבושין צדיקים שנקברו בלבושיהן על אחת כמה וכמה","וא\"ר חייא בר יוסף עתידה א\"י שתוציא גלוסקאות וכלי מילת שנאמר (תהלים עב, טז) יהי פסת בר בארץ","ת\"ר יהי פסת בר בארץ בראש הרים אמרו עתידה חטה שתתמר כדקל ועולה בראש הרים ושמא תאמר יש צער לקוצרה תלמוד לומר (תהלים עב, טז) ירעש כלבנון פריו הקב\"ה מביא רוח מבית גנזיו ומנשבה עליה ומשרה את סלתה ואדם יוצא לשדה ומביא מלא פיסת ידו וממנה פרנסתו ופרנסת אנשי ביתו","(דברים לב, יד) עם חלב כליות חטה אמרו עתידה חטה שתהא כשתי כליות של שור הגדול ואל תתמה שהרי שועל קינן בלפת ושקלוהו ומצאו בו ששים ליטרין בליטרא של צפורי","תניא אמר רב יוסף מעשה בשיחין באחד שהניח לו אביו שלשה בדי חרדל ונפשח אחד מהן ונמצאו בו תשעה קבין חרדל ועציו סיככו בו סוכת יוצרין: אמר ר\"ש בן תחליפא קלח של כרוב הניח לנו אבא והיינו עולים ויורדים בו בסולם","(דברים לב, יד) ודם ענב תשתה חמר אמרו לא כעולם הזה העולם הבא העולם הזה יש בו צער לבצור ולדרוך העולם הבא מביא ענוה אחת בקרון או בספינה ומניחה בזוית ביתו ומספק הימנה כפטוס גדול ועציו מסיקין תחת התבשיל ואין לך כל ענבה וענבה שאין בה שלשים גרבי יין שנא' (דברים לב, יד) ודם ענב תשתה חמר אל תקרי חמר אלא חומר","כי אתא רב דימי אמר מאי דכתיב (בראשית מט, יא) אוסרי לגפן עירה אין לך כל גפן וגפן שבא\"י שאין צריך עיר אחת לבצור (בראשית מט, יא) ולשורקה בני אתונו אין לך כל אילן סרק שבא\"י שאינו מוציא משוי שתי אתונות ושמא תאמר אין בו יין ת\"ל (בראשית מט, יא) כבס ביין לבושו ושמא תאמר אינו אדום ת\"ל ודם ענב תשתה חמר","ושמא תאמר אינו מרוה ת\"ל סותה ושמא תאמר אין בו טעם ת\"ל חכלילי עינים מיין כל חיך שטועמו אומר לי לי ושמא תאמר לנערים יפה ולזקנים אינו יפה ת\"ל ולבן שנים מחלב אל תיקרי לבן שינים אלא לבן שנים","פשטיה דקרא במאי כתיב כי אתא רב דימי אמר אמרה כנסת ישראל לפני הקב\"ה רבונו של עולם רמוז בעיניך דבסים מחמרא ואחוי לי שיניך דבסים מחלבא","מסייע ליה לר' יוחנן דאמר ר' יוחנן טוב המלבין שינים לחבירו יותר ממשקהו חלב שנאמר ולבן שנים מחלב אל תקרי לבן שינים אלא לבון שינים","רב חייא בר אדא מקרי דרדקי דר\"ל הוה איפגר תלתא יומי ולא אתא כי אתא א\"ל אמאי איפגרת","א\"ל דלית אחת הניח לי אבא ובצרתי ממנה יום ראשון ג' מאות אשכולות אשכול לגרב יום שני בצרתי ג' מאות אשכולות שתי אשכולות לגרב יום שלישי בצרתי ממנה ג' מאות אשכולות שלש אשכולות לגרב והפקרתי יותר מחציה א\"ל אי לאו דאיפגרת הוה עבדא טפי","רמי בר יחזקאל איקלע לבני ברק חזנהו להנהו עיזי דקאכלן תותי תאיני וקנטיף דובשא מתאיני וחלבא טייף מנייהו ומיערב בהדי הדדי אמר היינו זבת חלב ודבש","א\"ר יעקב בן דוסתאי מלוד לאונו שלשה מילין פעם אחת קדמתי בנשף והלכתי עד קרסולי בדבש של תאינים אמר ר\"ל לדידי חזי לי זבת חלב ודבש של צפורי והוי שיתסר מילין אשיתסר מילין אמר רבה בר בר חנה לדידי חזי לי זבת חלב ודבש של כל ארץ ישראל"],[[0,"שאין בה סמיכה","כמו במטות או בקתדראות יש סמיכה בספסלין וכסאות אין סמיכה:"],[1,"אין מרביעין עליה לא סוס ולא חמור","מספקא ליה אי חוששין לזרע האב אי לא הלכך אפי' היא בת חמורה נקבה אין מרביעין עליה חמור שמא חוששין לזרע האב ונמצא מרביע כלאים ורבנן פליגי ליה ואמרי אין חוששין לזרע האב ואם בת סוסיא היא מרביעין עליה סוס ואם בת חמורה היא מרביעין עליה חמור הכי איתא בפרק אותו ואת בנו:"],[3,"רפאים בל יקומו","מרפה עצמו מדברי תורה:"],[4,"וארץ רפאים תפיל","וארץ לרפאים תפיל:"],[5,"מצאתי להם תקנה","יהנו לתלמידי חכמים מנכסיהם:"],[6,"העושה פרקמטיא","מתעסק בממון ת\"ח כדי להגיע לידם שכר והם פנויין לעסוק בתורה ע\"י אלו וכתיב חיים כולכם היום ע\"י דיבוקן של תלמידי חכמים יזכו לחיות:"],[10,"גלוסקאות וכלי מילת","דרוש פסת בר לשון פיסת היד שהיא רחבה וחטה רחבה לא משכחת אלא פת אפויה וכלי מילת דרוש פסת ל' כתונת פסים:"],[11,"שתתמר","לשון תומר דקל:"],[12,"קינן בלפת","ניקב בו עד שעשה לידתו בתוכו ואעפ\"כ שקלו את המותר ששים ליטרין:"],[13,"נפשח","נבדל אחד מהן מן הקלח:"],[13,"והיינו עולים בסולם","ללקט עליו העליונים:"],[14,"ודם ענב תשתה","מתוך הענבה תשתהו ולא תצטרך לדורכו:"],[14,"חומר","כור והוא שלשים סאין:"],[14,"גרבי","סאה:"],[15,"אין לך כל אילן סרק","שלא יעשה פרי:"],[15,"אין בו יין","אין בו ליחלוח בפרי:"],[16,"סותה","לשון הסתה שהיין מסית את השכור:"],[17,"רמוז לי בעיניך","ותתרגם לשון שחוק ומחוך חוך לי בעינים שלך וטוב לי מיין כשתראני פנים צהובות ושוחקות:"],[17,"ואחוי לי שיניך","אף זו לשון שחוק שהשוחק שיניו נגלין:"],[19,"איפגר","לשון בטול:"],[20,"דלית","כרם המודל על גבי כלונסות טריליא\"ה בלע\"ז:"],[20,"הוה עבדא טפי","שהרי ראית שבכל יום היין מתמעט מן האשכולות וזהו עונש הבטול:"],[22,"קדמתי בנשף","קודם עמוד השחר:"]],[[9,"בלבושיהן","משמע בלבושיהן שנקברו דהיינו תכריכין אבל בירושלמי דהנושא אמר רבי לבניו מעטו בתכריכין שעתידין צדיקים שיעמדו בלבושיהן משמע מעטו בתכריכין שעתידין צדיקים שלא יעמדו בתכריכין אלא בלבושיהן מחיים:"]]],[["והויא כמבי מיכסי עד אקרא דתולבנקי כ\"ב פרסי אורכא ופותיא שיתא פרסי","רבי חלבו ור' עוירא ור' יוסי בר חנינא איקלעו לההוא אתרא אייתו קמייהו אפרסקא דהוה כאילפס כפר הינו ואילפס כפר הינו כמה הוי ה' סאין אכלו שליש והפקירו שליש ונתנו לפני בהמתן שליש","לשנה איקלע ר' אלעזר להתם ואייתו לקמיה נקטו בידיה ואמר (תהלים קז, לד) ארץ פרי למלחה מרעת יושבי בה","רבי יהושע בן לוי איקלע לגבלא חזנהו להנהו קטופי דהוו קיימי כי עיגלי אמר עגלים בין הגפנים אמרו ליה קטופי נינהו אמר ארץ ארץ הכניסי פירותייך למי את מוציאה פירותייך לערביים הללו שעמדו עלינו בחטאתינו","לשנה איקלע ר' חייא להתם חזנהו דהוו קיימי כעיזי אמר עזים בין הגפנים אמרו ליה זיל לא תעביד לן כי חברך:","תנו רבנן בברכותיה של ארץ ישראל בית סאה עושה חמשת ריבוא כורין בישיבתה של צוען בית סאה עושה שבעים כורין דתניא אמר רבי מאיר אני ראיתי בבקעת בית שאן בית סאה עושה שבעים כורין","ואין לך מעולה בכל ארצות יותר מארץ מצרים שנאמר (בראשית יג, י) כגן ה' כארץ מצרים ואין לך מעולה בכל ארץ מצרים יותר מצוען דהוו מרבו בה מלכים דכתיב (ישעיהו ל, ד) כי היו בצוען שריו ואין לך טרשים בכל א\"י יותר מחברון דהוו קברי בה שיכבי","ואפילו הכי חברון מבונה על אחת משבעה בצוען דכתיב (במדבר יג, כב) וחברון שבע שנים נבנתה לפני צוען מצרים מאי נבנתה אילימא נבנתה ממש אפשר אדם בונה בית לבנו קטן קודם שיבנה לבנו גדול שנאמר (בראשית י, ו) ובני חם כוש ומצרים ופוט וכנען","אלא שמבונה על אחת משבעה בצוען והני מילי בטרשים אבל שלא בטרשים חמש מאה","והני מילי שלא בברכותיה אבל בברכותיה כתיב (בראשית כו, יב) ויזרע יצחק בארץ ההיא וגו'","תניא אמר רבי יוסי סאה ביהודה היתה עושה חמש סאין סאה קמח סאה סלת סאה סובין סאה מורסין וסאה קיבוריא א\"ל ההוא צדוקי לר' חנינא יאה משבחיתו בה בארעכון בית סאה אחת הניח לי אבא ממנה משח ממנה חמר ממנה עיבור ממנה קיטניות ממנה רועות מקנתי","א\"ל ההוא בר אמוראה לבר ארעא דישראל האי [תאלתא] דקיימא אגודא דירדנא כמה גדריתו מינה אמר ליה שיתין כורי א\"ל אכתי לא עייליתו בה אחריבתוה אנן מאה ועשרים כורי הוה גזרינן מינה אמר ליה אנא נמי מחד גיסא קאמינא לך","אמר רב חסדא מאי דכתיב (ירמיהו ג, יט) ואתן לך ארץ חמדה נחלת צבי למה ארץ ישראל נמשלה לצבי לומר לך מה צבי זה אין עורו מחזיק בשרו אף ארץ ישראל אינה מחזקת פירותיה דבר אחר מה צבי זה קל מכל החיות אף ארץ ישראל קלה מכל הארצות לבשל את פירותיה","אי מה צבי זה קל ואין בשרו שמן אף ארץ ישראל קלה לבשל ואין פירותיה שמנים תלמוד לומר זבת חלב ודבש שמנים מחלב ומתוקים מדבש","רבי אלעזר כי הוה סליק לארץ ישראל אמר פלטי לי מחדא כי סמכוהו אמר פלטי לי מתרתי כי אותבוהו בסוד העיבור אמר פלטי לי מתלת","שנאמר (יחזקאל יג, ט) והיתה ידי אל הנביאים החוזים שוא וגו' בסוד עמי לא יהיו זה סוד עיבור ובכתב בית ישראל לא יכתבו זה סמיכה ואל אדמת ישראל לא יבואו כמשמעו","רבי זירא כי הוה סליק לא\"י לא אשכח מברא למעבר נקט במצרא וקעבר אמר ליה ההוא צדוקי עמא פזיזא דקדמיתו פומייכו לאודנייכו אכתי בפזיזותייכו קיימיתו אמר ליה דוכתא דמשה ואהרן לא זכו לה אנא מי יימר דזכינא לה:","ר' אבא מנשק כיפי דעכו ר' חנינא מתקן מתקליה ר' אמי ורבי אסי"],[[0,"והוה כמבי מיכסי עד אקרא דתולבנקי","כשתצרף כל המקומות ישתער לכך:"],[2,"נקטו בידיה","מצאן קטנות נאחזות בידו אחת:"],[3,"קטפי","אשכולות כדמתרגמינן (ויקרא כה) לא תבצור לא תקטוף:"],[4,"לשנה","לסוף שנה:"],[5,"בברכותיה","כשהשנה מבורכת:"],[5,"בישיבתה של צוען","כלומר כדמפרש ואזיל ומצוען אתה למד לארץ ישראל כדמפרש ואזיל:"],[5,"אני ראיתי בבקעת בית שאן","שהיא משאר ארצות:"],[5,"בית סאה עושה שבעים כורים","וכיון דבשאר ארצות יש שבעים כורים כל שכן בארץ מצרים שאין לך מעולה בכל הארצות כמצרים שהרי נמשלה לגן ה' ואין במצרים מדינה מעולה כצוען:"],[6,"דמרבו בה מלכי","מצרים שנאמר כי היו בצוען שריו על מלכי ישראל הכתוב מדבר לגנאי שמרדו בהקב\"ה וסמכו על מלכי מצרים ותמיד היו שריהם ושלוחיהם מצויין בצוען שלוחים למלך מצרים מביאין תשורה:"],[7,"מבונה","בנויה בכל טוב מבונה לשון פרי כדכתיב (בראשית ל) ואבנה גם אנכי ממנה:"],[7,"לבנו הקטן","לכנען:"],[7,"לבנו גדול","למצרים:"],[8,"על אחת משבעה","הרי שבע פעמים שבעים כורים הרי ד' מאות ותשעים ובמקום שאינו טרשים כחברון יש להוסיף עד חמש מאות ובברכותיה כתיב מאה שערים על אחת שבשאר שנים נתברך למאה מאה פעמים חמש מאות הרי חמשת ריבוא:"],[10,"סאה קמח","הוא אבק דק היוצא מן הנפה והחטין טחונין ברחיים של גריסין ואינן טחונין דקין והנפה מוציאה הקמח וקולטת פסולת ומחזיר מה שבנפה לריחים:"],[10,"סובין","שהמכתשת מוציאה כשלותתין חטין לסולת כותשין אותן במכתשת:"],[10,"מורסין","הן סובין היוצאין באחרונה:"],[10,"קיבוריא","קמח שאינו יפה שעושים ממנו פת קבור וקורין שאנדי\"ר:"],[10,"יאה משבחיתו בה בארעכון","יפה אתם משבחין אותה:"],[10,"בית סאה הניח לי אבא","בארץ ישראל:"],[11,"א\"ל ההוא בר אמוראה","אחד מבני האמורי אמר ליהודי תחלת ביאתו לארץ:"],[11,"הך תאלתא דקיימא אגודא דירדנא","דקל פלוני העומד על שפת הירדן:"],[11,"כמה גדריתו מינה","כמה תמרים אתם גודרים הימנו לקיטת תמרים קרויה גדירה בלשון [משנה וגוזרא בלשון] ארמי:"],[12,"אין עורו מחזיק את בשרו","שהעור כווץ וגומד לאחר הפשטו:"],[12,"אינה מחזקת פירותיה","עושה פירותיה מרובין עד אין מקום להצניען:"],[14,"פלטי לי מחדא","נצלתי מאחת מהן מן הקללות האמורות במקרא:"],[16,"נקט במצרא","יש מקום שאין גשר ומשליכין עץ על רוחב הנהר משפה לשפה ואינו רחב לילך עליו כי אם אוחז בידיו בחבל המתוח למעלה הימנו קשור שני ראשיו בשתי יתידות אחת מכאן ואחת מכאן בשני עברי הנהר:"],[16,"עמא פזיזא","עם בהול:"],[16,"דקדמיתו פומייכו לאודנייכו","מתחלתכם הייתם בהולים שהקדמתם נעשה לנשמע ועודכם בבהלתכם כבתחלה למהר לעשות דבר בלא עתו:"],[17,"כיפי","אלמוגים לישנא אחרינא כיפי דעכו סלעים:"],[17,"מתקן מתקליה","משוה ומתקן מכשולי העיר מחמת חיבת הארץ שהיתה חביבה עליו ומחזר שלא יצא שם רע על הדרכים:"]],[[17,"מנשק כיפי דעכו","משמע דמארץ ישראל הוא וכן בשילהי מי שאחזו (גיטין דף עו:) ותימה דבפ\"ק דגיטין (דף ב. ושם) תנן עכו כארץ ישראל לגיטין משמע דהוי מחוץ לארץ ומפרש בירושל' חציה בארץ וחציה בחוץ לארץ:"],[17,"רבי חנינא הוה מתקל מתקליה","פירוש שוקל אבנים ומוצאן קלות אמר עדיין לא נכנסתי לארץ ישראל כיון ששקלן ומצאן כבידות אמר כבר נכנסתי לארץ ישראל וכן מפרש בתנחומא בפרשת שלח לך כשעלה ר' חנינא הגדול מבבל בקש לידע אם נכנס לא\"י והיה שוקל אבנים כל זמן שהיו קלות אמר עדיין לא נכנסתי לארץ ישראל כיון שמצאן כבידות אמר אין אלו אלא אבני ארץ ישראל והיה מנשקן וקרא עליהן את הפסוק הזה כי רצו עבדיך את אבניה:"]]],[["קיימי משמשא לטולא ומטולא לשמשא ר' חייא בר גמדא מיגנדר בעפרה שנאמר (תהלים קב, טו) כי רצו עבדיך את אבניה ואת עפרה יחוננו","אמר רבי זירא אמר רבי ירמיה בר אבא דור שבן דוד בא קטיגוריא בתלמידי חכמים כי אמריתה קמיה דשמואל אמר צירוף אחר צירוף שנאמר (ישעיהו ו, יג) ועוד בה עשיריה ושבה והיתה לבער תני רב יוסף בזוזי ובזוזי דבזוזי","אמר רב חייא בר אשי אמר רב עתידין כל אילני סרק שבארץ ישראל שיטענו פירות שנאמר (יואל ב, כב) כי עץ נשא פריו תאנה וגפן נתנו חילם:","\u0001הדרן עלך שני דייני גזירות וסליקא לה מסכת כתובות\u0002"],[[0,"קיימי משמשא לטולא","כשהשמש הגיע למקום שהן יושבין וגורסין וחמה מקדרת עליהן עומדין משם לישב בצל ובימי הצנה עומדין מן הצל ויושבין בחמה כדי שלא יוכלו להתרעם על ישיבת ארץ ישראל:"],[0,"","כי רצו עבדיך את אבניה ואת עפרה יחוננו:"],[1,"קטיגוריא","הרבה מסטינים ומלמדים חובה יעמדו עליהם:"],[1,"צירוף אחר צירוף","גזירות על גזירות:"],[1,"ועוד בה עשיריה","כשתשעה החלקים יהיו אבודין ולא נותר כי אם העשירית אף היא תשוב והיתה לבער:"],[1,"בזוזי ובזוזי דבזוזי","שוללים אחר שוללים:"],[2,"כי עץ נשא פריו","מדכתיב תאנה וגפן נתנו חילם הרי עץ פרי אמור מה תלמוד לומר כי עץ נשא פריו אף אילני סרק ישאו פרי:"],[3,"","הדרן עלך שני דייני גזירות"]],[[1,"דור שבן דוד בא","איידי דאיירי בברכת העולם הבא דהיינו לימות המשיח נקט לה נמי הכא:"],[2,"עתידין כל אילני סרק שבארץ ישראל שיטענו פירות כו'","לפי שרוצה לסיים בדבר טוב נקט לה הכא ולא קאמרה לעיל דאיירי בהני מילי:"],[3,"","הדרן עלך שני דייני גזירות"]]]]};
